const SEARCH_DEFAULT_RESULT_LIMIT: usize = 50;
const SEARCH_MAX_RESULT_LIMIT: usize = 100;
const SEARCH_SNIPPET_LIMIT_BYTES: usize = 160;
const WORKSPACE_SEARCH_MAX_FILE_BYTES: u64 = 256 * 1024;
const PALETTE_RESULT_LIMIT: usize = 50;
const TREE_SITTER_OVERLAY_CACHE_MAX_ENTRIES: usize = 32;

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct TreeSitterOverlayCacheKey {
    path: String,
    text_hash: u64,
    text_len: usize,
}

#[derive(Debug, Default)]
struct TreeSitterOverlayCache {
    entries: HashMap<TreeSitterOverlayCacheKey, Vec<TreeSitterHighlightCapture>>,
    insertion_order: VecDeque<TreeSitterOverlayCacheKey>,
}

impl TreeSitterOverlayCache {
    fn get(&self, key: &TreeSitterOverlayCacheKey) -> Option<&Vec<TreeSitterHighlightCapture>> {
        self.entries.get(key)
    }

    fn insert_if_absent(
        &mut self,
        key: TreeSitterOverlayCacheKey,
        captures: Vec<TreeSitterHighlightCapture>,
    ) {
        if self.entries.contains_key(&key) {
            return;
        }
        if self.entries.len() >= TREE_SITTER_OVERLAY_CACHE_MAX_ENTRIES {
            while let Some(evicted) = self.insertion_order.pop_front() {
                if self.entries.remove(&evicted).is_some() {
                    break;
                }
            }
        }
        self.insertion_order.push_back(key.clone());
        self.entries.insert(key, captures);
    }
}

fn tree_sitter_overlay_cache() -> &'static Mutex<TreeSitterOverlayCache> {
    static CACHE: OnceLock<Mutex<TreeSitterOverlayCache>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(TreeSitterOverlayCache::default()))
}

fn tree_sitter_overlay_cache_guard() -> MutexGuard<'static, TreeSitterOverlayCache> {
    match tree_sitter_overlay_cache().lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

fn tree_sitter_overlay_cache_key(path: &str, text: &str) -> TreeSitterOverlayCacheKey {
    let mut hasher = DefaultHasher::new();
    path.hash(&mut hasher);
    text.hash(&mut hasher);
    TreeSitterOverlayCacheKey {
        path: path.to_string(),
        text_hash: hasher.finish(),
        text_len: text.len(),
    }
}

#[derive(Debug, Clone)]
struct PaletteState {
    open: bool,
    mode: PaletteMode,
    query: String,
    scope: SearchScopeProjection,
    selected_index: usize,
    results: Vec<PaletteResult>,
    pending_confirmation: Option<PendingPaletteConfirmation>,
    next_confirmation_token: u64,
}

#[derive(Debug, Clone)]
struct PendingPaletteConfirmation {
    projection: legion_ui::PaletteConfirmationProjection,
    intent: CommandDispatchIntent,
}

impl PaletteState {
    fn projection(&self) -> PaletteProjection {
        PaletteProjection {
            open: self.open,
            mode: self.mode,
            query: self.query.clone(),
            scope: self.scope,
            selected_index: self.selected_index,
            results: self.results.clone(),
            pending_confirmation: self
                .pending_confirmation
                .as_ref()
                .map(|pending| pending.projection.clone()),
        }
    }

    fn close(&mut self) {
        self.open = false;
        self.selected_index = 0;
        self.results.clear();
        self.pending_confirmation = None;
    }

    fn next_confirmation_token(&mut self) -> u64 {
        let token = self.next_confirmation_token.max(1);
        self.next_confirmation_token = token.wrapping_add(1).max(1);
        token
    }

    fn clamp_selection(&mut self) {
        if self.results.is_empty() {
            self.selected_index = 0;
        } else {
            self.selected_index = self.selected_index.min(self.results.len() - 1);
        }
    }

    fn select_first_available_command(&mut self) {
        self.selected_index = self
            .results
            .iter()
            .position(|result| result.disabled_reason.is_none())
            .unwrap_or(self.results.len());
    }
}

impl Default for PaletteState {
    fn default() -> Self {
        Self {
            open: false,
            mode: PaletteMode::File,
            query: String::new(),
            scope: SearchScopeProjection::ActiveFile,
            selected_index: 0,
            results: Vec::new(),
            pending_confirmation: None,
            next_confirmation_token: 1,
        }
    }
}

#[derive(Debug, Clone)]
struct PaletteScoredResult {
    score: i32,
    result: PaletteResult,
}

#[derive(Debug, Clone, Copy)]
struct PaletteCommandSpec {
    id: &'static str,
    title: &'static str,
    detail: &'static str,
    shortcut_label: Option<&'static str>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum PaletteCommandOperands {
    Branch(String),
    WorktreePath(String),
    CommitMessage(String),
    StashMessage(Option<String>),
    NewWorktree {
        branch: String,
        worktree_path: String,
    },
}

impl PaletteCommandOperands {
    fn detail(&self, command_id: &str) -> String {
        match (command_id, self) {
            ("git-switch-branch", Self::Branch(branch)) => {
                format!("Switch to branch ‘{branch}’")
            }
            ("git-create-branch", Self::Branch(branch)) => {
                format!("Create and switch to branch ‘{branch}’")
            }
            ("git-delete-branch", Self::Branch(branch)) => {
                format!("Delete branch ‘{branch}’")
            }
            ("git-remove-worktree", Self::WorktreePath(path)) => {
                format!("Remove worktree ‘{path}’")
            }
            ("git-commit", Self::CommitMessage(message)) => {
                format!("Commit staged changes as ‘{message}’")
            }
            ("git-stash", Self::StashMessage(Some(message))) => {
                format!("Stash changes as ‘{message}’")
            }
            ("git-stash", Self::StashMessage(None)) => "Stash local changes".to_string(),
            (
                "git-new-worktree",
                Self::NewWorktree {
                    branch,
                    worktree_path,
                },
            ) => format!("Create worktree ‘{worktree_path}’ from branch ‘{branch}’"),
            _ => String::new(),
        }
    }

    fn values(&self) -> Vec<String> {
        match self {
            Self::Branch(branch) => vec![branch.clone()],
            Self::WorktreePath(path) => vec![path.clone()],
            Self::CommitMessage(message) => vec![message.clone()],
            Self::StashMessage(message) => message.iter().cloned().collect(),
            Self::NewWorktree {
                branch,
                worktree_path,
            } => vec![branch.clone(), worktree_path.clone()],
        }
    }
}

fn argument_command_prefixes(command_id: &str) -> &'static [&'static str] {
    match command_id {
        "git-switch-branch" => &["git switch branch", "git: switch branch"],
        "git-create-branch" => &["git create branch", "git: create branch"],
        "git-delete-branch" => &["git delete branch", "git: delete branch"],
        "git-remove-worktree" => &["git remove worktree", "git: remove worktree"],
        "git-new-worktree" => &["git new worktree", "git: new worktree"],
        "git-commit" => &["git commit", "git: commit staged changes"],
        "git-stash" => &["git stash", "git: stash changes"],
        _ => &[],
    }
}

fn match_argument_command_prefix<'a>(
    query: &'a str,
    command_id: &str,
) -> Option<(&'static str, &'a str)> {
    let query = query.trim();
    argument_command_prefixes(command_id)
        .iter()
        .find_map(|prefix| {
            let head = query.get(..prefix.len())?;
            if !head.eq_ignore_ascii_case(prefix) {
                return None;
            }
            let remainder = query.get(prefix.len()..)?;
            (remainder.is_empty() || remainder.starts_with(char::is_whitespace))
                .then(|| (*prefix, remainder.trim()))
        })
}

fn strip_argument_command_prefix<'a>(query: &'a str, command_id: &str) -> Option<&'a str> {
    match_argument_command_prefix(query, command_id).map(|(_, remainder)| remainder)
}

fn parse_palette_command_operands(
    command_id: &str,
    query: &str,
) -> Option<Result<PaletteCommandOperands, &'static str>> {
    let missing = match command_id {
        "git-switch-branch" | "git-create-branch" | "git-delete-branch" => "Enter a branch name",
        "git-remove-worktree" => "Enter a worktree path",
        "git-new-worktree" => "Enter a branch and worktree path",
        "git-commit" => "Enter a commit message",
        "git-stash" => "Enter a stash message",
        _ => return None,
    };
    let Some(operands) = strip_argument_command_prefix(query, command_id) else {
        return Some(Err(missing));
    };
    if command_id == "git-stash" && operands.is_empty() {
        return Some(Ok(PaletteCommandOperands::StashMessage(None)));
    }
    if operands.is_empty() {
        return Some(Err(missing));
    }
    Some(match command_id {
        "git-switch-branch" | "git-create-branch" | "git-delete-branch" => {
            Ok(PaletteCommandOperands::Branch(operands.to_string()))
        }
        "git-remove-worktree" => Ok(PaletteCommandOperands::WorktreePath(operands.to_string())),
        "git-commit" => Ok(PaletteCommandOperands::CommitMessage(operands.to_string())),
        "git-stash" => Ok(PaletteCommandOperands::StashMessage(Some(
            operands.to_string(),
        ))),
        "git-new-worktree" => {
            let split = operands.find(char::is_whitespace);
            let Some(split) = split else {
                return Some(Err(missing));
            };
            let branch = operands[..split].trim();
            let worktree_path = operands[split..].trim();
            if branch.is_empty() || worktree_path.is_empty() {
                Err(missing)
            } else {
                Ok(PaletteCommandOperands::NewWorktree {
                    branch: branch.to_string(),
                    worktree_path: worktree_path.to_string(),
                })
            }
        }
        _ => unreachable!("argument commands are matched above"),
    })
}

fn palette_command_requires_confirmation(result_id: &str) -> bool {
    matches!(
        result_id.strip_prefix("command:").unwrap_or(result_id),
        "git-switch-branch"
            | "git-create-branch"
            | "git-delete-branch"
            | "git-prune-worktrees"
            | "git-remove-worktree"
            | "git-new-worktree"
            | "preferences-settings-reset"
    )
}

/// App-level composition errors.
#[derive(Debug, Error)]
pub enum AppCompositionError {
    /// Workspace operation failed.
    #[error(transparent)]
    Workspace(#[from] WorkspaceError),
    /// Editor operation failed.
    #[error(transparent)]
    Editor(#[from] EditorError),
    /// Protocol-port operation failed.
    #[error("protocol error: {0:?}")]
    Protocol(ProtocolError),
    /// No active workspace.
    #[error("workspace is not open")]
    WorkspaceNotOpen,
    /// No active file in composition.
    #[error("active file is not selected")]
    ActiveFileMissing,
    /// Active buffer not initialized for selected file.
    #[error("active buffer is not open")]
    ActiveBufferMissing,
    /// UI command targeted a buffer other than the active application buffer.
    #[error("command targeted buffer {target:?}, but active buffer is {active:?}")]
    BufferMismatch {
        /// Targeted buffer id.
        target: BufferId,
        /// Active buffer id.
        active: Option<BufferId>,
    },
    /// UI command targeted a buffer that is not open in the app tab set.
    #[error("buffer {0:?} is not open")]
    BufferNotOpen(BufferId),
    /// Dirty-close cancellation targeted a buffer with no active dirty-close prompt.
    #[error("dirty-close prompt is not active for buffer {0:?}")]
    DirtyClosePromptMissing(BufferId),
    /// UI proposal intent targeted a proposal other than the app-owned proposal being routed.
    #[error("proposal intent targeted {target:?}, but routed proposal is {active:?}")]
    ProposalIntentMismatch {
        /// Targeted proposal id.
        target: ProposalId,
        /// App-owned proposal id available for routing.
        active: Option<ProposalId>,
    },
    /// UI proposal intent requires an app-owned proposal object for routing.
    #[error("proposal intent requires an app-owned proposal")]
    ProposalIntentMissingProposal,
    /// Proposal-mediated save did not apply.
    #[error("save proposal did not apply: {0:?}")]
    SaveProposalRejected(Box<ProposalResponse>),
    /// Phase 4 AI runtime refused or failed a metadata-only step.
    #[error("phase 4 AI runtime failed: {0}")]
    AiRuntime(String),
    /// Requested Phase 4 AI run does not exist.
    #[error("phase 4 AI run not found: {run_id}")]
    AiRunMissing {
        /// Missing run identifier.
        run_id: String,
    },
    /// Collaboration runtime or app gate rejected a request.
    #[error("collaboration request failed: {0}")]
    Collaboration(String),
    /// Remote runtime or app gate rejected a request.
    #[error("remote request failed: {0}")]
    Remote(String),
    /// Language tooling workflow failed.
    #[error("language tooling request failed: {0}")]
    LanguageTooling(String),
    /// Terminal workflow failed.
    #[error("terminal request failed: {0}")]
    Terminal(String),
    /// Debug workflow failed.
    #[error("debug request failed: {0}")]
    Debug(String),
    /// Legion workflow orchestration failed at the app authority boundary.
    #[error("legion workflow request failed: {0}")]
    LegionWorkflow(String),
    /// Search query validation failed.
    #[error("search validation failed: {0}")]
    SearchValidation(String),
    /// Durable checkpoint operation failed.
    #[error("checkpoint operation failed: {0}")]
    Checkpoint(String),
    /// Operation denied because the workspace is untrusted.
    #[error("workspace not trusted: {0}")]
    WorkspaceNotTrusted(String),
}

/// Product-mode authority for app-owned AI dispatch.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AppProductMode {
    /// Deterministic local/manual mode; AI dispatch is rejected.
    Manual,
    /// Inline assist and assisted proposal/explain dispatch are enabled.
    Assist,
    /// Delegated task mode; includes Assist-level dispatch.
    Delegate,
    /// Automation mode; includes Assist-level dispatch.
    Automate,
}

impl AppProductMode {
    fn allows_assist(self) -> bool {
        self.to_product_mode()
            .allows_runtime_surface(legion_protocol::ProductRuntimeSurface::AssistedAi)
    }

    fn allows_delegate(self) -> bool {
        self.to_product_mode()
            .allows_runtime_surface(legion_protocol::ProductRuntimeSurface::DelegatedTask)
    }

    fn allows_automate(self) -> bool {
        self.to_product_mode()
            .allows_runtime_surface(legion_protocol::ProductRuntimeSurface::Automation)
    }

    /// Convert the app authority enum into the shared protocol product mode.
    pub fn to_product_mode(self) -> legion_protocol::ProductMode {
        match self {
            Self::Manual => legion_protocol::ProductMode::Manual,
            Self::Assist => legion_protocol::ProductMode::Assist,
            Self::Delegate => legion_protocol::ProductMode::Delegates,
            Self::Automate => legion_protocol::ProductMode::LegionWorkflows,
        }
    }

    /// Convert a UI dock/product mode into the app authority enum.
    pub fn from_dock_mode(mode: DockMode) -> Self {
        match mode {
            DockMode::Manual => Self::Manual,
            DockMode::Assist => Self::Assist,
            DockMode::Delegate => Self::Delegate,
            DockMode::Automate => Self::Automate,
        }
    }

    /// Convert the app authority enum into a UI dock/product mode.
    pub fn to_dock_mode(self) -> DockMode {
        match self {
            Self::Manual => DockMode::Manual,
            Self::Assist => DockMode::Assist,
            Self::Delegate => DockMode::Delegate,
            Self::Automate => DockMode::Automate,
        }
    }
}

#[cfg(test)]
mod daily_editing_save_all_internal_tests {
    use super::*;

    #[test]
    fn daily_editing_save_all_missing_metadata_records_buffer_error() {
        let mut app = AppComposition::new();
        let orphaned_buffer = BufferId(9001);
        app.active_documents.open_tabs.push(orphaned_buffer);

        let outcome = app.save_all().expect("save-all records metadata error");
        assert_eq!(outcome.status, AppSaveAllStatus::Rejected);
        assert_eq!(outcome.saved_count, 0);
        assert_eq!(outcome.rejected_count, 1);
        assert_eq!(outcome.results.len(), 1);

        let item = &outcome.results[0];
        assert_eq!(item.buffer_id, orphaned_buffer);
        assert_eq!(item.status, AppSaveAllItemStatus::MetadataMissing);
        assert!(item.outcome.is_none());
        assert!(item.final_dirty);
        let metadata = item
            .rejection_metadata
            .as_ref()
            .expect("metadata failure summary");
        assert_eq!(metadata.response_kind, "MetadataMissing");
        assert_eq!(metadata.diagnostic_codes, vec!["save_all.metadata_missing"]);
    }

    #[test]
    fn excerpt_surface_projection_carries_source_buffer_anchors() {
        let mut app = AppComposition::new();

        let buffer_a = app
            .editor
            .open_buffer(
                WorkspaceId(7),
                FileId(11),
                "src/alpha.rs",
                "alpha\nfn alpha() {}\n",
            )
            .expect("open first buffer");
        let opened_a = OpenedFileText {
            identity: FileIdentity {
                file_id: FileId(11),
                workspace_id: WorkspaceId(7),
                canonical_path: CanonicalPath("src/alpha.rs".to_string()),
                content_version: FileContentVersion(1),
                content_hash: Some("hash-alpha".to_string()),
            },
            text: "alpha\nfn alpha() {}\n".to_string(),
            fingerprint: FileFingerprint {
                algorithm: "test".to_string(),
                value: "alpha".to_string(),
            },
            file_content_version: FileContentVersion(1),
            workspace_generation: WorkspaceGeneration(1),
            modified_at: None,
            file_length: Some(21),
            is_new_file: false,
        };
        app.active_documents.bind_opened_file(&opened_a, buffer_a);

        let buffer_b = app
            .editor
            .open_buffer(
                WorkspaceId(7),
                FileId(12),
                "src/beta.rs",
                "beta\nfn beta() {}\n",
            )
            .expect("open second buffer");
        let opened_b = OpenedFileText {
            identity: FileIdentity {
                file_id: FileId(12),
                workspace_id: WorkspaceId(7),
                canonical_path: CanonicalPath("src/beta.rs".to_string()),
                content_version: FileContentVersion(1),
                content_hash: Some("hash-beta".to_string()),
            },
            text: "beta\nfn beta() {}\n".to_string(),
            fingerprint: FileFingerprint {
                algorithm: "test".to_string(),
                value: "beta".to_string(),
            },
            file_content_version: FileContentVersion(1),
            workspace_generation: WorkspaceGeneration(1),
            modified_at: None,
            file_length: Some(18),
            is_new_file: false,
        };
        app.active_documents.bind_opened_file(&opened_b, buffer_b);

        let surface =
            ProjectionBuilder::excerpt_surface_projection(&app.active_documents, &app.editor);

        assert_eq!(surface.active_excerpt_id.as_deref(), Some("buffer:2"));
        assert_eq!(surface.sections.len(), 2);

        let first = &surface.sections[0];
        assert_eq!(first.excerpt_id, "buffer:1");
        assert_eq!(first.buffer_id, Some(buffer_a));
        assert_eq!(
            first.file_path.as_ref().map(|path| path.0.as_str()),
            Some("src/alpha.rs")
        );
        assert!(!first.dirty);
        assert!(!first.lines.is_empty());
        assert_eq!(first.lines[0].visible_text, "alpha");
        assert_eq!(first.lines[0].range.start.line, 0);

        let second = &surface.sections[1];
        assert_eq!(second.excerpt_id, "buffer:2");
        assert_eq!(second.buffer_id, Some(buffer_b));
        assert_eq!(
            second.file_path.as_ref().map(|path| path.0.as_str()),
            Some("src/beta.rs")
        );
        assert!(!second.dirty);
        assert!(!second.lines.is_empty());
    }
    #[test]
    fn terminal_shell_output_parser_strips_markers_and_extracts_metadata() {
        let parsed = legion_terminal::osc::parse_terminal_shell_output(
            "\x1b]7;file://localhost/tmp/workspace\x1b\\output\x1b]133;D;7\x1b\\",
        );

        assert_eq!(parsed.visible_output, "output");
        assert_eq!(parsed.cwd.as_deref(), Some("/tmp/workspace"));
        assert_eq!(parsed.exit_code, Some(7));
    }

    /// Regression for legion-smoke runs 28741840232 / 28747873556 (macos-latest).
    ///
    /// bash 3.2 delivered the zsh-deprecation banner, prompt, command echo,
    /// cargo output, AND the GP-1 exit marker in ONE PTY read chunk. The
    /// projection turned the whole chunk into ONE row capped at 240 chars,
    /// which silently hid everything past the cap — including the exit
    /// marker — from the projection and from scrollback search. A chunk is
    /// a transport unit, not a display row: multi-line chunks must become
    /// one row per line so the per-row cap only ever truncates a genuinely
    /// long single line.
    #[test]
    fn terminal_multi_line_output_chunk_splits_into_per_line_rows() {
        let mut workflow = TerminalWorkflow::default();
        // Verbatim shape of the macOS CI chunk (row[2] of the failure dump).
        let payload = "\r\nThe default interactive shell is now zsh.\r\n\
                       To update your account to use zsh, please run `chsh -s /bin/zsh`.\r\n\
                       For more details, please visit https://support.apple.com/kb/HT208050.\r\n\
                       bash-3.2$ sh '/var/folders/8j/sfr9qqcj73j4p6nhwcfpr0th0000gn/T/gp1_smoke_test_26652.sh'\r\n\
                       \r\nrunning 1 test\r\n.\r\n\
                       test result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.00s\r\n\
                       \r\nSMOKE_EXIT:0\r\nbash-3.2$ ";
        let marker_at = payload.find("SMOKE_EXIT:0").expect("marker in payload");
        assert!(
            marker_at > 240,
            "replay must place the marker past the per-row cap (found at {marker_at})"
        );
        let byte_count = payload.len() as u64;
        let chunk = legion_protocol::TerminalOutputChunk {
            session_id: TerminalSessionId(1),
            sequence: EventSequence(1),
            redacted_payload: payload.to_string(),
            byte_count,
            truncated: false,
            redaction: RedactionHint::MetadataOnly,
            schema_version: 1,
        };
        let shell_projection = legion_terminal::osc::TerminalShellProjection {
            visible_output: payload.to_string(),
            cwd: None,
            exit_code: None,
            boundary: None,
        };

        workflow.push_terminal_output(chunk, false, Some(&shell_projection));

        let rows = &workflow.projection.output_rows;
        assert!(
            rows.len() > 1,
            "multi-line chunk must produce one row per line, got {} row(s)",
            rows.len()
        );
        assert!(
            rows.iter()
                .any(|row| row.redacted_payload.contains("SMOKE_EXIT:0")),
            "line past the 240-char cap must survive as its own visible row; rows: {:?}",
            rows.iter()
                .map(|row| row.redacted_payload.as_str())
                .collect::<Vec<_>>()
        );
        // No row is a merged multi-line blob.
        assert!(
            rows.iter()
                .all(|row| !row.redacted_payload.trim_end_matches('\n').contains('\n')),
            "no projected row may contain interior newlines"
        );
    }

    /// Carriage-return redraws (bash 3.2 horizontal scroll, progress bars)
    /// overwrite the line in a real terminal; the projection must keep the
    /// final visible content of the line, not the concatenation of every
    /// redraw window.
    #[test]
    fn terminal_carriage_return_redraw_keeps_final_line_content() {
        let mut workflow = TerminalWorkflow::default();
        let payload = "Compiling 1/10\rCompiling 5/10\rCompiling 10/10 done\r\nfinished\r\n";
        let chunk = legion_protocol::TerminalOutputChunk {
            session_id: TerminalSessionId(1),
            sequence: EventSequence(1),
            redacted_payload: payload.to_string(),
            byte_count: payload.len() as u64,
            truncated: false,
            redaction: RedactionHint::MetadataOnly,
            schema_version: 1,
        };
        let shell_projection = legion_terminal::osc::TerminalShellProjection {
            visible_output: payload.to_string(),
            cwd: None,
            exit_code: None,
            boundary: None,
        };

        workflow.push_terminal_output(chunk, false, Some(&shell_projection));

        let payloads: Vec<&str> = workflow
            .projection
            .output_rows
            .iter()
            .map(|row| row.redacted_payload.as_str())
            .collect();
        assert_eq!(
            payloads,
            vec!["Compiling 10/10 done", "finished"],
            "last redraw wins per line; \\r\\n is a line ending, not a redraw"
        );
    }
}

