#[cfg(feature = "ai")]
/// Capability boundary for resolver-backed workflow workers.
///
/// Providers may draft proposal content, but they must not use tools that return
/// workspace source to the provider.  In particular, this broker is deliberately
/// narrower than the delegated runtime's general-purpose broker.
struct LegionWorkflowProposalOnlyCapabilityBroker;

#[cfg(feature = "ai")]
impl CapabilityBrokerPort for LegionWorkflowProposalOnlyCapabilityBroker {
    fn handle(&self, request: CapabilityRequest) -> ProtocolResult<CapabilityResponse> {
        let cap_id = match &request {
            CapabilityRequest::Request { capability_id, .. } => capability_id.clone(),
            _ => CapabilityId("unknown".to_string()),
        };
        let granted = cap_id.0 == "delegate.tool.edit-as-proposal";
        Ok(CapabilityResponse::Decision(CapabilityDecision {
            decision_id: CapabilityDecisionId(1),
            granted,
            capability: cap_id,
            reason: (!granted)
                .then(|| "workflow providers are restricted to proposal-only tools".to_string()),
        }))
    }
}

/// App-owned outcome for a delegated task execution attempt.
#[derive(Debug, Clone)]
pub enum AppDelegatedTaskExecutionOutcome {
    /// A matching plan contract was not found.
    PlanMissing {
        /// Missing plan identifier.
        plan_id: DelegatedTaskPlanId,
    },
    /// Execution reached a tool boundary and is waiting on explicit human permission.
    WaitingForToolPermission {
        /// Permission row that must be approved or denied.
        request: DelegatedTaskToolPermissionRequest,
    },
    /// Execution was denied by a fail-closed tool permission decision.
    Denied {
        /// Denying permission row.
        request: DelegatedTaskToolPermissionRequest,
    },
    /// Proposal-only output is ready for proposal lifecycle review.
    ProposalReady(Box<AssistedAiEditProposalOutput>),
}

/// Product-facing AI provider preference for Assist / Delegate composition paths.
///
/// **Local-first default (`Auto`):** try Ollama loopback when a fast TCP probe
/// succeeds, else Anthropic BYOK when credentials exist, else deterministic fixture.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum ProductAiProviderPreference {
    /// Local-first auto routing (Ollama → Anthropic → fixture).
    #[default]
    Auto,
    /// Force Ollama loopback when reachable; else fixture.
    Ollama,
    /// Force Anthropic when credentials exist; else fixture.
    Anthropic,
    /// Always use the offline deterministic fixture (CI / zero-egress).
    Deterministic,
}

impl ProductAiProviderPreference {
    /// Parse preference labels used by env (`LEGION_AI_PROVIDER`) and UI.
    pub fn parse(label: &str) -> Self {
        match label.trim().to_ascii_lowercase().as_str() {
            "ollama" | "local" => Self::Ollama,
            "anthropic" | "byok" | "claude" => Self::Anthropic,
            "deterministic" | "deterministic-local" | "fixture" | "offline" => Self::Deterministic,
            "auto" | "" => Self::Auto,
            _ => Self::Auto,
        }
    }

    /// Stable id for UI / status labels.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::Ollama => "ollama",
            Self::Anthropic => "anthropic",
            Self::Deterministic => "deterministic",
        }
    }

    /// Default preference from `LEGION_AI_PROVIDER` when set.
    ///
    /// Test builds default to [`Self::Deterministic`] rather than `Auto`.
    /// `Auto` probes loopback for a local model server, so with `Auto` the
    /// outcome of a test depends on whether the developer happens to have
    /// Ollama running — six tests in this workspace silently took the live
    /// path and failed the moment a model server was installed, which the
    /// roadmap actively asks developers to do. A test that wants a live
    /// provider must now say so explicitly via
    /// [`AppComposition::set_preferred_ai_provider`].
    pub fn from_env() -> Self {
        if let Ok(configured) = std::env::var("LEGION_AI_PROVIDER") {
            return Self::parse(&configured);
        }
        #[cfg(any(test, feature = "test-helpers"))]
        {
            Self::Deterministic
        }
        #[cfg(not(any(test, feature = "test-helpers")))]
        {
            Self::default()
        }
    }
}

/// Resolve Anthropic API key from env (preferred) or OS keyring BYOK storage.
///
/// Desktop `SetProviderApiKey` writes to the keyring; this path loads that secret
/// when `ANTHROPIC_API_KEY` (and Legion prefixes) are unset.
#[cfg(feature = "ai")]
fn resolve_anthropic_api_key() -> Option<String> {
    std::env::var("ANTHROPIC_API_KEY")
        .ok()
        .filter(|v| !v.trim().is_empty())
        .or_else(|| {
            std::env::var("LEGION_ANTHROPIC_API_KEY")
                .ok()
                .filter(|v| !v.trim().is_empty())
        })
        .or_else(|| {
            std::env::var("DEVIL_ANTHROPIC_API_KEY")
                .ok()
                .filter(|v| !v.trim().is_empty())
        })
        .or_else(|| {
            // Desktop SetProviderApiKey stores `anthropic:api_key`; also accept
            // legacy `ANTHROPIC_API_KEY` account names.
            load_provider_api_key(&OsKeyringSecretStore, "anthropic")
                .ok()
                .flatten()
        })
}

/// Resolve configured Anthropic base URL (proxy / self-hosted / production).
#[cfg(feature = "ai")]
fn anthropic_base_url_from_env() -> String {
    std::env::var("LEGION_ANTHROPIC_BASE_URL")
        .ok()
        .filter(|v| !v.trim().is_empty())
        .or_else(|| {
            std::env::var("DEVIL_ANTHROPIC_BASE_URL")
                .ok()
                .filter(|v| !v.trim().is_empty())
        })
        .or_else(|| {
            std::env::var("ANTHROPIC_BASE_URL")
                .ok()
                .filter(|v| !v.trim().is_empty())
        })
        .unwrap_or_else(|| "https://api.anthropic.com".to_string())
}

/// Build an Anthropic client from env, falling back to OS keyring BYOK storage.
///
/// Always honors configured base URL env vars; only the credential may come
/// from the keyring when process env keys are unset.
#[cfg(feature = "ai")]
fn anthropic_client_with_keyring_fallback() -> legion_ai_providers::AnthropicMessagesClient {
    use legion_ai_providers::{
        ANTHROPIC_PROVIDER_ID, AnthropicCredentialKind, AnthropicMessagesClient,
        ReqwestProviderHttpTransport,
    };

    let base_url = anthropic_base_url_from_env();
    if let Some(api_key) = resolve_anthropic_api_key() {
        return AnthropicMessagesClient::with_transport_kind(
            ANTHROPIC_PROVIDER_ID,
            base_url,
            Some(api_key),
            AnthropicCredentialKind::ApiKey,
            ReqwestProviderHttpTransport,
        );
    }
    // No explicit key: still use from_env so base URL + any remaining credential
    // sources stay consistent with the provider adapter.
    AnthropicMessagesClient::from_env(ANTHROPIC_PROVIDER_ID)
}

/// Fast TCP probe for Ollama loopback so CI/offline does not pay HTTP timeouts.
#[cfg(feature = "ai")]
fn ollama_loopback_reachable() -> bool {
    use std::net::{SocketAddr, TcpStream, ToSocketAddrs};
    use std::time::Duration;

    let base =
        std::env::var("OLLAMA_BASE_URL").unwrap_or_else(|_| "http://127.0.0.1:11434".to_string());
    let trimmed = base
        .trim()
        .trim_start_matches("http://")
        .trim_start_matches("https://")
        .trim_end_matches('/');
    let host_port = if trimmed.contains(':') {
        trimmed.to_string()
    } else {
        format!("{trimmed}:11434")
    };
    let Ok(mut addrs) = host_port.to_socket_addrs() else {
        return false;
    };
    let Some(addr) = addrs.next() else {
        return false;
    };
    // Guard against accidental remote probes in product auto mode.
    match addr {
        SocketAddr::V4(v4) if v4.ip().is_loopback() => {}
        SocketAddr::V6(v6) if v6.ip().is_loopback() => {}
        _ => return false,
    }
    TcpStream::connect_timeout(&addr, Duration::from_millis(150)).is_ok()
}

#[cfg(feature = "ai")]
fn ollama_model_label() -> String {
    std::env::var("OLLAMA_MODEL")
        .ok()
        .filter(|v| !v.trim().is_empty())
        .unwrap_or_else(|| "llama3.2".to_string())
}

/// One successful product chat completion (provider id, model, text, optional stream chunks).
/// Pure data — deliberately not `ai`-gated so the stream-sink/lane machinery keeps one
/// signature across feature configurations (no-`ai` builds simply never produce `Some`).
struct ProductChatCompletion {
    provider_id: String,
    model: String,
    text: String,
    /// Ordered text deltas when the provider streamed; otherwise a single full chunk.
    stream_chunks: Vec<String>,
    /// True when Anthropic (or another) SSE path produced multiple deltas.
    streamed: bool,
}

/// Product completion bound to the **authorized** live backend only.
///
/// Auto selects Ollama when loopback is reachable, otherwise Anthropic BYOK when a
/// key exists. Completion never falls through from an Ollama-authorized route to
/// Anthropic (or the reverse): that would bypass the capability/network decision
/// built for the selected backend. Offline / no-provider returns `None` for
/// fixture fallbacks.
///
/// Anthropic uses progressive Messages **SSE** when available (`on_delta` fires as
/// chunks arrive). Ollama remains a single-chunk completion.
#[cfg(feature = "ai")]
fn complete_product_chat(
    preference: ProductAiProviderPreference,
    system: &str,
    user: &str,
    max_tokens: u32,
    temperature: f32,
    mut on_delta: Option<&mut dyn FnMut(&str)>,
) -> Option<ProductChatCompletion> {
    use legion_ai::{ChatCompletionRequest, ChatMessage, ChatRole, ModelProvider};
    use legion_ai_providers::OllamaProvider;

    let backend = product_ai_selected_live_backend(preference)?;

    match backend {
        ProductAiLiveBackend::Ollama => {
            let model = ollama_model_label();
            let client = OllamaProvider::default();
            let request = ChatCompletionRequest {
                provider: "ollama".to_string(),
                model: model.clone(),
                messages: vec![
                    ChatMessage {
                        role: ChatRole::System,
                        content: system.to_string(),
                    },
                    ChatMessage {
                        role: ChatRole::User,
                        content: user.to_string(),
                    },
                ],
                max_tokens: Some(max_tokens),
                temperature: Some(temperature),
                metadata: Default::default(),
            };
            if let Ok(response) = client.complete(request)
                && !response.text.trim().is_empty()
            {
                let text = response.text.trim().to_string();
                if let Some(cb) = on_delta.as_mut() {
                    cb(&text);
                }
                return Some(ProductChatCompletion {
                    provider_id: "ollama".to_string(),
                    model: response.model,
                    stream_chunks: vec![text.clone()],
                    text,
                    streamed: false,
                });
            }
            None
        }
        ProductAiLiveBackend::Anthropic => {
            let client = anthropic_client_with_keyring_fallback();
            let request = ChatCompletionRequest {
                provider: "anthropic".to_string(),
                model: "claude-sonnet-4-20250514".to_string(),
                messages: vec![
                    ChatMessage {
                        role: ChatRole::System,
                        content: system.to_string(),
                    },
                    ChatMessage {
                        role: ChatRole::User,
                        content: user.to_string(),
                    },
                ],
                max_tokens: Some(max_tokens),
                temperature: Some(temperature),
                metadata: Default::default(),
            };
            // Progressive SSE: on_delta fires as text deltas arrive on the wire.
            let mut delta_sink = |text: &str| {
                if let Some(cb) = on_delta.as_mut() {
                    cb(text);
                }
            };
            if let Ok(chunks) = client.stream_text_deltas_with_callback(
                request.clone(),
                Default::default(),
                &mut delta_sink,
            ) {
                let chunks: Vec<String> = chunks.into_iter().filter(|d| !d.is_empty()).collect();
                let text = chunks.join("");
                if !text.trim().is_empty() {
                    let streamed = chunks.len() > 1;
                    return Some(ProductChatCompletion {
                        provider_id: "anthropic".to_string(),
                        model: request.model.clone(),
                        stream_chunks: if chunks.is_empty() {
                            vec![text.clone()]
                        } else {
                            chunks
                        },
                        text: text.trim().to_string(),
                        streamed,
                    });
                }
            }
            if let Ok(response) = client.complete(request)
                && !response.text.trim().is_empty()
            {
                let text = response.text.trim().to_string();
                if let Some(cb) = on_delta.as_mut() {
                    cb(&text);
                }
                return Some(ProductChatCompletion {
                    provider_id: "anthropic".to_string(),
                    model: response.model,
                    stream_chunks: vec![text.clone()],
                    text,
                    streamed: false,
                });
            }
            None
        }
    }
}

/// Result of resolving assist edit proposal body text (live model or fixture).
