/// Background job result for non-blocking product AI generation.
#[derive(Debug, Clone)]
struct ProductAiBackgroundResult {
    /// Delegate chat assistant message to finalize; empty when this is Assist.
    assistant_message_id: String,
    content_label: String,
    stream: Option<ProductAiStreamProjection>,
    /// When set, `poll_product_ai_stream` registers an Assist proposal on the app thread.
    assist_proposal: Option<AssistedEditProposalSource>,
}

/// Context retained while a live Assist proposal streams on a worker thread.
///
/// Authorization and agent Planning→Proposing run on the UI thread; completion
/// text arrives later so the renderer can poll progressive deltas and remain
/// responsive. Proposal registration happens on poll after the worker finishes.
#[derive(Debug, Clone)]
struct PendingAssistProposalJob {
    run_id: legion_protocol::AgentRunId,
    route_id: String,
    operation_class: legion_protocol::AssistedAiOperationClass,
    provider_class: legion_protocol::AssistedAiProviderClass,
    provider_route_request: legion_protocol::AssistedAiProviderRouteRequest,
    route_response: legion_protocol::AssistedAiProviderRouteResponse,
    context_manifest_projection: legion_protocol::ContextManifestProjection,
    privacy_inspector_projection: legion_protocol::PrivacyInspectorProjection,
    permission_budget_projection: legion_protocol::PermissionBudgetProjection,
    generated_at: TimestampMillis,
    event_context: EventContext,
    principal: PrincipalId,
    file_id: FileId,
    preconditions: ProposalVersionPreconditions,
    agent: AgentRuntime,
}

/// Shared live stream sink updated as SSE deltas arrive (background or progressive).
#[derive(Debug, Default)]
struct LiveProductAiStreamSink {
    projection: Mutex<ProductAiStreamProjection>,
    in_flight: std::sync::atomic::AtomicBool,
    /// Completed background chat results waiting to be applied on the app thread.
    pending_results: Mutex<VecDeque<ProductAiBackgroundResult>>,
}

struct ProductAiLaneReservation {
    sink: Arc<LiveProductAiStreamSink>,
    operation: &'static str,
    armed: bool,
}

impl ProductAiLaneReservation {
    fn try_acquire(
        sink: Arc<LiveProductAiStreamSink>,
        operation: &'static str,
        provider_hint: &str,
        model_hint: &str,
    ) -> Option<Self> {
        if !sink.try_begin(operation, provider_hint, model_hint) {
            return None;
        }
        Some(Self {
            sink,
            operation,
            armed: true,
        })
    }

    fn sink(&self) -> Arc<LiveProductAiStreamSink> {
        self.sink.clone()
    }

    fn finish(mut self, completion: Option<&ProductChatCompletion>) {
        self.armed = false;
        self.sink.finish(completion, self.operation);
    }

    fn finish_background(
        mut self,
        result: ProductAiBackgroundResult,
        completion: Option<&ProductChatCompletion>,
    ) {
        self.armed = false;
        self.sink
            .finish_background(result, completion, self.operation);
    }
}

impl Drop for ProductAiLaneReservation {
    fn drop(&mut self) {
        if self.armed {
            self.sink.finish(None, self.operation);
        }
    }
}

impl LiveProductAiStreamSink {
    fn try_begin(&self, operation: &str, provider_hint: &str, model_hint: &str) -> bool {
        let Ok(pending) = self.pending_results.lock() else {
            return false;
        };
        if !pending.is_empty()
            || self
                .in_flight
                .compare_exchange(
                    false,
                    true,
                    std::sync::atomic::Ordering::SeqCst,
                    std::sync::atomic::Ordering::SeqCst,
                )
                .is_err()
        {
            return false;
        }
        let Ok(mut guard) = self.projection.lock() else {
            self.in_flight
                .store(false, std::sync::atomic::Ordering::SeqCst);
            return false;
        };
        *guard = ProductAiStreamProjection {
            provider_id: provider_hint.to_string(),
            model: model_hint.to_string(),
            operation: operation.to_string(),
            chunks: Vec::new(),
            streamed: false,
            in_flight: true,
            text_preview: String::new(),
        };
        true
    }

    fn push_delta(&self, delta: &str) {
        if delta.is_empty() {
            return;
        }
        if let Ok(mut guard) = self.projection.lock() {
            guard.chunks.push(delta.to_string());
            guard.streamed = guard.chunks.len() > 1 || guard.streamed;
            guard.in_flight = true;
            let joined = guard.chunks.join("");
            guard.text_preview = joined.chars().take(480).collect();
        }
    }

    fn finish(&self, completion: Option<&ProductChatCompletion>, operation: &str) {
        if let Ok(mut guard) = self.projection.lock() {
            if let Some(completion) = completion {
                *guard = product_stream_from_completion(completion, operation);
            } else {
                guard.in_flight = false;
            }
        }
        self.in_flight
            .store(false, std::sync::atomic::Ordering::SeqCst);
    }

    fn snapshot(&self) -> ProductAiStreamProjection {
        self.projection
            .lock()
            .map(|g| g.clone())
            .unwrap_or_default()
    }

    fn is_in_flight(&self) -> bool {
        self.in_flight.load(std::sync::atomic::Ordering::SeqCst)
    }

    fn has_pending_results(&self) -> bool {
        self.pending_results
            .lock()
            .map(|queue| !queue.is_empty())
            .unwrap_or(true)
    }

    fn mode_allows_active_operation(&self, mode: AppProductMode) -> bool {
        if !self.is_in_flight() && !self.has_pending_results() {
            return true;
        }
        let Ok(guard) = self.projection.lock() else {
            return false;
        };
        match guard.operation.as_str() {
            "delegate.chat" => mode.allows_delegate(),
            "assist.proposal" => mode.allows_assist(),
            _ => false,
        }
    }

    /// Publish the final stream projection and enqueue its app-thread result
    /// before making the operation observable as no longer in flight. This
    /// ordering closes the Manual-transition race between provider completion
    /// and result handoff.
    fn finish_background(
        &self,
        result: ProductAiBackgroundResult,
        completion: Option<&ProductChatCompletion>,
        operation: &str,
    ) {
        let Ok(mut queue) = self.pending_results.lock() else {
            return;
        };
        if let Ok(mut guard) = self.projection.lock() {
            if let Some(completion) = completion {
                *guard = product_stream_from_completion(completion, operation);
            } else {
                guard.in_flight = false;
            }
        }
        queue.push_back(result);
        self.in_flight
            .store(false, std::sync::atomic::Ordering::SeqCst);
    }

    fn take_background_results(&self) -> Vec<ProductAiBackgroundResult> {
        self.pending_results
            .lock()
            .map(|mut queue| queue.drain(..).collect())
            .unwrap_or_default()
    }
}

/// Bound ghost-text bytes for live inline predictions (matches protocol max).
#[cfg(feature = "ai")]
fn bound_inline_prediction_text(text: &str, max_bytes: u32) -> String {
    let mut end = text.len().min(max_bytes as usize);
    while end > 0 && !text.is_char_boundary(end) {
        end -= 1;
    }
    text[..end].to_string()
}

/// Build an `InlinePredictionResult` from a live product completion when available.
///
/// Real adapters often lack `predict_inline`; we map a short chat completion into
/// the ghost-text result shape. Falls back to `None` for deterministic offline.
#[cfg(feature = "ai")]
fn try_live_product_inline_prediction(
    preference: ProductAiProviderPreference,
    metadata: &InlinePredictionRequestMetadata,
    buffer_excerpt: &str,
) -> Option<InlinePredictionResult> {
    let max_bytes = metadata
        .max_prediction_bytes
        .clamp(1, INLINE_PREDICTION_MAX_GHOST_TEXT_BYTES);
    let system = format!(
        "You are Legion Assist inline prediction. Reply with ONLY the short text to insert at the cursor (ghost text). \
No markdown fences, no quotes, no explanation. Prefer a single line. Max ~{max_bytes} bytes."
    );
    let user = format!(
        "Language: {}\nCursor line {} character {}\nBuffer excerpt:\n{buffer_excerpt}",
        metadata.language_id.0, metadata.cursor.line, metadata.cursor.character
    );
    let completion = complete_product_chat(preference, &system, &user, 128, 0.1, None)?;
    let text = bound_inline_prediction_text(completion.text.trim(), max_bytes);
    if text.is_empty() {
        return None;
    }
    let byte_len = text.len() as u32;
    let line_count = text.bytes().filter(|byte| *byte == b'\n').count() as u32 + 1;
    let mut provider = metadata.provider.clone();
    provider.provider_id = completion.provider_id.clone();
    provider.model_label = completion.model.clone();
    provider.provider_class = if completion.provider_id == "ollama" {
        AssistedAiProviderClass::LocalLoopback
    } else {
        AssistedAiProviderClass::ByokRemote
    };
    provider.operation_class = AssistedAiOperationClass::InlinePrediction;
    provider.invocation_state = AssistedAiProviderInvocationState::Completed;
    provider.health_labels = vec![
        if completion.provider_id == "ollama" {
            "local".to_string()
        } else {
            "byok".to_string()
        },
        completion.provider_id.clone(),
    ];
    provider.cost_labels = vec![if completion.provider_id == "ollama" {
        "local".to_string()
    } else {
        "remote".to_string()
    }];
    provider.latency = InlinePredictionLatencyMetadata {
        queued_ms: 0,
        inference_ms: 0,
        total_ms: 0,
        timed_out: false,
    };
    Some(InlinePredictionResult {
        result_id: InlinePredictionResultId(format!("{}:result", metadata.request_id.0)),
        request_id: metadata.request_id.clone(),
        state: InlinePredictionResultState::Available,
        retention: InlinePredictionRetention::EphemeralDisplay,
        insert_range: ProtocolTextRange {
            start: metadata.cursor,
            end: metadata.cursor,
        },
        ghost_text: Some(InlinePredictionGhostText {
            text: text.clone(),
            byte_len,
            line_count,
            text_fingerprint: FileFingerprint {
                algorithm: format!("{}-inline-v1", completion.provider_id),
                value: format!(
                    "{}:{}:{}",
                    metadata.language_id.0, metadata.cursor.line, byte_len
                ),
            },
        }),
        fingerprint: metadata.fingerprint.clone(),
        freshness: InlinePredictionFreshness::fresh(metadata.schema_version),
        provider,
        refusal: None,
        generated_at: metadata.requested_at,
        expires_at: None,
        redaction_hints: vec![RedactionHint::MetadataOnly],
        schema_version: metadata.schema_version,
    })
}

/// App-owned outcome for a delegated task loop run started via `StartDelegatedTask`.
#[derive(Debug, Clone)]
pub enum AppDelegatedTaskOutcome {
    /// The agent loop completed naturally; proposals may be empty if no edits were proposed.
    Completed {
        /// Final text from the model.
        final_message: String,
        /// Edit proposals extracted from the sandbox worktree.
        proposals: Vec<AssistedAiEditProposalOutput>,
        /// Audit steps recorded during the run.
        audit_steps: Vec<legion_protocol::DelegatedTaskLoopStepRecord>,
    },
    /// Budget was exhausted before the loop completed.
    BudgetExhausted {
        /// Human-readable reason label.
        reason: String,
        /// Audit steps recorded before exhaustion.
        audit_steps: Vec<legion_protocol::DelegatedTaskLoopStepRecord>,
    },
    /// A non-retryable policy denial stopped the loop.
    Blocked {
        /// Human-readable reason label.
        reason: String,
        /// Audit steps recorded before the loop was blocked.
        audit_steps: Vec<legion_protocol::DelegatedTaskLoopStepRecord>,
    },
    /// The idle-turn governor ended a run that had stopped making progress.
    ///
    /// Carries proposals, unlike `Blocked` and `BudgetExhausted`: the run
    /// stopped because the model went in circles, which says nothing about
    /// the edits it produced before that.
    StoppedNoProgress {
        /// Human-readable reason label.
        reason: String,
        /// Edit proposals produced before the run stalled.
        proposals: Vec<AssistedAiEditProposalOutput>,
        /// Audit steps recorded before the stop.
        audit_steps: Vec<legion_protocol::DelegatedTaskLoopStepRecord>,
    },
    /// The loop was cancelled via the cancellation probe.
    Cancelled,
    /// Sandbox allocation failed before the loop could start.
    SandboxAllocationFailed {
        /// Human-readable reason label.
        reason: String,
    },
}

#[cfg(feature = "ai")]
type DelegatedTaskJoinHandle =
    std::thread::JoinHandle<Result<DelegatedTaskRunCompletion, AppCompositionError>>;

#[cfg(feature = "ai")]
struct SupervisedDelegatedTaskRun {
    owner_id: uuid::Uuid,
    join_handle: DelegatedTaskJoinHandle,
}

#[cfg(feature = "ai")]
struct DelegatedTaskHandleSupervisor {
    sender: std::sync::mpsc::Sender<SupervisedDelegatedTaskRun>,
    _thread_handle: std::thread::JoinHandle<()>,
}

#[cfg(feature = "ai")]
static DELEGATED_TASK_HANDLE_SUPERVISOR: OnceLock<DelegatedTaskHandleSupervisor> = OnceLock::new();

#[cfg(feature = "ai")]
static DELEGATED_TASK_HANDLE_SUPERVISOR_INIT: Mutex<()> = Mutex::new(());

#[cfg(feature = "ai")]
static DELEGATED_TASK_HANDLE_FALLBACK: OnceLock<Mutex<Vec<SupervisedDelegatedTaskRun>>> =
    OnceLock::new();

#[cfg(all(feature = "ai", any(test, feature = "test-helpers")))]
#[derive(Default)]
struct DelegatedTaskSupervisorTestObservations {
    handed_off: HashSet<uuid::Uuid>,
    reaped: HashSet<uuid::Uuid>,
}

#[cfg(all(feature = "ai", any(test, feature = "test-helpers")))]
static DELEGATED_TASK_SUPERVISOR_TEST_OBSERVATIONS: OnceLock<
    Mutex<DelegatedTaskSupervisorTestObservations>,
> = OnceLock::new();

#[cfg(feature = "ai")]
fn retain_delegated_task_handle(run: SupervisedDelegatedTaskRun) {
    DELEGATED_TASK_HANDLE_FALLBACK
        .get_or_init(|| Mutex::new(Vec::new()))
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .push(run);
}

#[cfg(all(feature = "ai", any(test, feature = "test-helpers")))]
fn record_delegated_task_handoff(owner_id: uuid::Uuid) {
    DELEGATED_TASK_SUPERVISOR_TEST_OBSERVATIONS
        .get_or_init(|| Mutex::new(DelegatedTaskSupervisorTestObservations::default()))
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .handed_off
        .insert(owner_id);
}

#[cfg(all(feature = "ai", any(test, feature = "test-helpers")))]
fn record_delegated_task_reaped(owner_id: uuid::Uuid) {
    DELEGATED_TASK_SUPERVISOR_TEST_OBSERVATIONS
        .get_or_init(|| Mutex::new(DelegatedTaskSupervisorTestObservations::default()))
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .reaped
        .insert(owner_id);
}

#[cfg(feature = "ai")]
fn run_delegated_task_handle_supervisor(
    receiver: std::sync::mpsc::Receiver<SupervisedDelegatedTaskRun>,
) {
    let mut pending = Vec::new();
    loop {
        if pending.is_empty() {
            match receiver.recv() {
                Ok(run) => pending.push(run),
                Err(_) => return,
            }
        } else {
            match receiver.recv_timeout(std::time::Duration::from_millis(10)) {
                Ok(run) => pending.push(run),
                Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {}
                Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
                    for run in pending.drain(..) {
                        retain_delegated_task_handle(run);
                    }
                    return;
                }
            }
        }
        while let Ok(run) = receiver.try_recv() {
            pending.push(run);
        }

        let mut index = 0;
        while index < pending.len() {
            if pending[index].join_handle.is_finished() {
                let run = pending.swap_remove(index);
                let _owner_id = run.owner_id;
                let _ = run.join_handle.join();
                #[cfg(any(test, feature = "test-helpers"))]
                record_delegated_task_reaped(_owner_id);
            } else {
                index += 1;
            }
        }
    }
}

#[cfg(feature = "ai")]
fn delegated_task_supervisor_sender()
-> Result<std::sync::mpsc::Sender<SupervisedDelegatedTaskRun>, AppCompositionError> {
    if let Some(supervisor) = DELEGATED_TASK_HANDLE_SUPERVISOR.get() {
        return Ok(supervisor.sender.clone());
    }
    let _init_guard = DELEGATED_TASK_HANDLE_SUPERVISOR_INIT
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    if let Some(supervisor) = DELEGATED_TASK_HANDLE_SUPERVISOR.get() {
        return Ok(supervisor.sender.clone());
    }

    let (sender, receiver) = std::sync::mpsc::channel();
    let thread_handle = std::thread::Builder::new()
        .name("legion-delegated-handle-supervisor".to_string())
        .spawn(move || run_delegated_task_handle_supervisor(receiver))
        .map_err(|error| {
            AppCompositionError::AiRuntime(format!(
                "failed to initialize delegated task handle supervisor: {error}"
            ))
        })?;
    let supervisor = DelegatedTaskHandleSupervisor {
        sender: sender.clone(),
        _thread_handle: thread_handle,
    };
    if DELEGATED_TASK_HANDLE_SUPERVISOR.set(supervisor).is_err() {
        return DELEGATED_TASK_HANDLE_SUPERVISOR
            .get()
            .map(|supervisor| supervisor.sender.clone())
            .ok_or_else(|| {
                AppCompositionError::AiRuntime(
                    "delegated task handle supervisor initialization raced without an owner"
                        .to_string(),
                )
            });
    }
    Ok(sender)
}

#[cfg(feature = "ai")]
struct InFlightDelegatedTaskRun {
    owner_id: uuid::Uuid,
    cancellation_flag: SharedCancellationFlag,
    join_handle: Option<DelegatedTaskJoinHandle>,
    supervisor_sender: std::sync::mpsc::Sender<SupervisedDelegatedTaskRun>,
}

#[cfg(feature = "ai")]
impl Drop for InFlightDelegatedTaskRun {
    fn drop(&mut self) {
        self.cancellation_flag.cancel();
        let Some(join_handle) = self.join_handle.take() else {
            return;
        };
        if join_handle.is_finished() {
            let _ = join_handle.join();
            return;
        }
        let owner_id = self.owner_id;
        let supervised_run = SupervisedDelegatedTaskRun {
            owner_id,
            join_handle,
        };
        match self.supervisor_sender.send(supervised_run) {
            Ok(()) => {
                #[cfg(any(test, feature = "test-helpers"))]
                record_delegated_task_handoff(owner_id);
            }
            Err(std::sync::mpsc::SendError(supervised_run)) => {
                // Retain ownership for process lifetime if the preinitialized
                // supervisor ever disconnects; never detach a live worker.
                retain_delegated_task_handle(supervised_run);
            }
        }
    }
}

#[cfg(feature = "ai")]
struct DelegatedTaskRunCompletion {
    audit_steps: Vec<legion_protocol::DelegatedTaskLoopStepRecord>,
    loop_result: Option<legion_agent::agent_loop::DelegatedTaskLoopResult>,
    sandbox_allocation_failure: Option<String>,
    sandbox_enforcement_label: Option<String>,
}

#[cfg(feature = "ai")]
struct DelegatedSandboxCleanupGuard {
    orchestrator: DelegatedTaskSandboxOrchestrator,
    permission: DelegatedTaskToolPermissionRequest,
    cleanup_complete: bool,
}

#[cfg(feature = "ai")]
impl DelegatedSandboxCleanupGuard {
    fn new(
        orchestrator: DelegatedTaskSandboxOrchestrator,
        permission: DelegatedTaskToolPermissionRequest,
    ) -> Self {
        Self {
            orchestrator,
            permission,
            cleanup_complete: false,
        }
    }

    fn initialize(&mut self) -> Result<(), std::io::Error> {
        self.orchestrator.initialize(&self.permission)
    }

    fn cleanup(&mut self) -> Result<(), std::io::Error> {
        match self.orchestrator.cleanup(&self.permission) {
            Ok(()) => {
                self.cleanup_complete = true;
                Ok(())
            }
            Err(error) => Err(error),
        }
    }
}

#[cfg(feature = "ai")]
impl Drop for DelegatedSandboxCleanupGuard {
    fn drop(&mut self) {
        if !self.cleanup_complete {
            let _ = self.orchestrator.cleanup(&self.permission);
        }
    }
}

/// Thread-safe cancellation flag shared between the UI kill switch and the delegated task loop.
///
/// The UI thread calls [`SharedCancellationFlag::cancel`] and the delegated task loop polls
/// [`SharedCancellationFlag::is_cancelled`] before every model turn and every tool execution.
#[derive(Clone)]
pub struct SharedCancellationFlag {
    cancelled: std::sync::Arc<std::sync::atomic::AtomicBool>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ActiveWorkerIdentity {
    DelegatedTask { run_id: String },
    LegionWorkflow { session_id: LegionWorkflowSessionId },
}

#[derive(Clone)]
struct ActiveWorkerRegistration {
    owner_id: uuid::Uuid,
    identity: ActiveWorkerIdentity,
    cancellation_flag: SharedCancellationFlag,
}

impl SharedCancellationFlag {
    /// Create a new flag in the non-cancelled state.
    pub fn new() -> Self {
        Self {
            cancelled: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
        }
    }

    /// Signal cancellation. The delegated task loop will observe this on its next poll.
    pub fn cancel(&self) {
        self.cancelled
            .store(true, std::sync::atomic::Ordering::Release);
    }

    /// Returns true if cancellation has been signalled.
    pub fn is_cancelled(&self) -> bool {
        self.cancelled.load(std::sync::atomic::Ordering::Acquire)
    }
}

impl Default for SharedCancellationFlag {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(feature = "ai")]
impl legion_agent::agent_loop::DelegatedTaskCancellationProbe for SharedCancellationFlag {
    fn is_cancelled(&self) -> bool {
        self.cancelled.load(std::sync::atomic::Ordering::Acquire)
    }
}

/// Tool host for the native delegated task loop backed by `spawn_sandboxed`.
///
/// `TerminalCommand` calls are forwarded to an OS-sandboxed child process;
/// `McpPassthrough` calls return an error — MCP integration is wired in a
/// later packet.
///
/// Each successful spawn records a [`SandboxEnforcementReport`] so product UI
/// can show what the OS actually enforced (not only compile-time profile notes).
#[cfg(feature = "ai")]
pub struct AppDelegatedToolHost {
    /// Worktree root for spawned commands (writable root for the sandbox).
    pub worktree_root: PathBuf,
    /// Allowed network egress destinations (empty = no network).
    pub allowed_egress: std::collections::BTreeSet<String>,
    /// Last live enforcement report from `spawn_sandboxed` (shared with app projection).
    pub last_enforcement: Arc<Mutex<Option<legion_sandbox::spawn::SandboxEnforcementReport>>>,
}

#[cfg(feature = "ai")]
impl AppDelegatedToolHost {
    /// Construct a tool host with a fresh shared enforcement slot.
    pub fn new(worktree_root: PathBuf, allowed_egress: std::collections::BTreeSet<String>) -> Self {
        Self {
            worktree_root,
            allowed_egress,
            last_enforcement: Arc::new(Mutex::new(None)),
        }
    }

    /// Construct a tool host that writes enforcement into an existing shared slot.
    pub fn with_enforcement_slot(
        worktree_root: PathBuf,
        allowed_egress: std::collections::BTreeSet<String>,
        last_enforcement: Arc<Mutex<Option<legion_sandbox::spawn::SandboxEnforcementReport>>>,
    ) -> Self {
        Self {
            worktree_root,
            allowed_egress,
            last_enforcement,
        }
    }

    /// Format the last recorded enforcement report for projection rows.
    pub fn last_enforcement_summary(&self) -> Option<String> {
        let guard = self.last_enforcement.lock().ok()?;
        let report = guard.as_ref()?;
        Some(format_sandbox_enforcement_summary(report))
    }
}

#[cfg(feature = "ai")]
fn format_sandbox_enforcement_summary(
    report: &legion_sandbox::spawn::SandboxEnforcementReport,
) -> String {
    format!(
        "sandbox live enforcement: backend={} fs_write={} fs_read={} network={} caveats={}",
        report.backend_used,
        report.filesystem_write_enforced,
        report.filesystem_read_enforced,
        report.network_enforced,
        if report.caveat_labels.is_empty() {
            "none".to_string()
        } else {
            report.caveat_labels.join("; ")
        }
    )
}

#[cfg(feature = "ai")]
fn require_delegated_terminal_enforcement(
    report: &legion_sandbox::spawn::SandboxEnforcementReport,
) -> Result<(), String> {
    if report.filesystem_write_enforced
        && report.filesystem_read_enforced
        && report.network_enforced
    {
        return Ok(());
    }

    Err(format!(
        "terminal command denied: sandbox does not enforce the required filesystem and network isolation ({})",
        format_sandbox_enforcement_summary(report)
    ))
}

#[cfg(feature = "ai")]
impl legion_agent::agent_loop::DelegatedToolHost for AppDelegatedToolHost {
    fn run_terminal_command(
        &self,
        command: &str,
        workdir: Option<&Path>,
        timeout_seconds: Option<u32>,
    ) -> Result<String, String> {
        use legion_sandbox::spawn::{SandboxSpawnSpec, spawn_sandboxed};
        use std::time::Duration;

        let working_dir = workdir.unwrap_or(&self.worktree_root).to_path_buf();
        let timeout = Duration::from_secs(u64::from(timeout_seconds.unwrap_or(30)));

        let shell = if cfg!(windows) {
            PathBuf::from("cmd.exe")
        } else {
            PathBuf::from("/bin/sh")
        };
        let spec_for_args = |args| SandboxSpawnSpec {
            program: shell.clone(),
            args,
            working_dir: working_dir.clone(),
            writable_root: self.worktree_root.clone(),
            allowed_egress: self.allowed_egress.clone(),
            timeout,
            env: vec![],
        };

        // Probe the selected backend with a fixed, harmless command before any
        // model-controlled input is executed. The enforcement report is only
        // available after spawn, so checking the real command's report alone
        // would be too late to prevent data access or exfiltration.
        let probe_spec = spec_for_args(if cfg!(windows) {
            vec!["/C".to_string(), "exit /B 0".to_string()]
        } else {
            vec!["-c".to_string(), "true".to_string()]
        });
        let probe = spawn_sandboxed(&probe_spec)
            .map_err(|e| format!("sandbox enforcement probe failed: {e}"))?;
        if let Ok(mut slot) = self.last_enforcement.lock() {
            *slot = Some(probe.enforcement.clone());
        }
        if probe.timed_out {
            return Err(format!(
                "sandbox enforcement probe timed out after {}s",
                timeout.as_secs()
            ));
        }
        require_delegated_terminal_enforcement(&probe.enforcement)?;

        let spec = spec_for_args(if cfg!(windows) {
            vec!["/C".to_string(), command.to_string()]
        } else {
            vec!["-c".to_string(), command.to_string()]
        });

        match spawn_sandboxed(&spec) {
            Ok(output) => {
                if let Ok(mut slot) = self.last_enforcement.lock() {
                    *slot = Some(output.enforcement.clone());
                }
                let stdout = String::from_utf8_lossy(&output.stdout);
                let stderr = String::from_utf8_lossy(&output.stderr);
                let summary = format_sandbox_enforcement_summary(&output.enforcement);
                require_delegated_terminal_enforcement(&output.enforcement)?;
                if output.timed_out {
                    Err(format!(
                        "command timed out after {}s ({summary})",
                        timeout.as_secs()
                    ))
                } else {
                    Ok(format!("{stdout}{stderr}\n[{summary}]"))
                }
            }
            Err(e) => Err(format!("sandbox spawn failed: {e}")),
        }
    }

    fn call_mcp_tool(
        &self,
        _server_id: &str,
        _tool_name: &str,
        _arguments: &serde_json::Value,
    ) -> Result<String, String> {
        Err("MCP passthrough not yet available in production dispatch".to_string())
    }
}

/// App-owned outcome for a Delegate chat turn.
#[derive(Debug, Clone)]
pub struct AppDelegateChatOutcome {
    /// Current delegated task projection after the chat turn.
    pub projection: DelegatedTaskProjection,
    /// User message id.
    pub user_message_id: String,
    /// Assistant message id.
    pub assistant_message_id: String,
    /// Number of retrieval citations attached to the assistant response.
    pub citation_count: usize,
}

#[derive(Debug, Clone)]
struct DelegateWorkflowState {
    chat_messages: Vec<DelegatedTaskChatMessage>,
    context_citations: Vec<DelegatedTaskContextCitation>,
    hunk_decisions: HashMap<(ProposalId, String), DelegatedTaskProposalHunkDisposition>,
    tool_permission_requests: HashMap<String, DelegatedTaskToolPermissionRequest>,
    runtime_activation: DelegatedTaskRuntimeActivationState,
    next_message_sequence: u64,
    /// Last live sandbox enforcement summary from tool-host spawns (display-safe).
    last_sandbox_enforcement_label: Option<String>,
}

impl Default for DelegateWorkflowState {
    fn default() -> Self {
        Self {
            chat_messages: Vec::new(),
            context_citations: Vec::new(),
            hunk_decisions: HashMap::new(),
            tool_permission_requests: HashMap::new(),
            runtime_activation: DelegatedTaskRuntimeActivationState::NotEncoded,
            next_message_sequence: 0,
            last_sandbox_enforcement_label: None,
        }
    }
}

impl DelegateWorkflowState {
    fn next_message_id(&mut self, role: DelegatedTaskChatRole) -> String {
        self.next_message_sequence = self.next_message_sequence.saturating_add(1);
        format!("delegate:{role:?}:{}", self.next_message_sequence)
    }

    #[cfg_attr(not(feature = "ai"), allow(dead_code))]
    fn set_runtime_activation(&mut self, runtime_activation: DelegatedTaskRuntimeActivationState) {
        self.runtime_activation = runtime_activation;
    }

    #[cfg(any(test, feature = "test-helpers"))]
    fn record_system_message(
        &mut self,
        content_label: impl Into<String>,
        plan_id: Option<DelegatedTaskPlanId>,
        proposal_id: Option<ProposalId>,
        correlation_id: CorrelationId,
        causality_id: CausalityId,
    ) -> String {
        let message_id = self.next_message_id(DelegatedTaskChatRole::System);
        self.chat_messages.push(DelegatedTaskChatMessage {
            message_id: message_id.clone(),
            role: DelegatedTaskChatRole::System,
            content_label: content_label.into(),
            plan_id,
            proposal_id,
            citation_ids: Vec::new(),
            tool_permission_request_ids: Vec::new(),
            correlation_id,
            causality_id,
            created_at: TimestampMillis::now(),
            redaction_hints: vec![RedactionHint::MetadataOnly],
            schema_version: 1,
        });
        message_id
    }

    fn record_tool_permission(&mut self, request: DelegatedTaskToolPermissionRequest) {
        self.tool_permission_requests
            .insert(request.request_id.clone(), request);
    }

    fn tool_permission(&self, request_id: &str) -> Option<&DelegatedTaskToolPermissionRequest> {
        self.tool_permission_requests.get(request_id)
    }

    fn record_tool_permission_decision(
        &mut self,
        mut input: DelegatedTaskToolPermissionRequestInput,
    ) -> DelegatedTaskToolPermissionRequest {
        let effective_decision = if self
            .tool_permission_requests
            .get(&input.request_id)
            .is_some_and(|request| request.deny_overrides)
        {
            DelegatedTaskToolPermissionDecision::Deny
        } else {
            input.decision
        };
        input.decision = effective_decision;
        let request = delegated_task_tool_permission_request(input);
        self.record_tool_permission(request.clone());
        request
    }

    fn apply_to_projection(
        &self,
        projection: &mut DelegatedTaskProjection,
        proposal_ledger: &ProposalLedgerProjection,
    ) {
        projection.chat_messages = self.chat_messages.clone();
        projection.context_citations = self.context_citations.clone();
        projection.proposal_reviews = proposal_ledger
            .rows
            .iter()
            .filter(|row| row.diff_summary.hunk_count > 0 || !row.diff_summary.chunks.is_empty())
            .map(|row| self.review_for_row(row))
            .collect();
        projection.tool_permission_requests = self
            .tool_permission_requests
            .values()
            .cloned()
            .collect::<Vec<_>>();
        projection.tool_permission_requests.sort_by(|left, right| {
            left.request_id
                .cmp(&right.request_id)
                .then_with(|| format!("{:?}", left.profile).cmp(&format!("{:?}", right.profile)))
        });
        projection.runtime_activation = self.runtime_activation;
        projection.chat_message_count = projection.chat_messages.len() as u32;
        projection.context_citation_count = projection.context_citations.len() as u32;
        projection.proposal_review_count = projection.proposal_reviews.len() as u32;
        projection.tool_permission_request_count = projection.tool_permission_requests.len() as u32;
        if let Some(label) = &self.last_sandbox_enforcement_label
            && !projection
                .plan_only_disclaimers
                .iter()
                .any(|existing| existing == label)
        {
            projection.plan_only_disclaimers.push(label.clone());
        }
    }

    fn review_for_row(&self, row: &ProposalLedgerRow) -> DelegatedTaskProposalReview {
        let chunks = proposal_review_chunks(row)
            .into_iter()
            .map(|chunk| {
                let hunk_id = delegate_hunk_id(row.proposal_id, &chunk);
                let disposition = self
                    .hunk_decisions
                    .get(&(row.proposal_id, hunk_id.clone()))
                    .copied()
                    .unwrap_or(DelegatedTaskProposalHunkDisposition::Pending);
                DelegatedTaskProposalHunkReview {
                    hunk_id,
                    proposal_id: row.proposal_id,
                    target_id: chunk.target_id.clone(),
                    payload_kind: row.payload_kind,
                    path: target_path_for_chunk(row, chunk.target_id.as_deref()),
                    byte_range: chunk.byte_range,
                    changed_line_count: chunk.changed_line_count,
                    inserted_line_count: chunk.inserted_line_count,
                    deleted_line_count: chunk.deleted_line_count,
                    content_hash: chunk.content_hash.clone(),
                    disposition,
                    risk_label: row.risk_label,
                    privacy_label: row.privacy_label,
                    labels: vec!["delegate.proposal_hunk.human_review".to_string()],
                    redaction_hints: vec![RedactionHint::MetadataOnly],
                    schema_version: 1,
                }
            })
            .collect::<Vec<_>>();
        DelegatedTaskProposalReview::from_hunks(
            format!("delegate:review:{}", row.proposal_id.0),
            row.proposal_id,
            chunks,
            vec!["delegate.proposal_review.human_approval_queue".to_string()],
            1,
        )
    }
}

/// App-owned outcome for an Automate MCP tool-call attempt.
#[derive(Debug, Clone)]
pub enum AppAutomateToolCallOutcome {
    /// Tool call reached a permission boundary and must wait.
    WaitingForToolPermission {
        /// Permission row that must be approved or denied.
        request: DelegatedTaskToolPermissionRequest,
    },
    /// Tool call was denied by a fail-closed permission decision.
    Denied {
        /// Denying permission row.
        request: DelegatedTaskToolPermissionRequest,
    },
    /// Risk monitor or kill switch halted the fleet before the call.
    Halted {
        /// Current risk monitor snapshot.
        monitor: LegionWorkflowRiskMonitorSnapshot,
    },
    /// Tool call is ready to be invoked by the MCP client.
    Ready {
        /// Permission row authorizing this call.
        request: DelegatedTaskToolPermissionRequest,
        /// Current risk monitor snapshot.
        monitor: LegionWorkflowRiskMonitorSnapshot,
    },
}

/// Metadata-safe Automate MCP tool invocation routed by app-owned workflow execution.
#[derive(Debug, Clone, PartialEq)]
pub struct AppAutomateMcpToolInvocation {
    /// Workflow session that owns the worker.
    pub session_id: LegionWorkflowSessionId,
    /// Worker that requested the tool call.
    pub worker_id: LegionWorkflowWorkerId,
    /// MCP server selected from the app-owned registry.
    pub server_id: McpServerId,
    /// MCP tool selected from the app-owned registry.
    pub tool_name: McpToolName,
    /// Permission row that authorized this invocation.
    pub permission: DelegatedTaskToolPermissionRequest,
    /// Display-safe or empty call arguments. Raw source must not be persisted here.
    pub arguments: Value,
    /// Non-zero correlation id for this invocation.
    pub correlation_id: CorrelationId,
    /// Non-nil causality id for this invocation.
    pub causality_id: CausalityId,
    /// Event sequence assigned by app composition.
    pub event_sequence: EventSequence,
}

/// Metadata-only receipt returned after an Automate MCP runtime call.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AppAutomateMcpToolInvocationReceipt {
    /// Workflow session that owns the worker.
    pub session_id: LegionWorkflowSessionId,
    /// Worker that requested the tool call.
    pub worker_id: LegionWorkflowWorkerId,
    /// MCP server that handled the call.
    pub server_id: McpServerId,
    /// MCP tool that handled the call.
    pub tool_name: McpToolName,
    /// Permission request id used for runtime authorization.
    pub permission_request_id: String,
    /// Display-safe result label.
    pub result_label: String,
    /// Fingerprint of redacted result metadata.
    pub result_fingerprint: FileFingerprint,
}

/// Error returned by an app-registered Automate MCP tool runtime.
#[derive(Debug, Clone, PartialEq, Eq, Error)]
pub enum AppAutomateMcpToolRuntimeError {
    /// Runtime transport, authorization, or protocol handling failed.
    #[error("Legion Workflows MCP tool runtime failed: {reason_label}")]
    Runtime {
        /// Display-safe failure reason.
        reason_label: String,
    },
}

impl AppAutomateMcpToolRuntimeError {
    #[cfg(feature = "ai")]
    fn runtime(reason_label: impl Into<String>) -> Self {
        Self::Runtime {
            reason_label: reason_label.into(),
        }
    }
}

/// Runtime bridge used by app-owned Automate fleet execution to invoke MCP tools.
pub trait AppAutomateMcpToolRuntime: Send + Sync {
    /// Invoke one MCP tool after app-owned permission and risk checks pass.
    fn call_tool(
        &self,
        invocation: &AppAutomateMcpToolInvocation,
    ) -> Result<AppAutomateMcpToolInvocationReceipt, AppAutomateMcpToolRuntimeError>;
}

/// ACP host command configured by the app.
#[derive(Debug, Clone)]
#[cfg(any(test, feature = "test-helpers"))]
struct AcpHostCommand {
    program: PathBuf,
    args: Vec<String>,
}

#[cfg(any(test, feature = "test-helpers"))]
impl AcpHostCommand {
    fn new(program: impl Into<PathBuf>, args: Vec<String>) -> Self {
        Self {
            program: program.into(),
            args,
        }
    }

    fn run(
        &self,
        sandbox_path: &Path,
        target_path: &Path,
        plan_id: &str,
    ) -> std::io::Result<std::process::Output> {
        let mut command = Command::new(&self.program);
        command.args(&self.args);
        command.current_dir(sandbox_path);
        command.env("LEGION_ACP_PLAN_ID", plan_id);
        command.env("LEGION_ACP_SANDBOX_PATH", sandbox_path);
        command.env("LEGION_ACP_TARGET_PATH", target_path);
        command.env(
            "LEGION_ACP_TARGET_DIR",
            target_path.parent().unwrap_or(sandbox_path),
        );
        command.env(
            "LEGION_ACP_TARGET_FILE",
            target_path
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("proposal.txt"),
        );
        command.output()
    }
}

/// App adapter that invokes a `legion-ai-providers` MCP client from Automate workflows.
#[cfg(feature = "ai")]
pub struct AppMcpClientToolRuntime<T>
where
    T: McpTransport,
{
    client: McpClient<T>,
}

#[cfg(feature = "ai")]
impl<T> AppMcpClientToolRuntime<T>
where
    T: McpTransport,
{
    /// Create an app runtime adapter over a validated MCP client.
    pub fn new(client: McpClient<T>) -> Self {
        Self { client }
    }
}

#[cfg(feature = "ai")]
impl<T> AppAutomateMcpToolRuntime for AppMcpClientToolRuntime<T>
where
    T: McpTransport + Send + Sync,
{
    fn call_tool(
        &self,
        invocation: &AppAutomateMcpToolInvocation,
    ) -> Result<AppAutomateMcpToolInvocationReceipt, AppAutomateMcpToolRuntimeError> {
        let result = self
            .client
            .call_tool_with_permission(
                format!(
                    "mcp-call:{}:{}:{}",
                    invocation.session_id.0, invocation.worker_id.0, invocation.event_sequence.0
                ),
                &invocation.server_id,
                &invocation.tool_name,
                invocation.arguments.clone(),
                &invocation.permission,
            )
            .map_err(|error| AppAutomateMcpToolRuntimeError::runtime(error.to_string()))?;
        let result_label = result
            .get("result_label")
            .and_then(Value::as_str)
            .unwrap_or("mcp.tool.result.redacted")
            .to_string();
        Ok(AppAutomateMcpToolInvocationReceipt {
            session_id: invocation.session_id.clone(),
            worker_id: invocation.worker_id.clone(),
            server_id: invocation.server_id.clone(),
            tool_name: invocation.tool_name.clone(),
            permission_request_id: invocation.permission.request_id.clone(),
            result_label,
            result_fingerprint: value_fingerprint("mcp-result", &result),
        })
    }
}

#[derive(Debug, Clone)]
struct AutomateWorkflowState {
    mcp_registries: HashMap<String, McpRegistrySnapshot>,
    decision_feed: Vec<LegionWorkflowDecisionFeedEntry>,
    risk_monitors: HashMap<String, LegionWorkflowRiskMonitorSnapshot>,
    kill_switches: HashMap<String, LegionWorkflowKillSwitch>,
    tool_permission_requests: HashMap<String, DelegatedTaskToolPermissionRequest>,
    high_risk_tool_count: HashMap<String, u32>,
    denied_tool_count: HashMap<String, u32>,
    next_decision_sequence: u64,
    halt_threshold: u32,
}

#[derive(Debug, Clone)]
struct AutomateDecisionInput {
    session_id: LegionWorkflowSessionId,
    worker_id: Option<LegionWorkflowWorkerId>,
    kind: LegionWorkflowDecisionKind,
    summary_label: String,
    risk_label: ProposalRiskLabel,
    mcp_server_id: Option<McpServerId>,
    mcp_primitive_kind: Option<McpPrimitiveKind>,
    tool_permission_request_id: Option<String>,
    event_context: EventContext,
    event_sequence: EventSequence,
}

impl Default for AutomateWorkflowState {
    fn default() -> Self {
        Self {
            mcp_registries: HashMap::new(),
            decision_feed: Vec::new(),
            risk_monitors: HashMap::new(),
            kill_switches: HashMap::new(),
            tool_permission_requests: HashMap::new(),
            high_risk_tool_count: HashMap::new(),
            denied_tool_count: HashMap::new(),
            next_decision_sequence: 0,
            halt_threshold: 3,
        }
    }
}

impl AutomateWorkflowState {
    fn apply_to_projection(&self, projection: &mut LegionWorkflowProjection) {
        projection.mcp_registries = self.mcp_registries.values().cloned().collect();
        projection
            .mcp_registries
            .sort_by(|left, right| left.registry_id.cmp(&right.registry_id));
        projection.decision_feed = self.decision_feed.clone();
        projection
            .decision_feed
            .sort_by_key(|entry| entry.event_sequence.0);
        projection.risk_monitors = self.risk_monitors.values().cloned().collect();
        projection
            .risk_monitors
            .sort_by(|left, right| left.monitor_id.0.cmp(&right.monitor_id.0));
        projection.kill_switches = self.kill_switches.values().cloned().collect();
        projection
            .kill_switches
            .sort_by(|left, right| left.kill_switch_id.0.cmp(&right.kill_switch_id.0));
        projection.tool_permission_requests =
            self.tool_permission_requests.values().cloned().collect();
        projection
            .tool_permission_requests
            .sort_by(|left, right| left.request_id.cmp(&right.request_id));
        projection.mcp_registry_count = projection.mcp_registries.len() as u32;
        projection.decision_feed_count = projection.decision_feed.len() as u32;
        projection.risk_monitor_count = projection.risk_monitors.len() as u32;
        projection.kill_switch_count = projection.kill_switches.len() as u32;
        projection.tool_permission_request_count = projection.tool_permission_requests.len() as u32;
    }

    #[cfg_attr(not(feature = "ai"), allow(dead_code))]
    fn decision_feed_for_session(
        &self,
        session_id: &LegionWorkflowSessionId,
    ) -> Vec<LegionWorkflowDecisionFeedEntry> {
        self.decision_feed
            .iter()
            .filter(|entry| &entry.session_id == session_id)
            .cloned()
            .collect()
    }

    #[cfg_attr(not(feature = "ai"), allow(dead_code))]
    fn risk_monitors(&self) -> Vec<LegionWorkflowRiskMonitorSnapshot> {
        self.risk_monitors.values().cloned().collect()
    }

    #[cfg_attr(not(feature = "ai"), allow(dead_code))]
    fn kill_switches(&self) -> Vec<LegionWorkflowKillSwitch> {
        self.kill_switches.values().cloned().collect()
    }

    #[cfg_attr(not(feature = "ai"), allow(dead_code))]
    fn tool_permission_requests(&self) -> Vec<DelegatedTaskToolPermissionRequest> {
        self.tool_permission_requests.values().cloned().collect()
    }

    #[cfg_attr(not(feature = "ai"), allow(dead_code))]
    fn mcp_registries(&self) -> Vec<McpRegistrySnapshot> {
        self.mcp_registries.values().cloned().collect()
    }

    fn seed_mcp_registry(&mut self, registry: McpRegistrySnapshot) {
        self.mcp_registries
            .insert(registry.server.server_id.0.clone(), registry);
    }

    fn apply_mcp_list_changed(
        &mut self,
        server_id: &McpServerId,
        _kind: McpListChangedKind,
        generated_at: TimestampMillis,
    ) -> bool {
        let Some(registry) = self.mcp_registries.get_mut(&server_id.0) else {
            return false;
        };
        registry.last_notification_kind = None;
        registry.list_version = registry.list_version.saturating_add(1);
        registry.generated_at = generated_at;
        true
    }

    fn mcp_tool(
        &self,
        server_id: &McpServerId,
        tool_name: &McpToolName,
    ) -> Option<&McpToolDescriptor> {
        self.mcp_registries
            .get(&server_id.0)
            .and_then(|registry| registry.tools.iter().find(|tool| tool.name == *tool_name))
    }

    fn record_decision(
        &mut self,
        input: AutomateDecisionInput,
    ) -> Result<LegionWorkflowDecisionFeedEntry, AppCompositionError> {
        self.next_decision_sequence = self.next_decision_sequence.saturating_add(1);
        let rationale_label = format!("legion_workflow.decision.{:?}", input.kind);
        let entry = LegionWorkflowDecisionFeedEntry {
            decision_id: LegionWorkflowDecisionId(format!(
                "legion-decision:{}:{}",
                input.session_id.0, self.next_decision_sequence
            )),
            session_id: input.session_id,
            worker_id: input.worker_id,
            kind: input.kind,
            summary_label: input.summary_label,
            rationale_labels: vec![rationale_label],
            risk_label: input.risk_label,
            mcp_server_id: input.mcp_server_id,
            mcp_primitive_kind: input.mcp_primitive_kind,
            tool_permission_request_id: input.tool_permission_request_id,
            correlation_id: input.event_context.correlation_id,
            causality_id: input.event_context.causality_id,
            event_sequence: input.event_sequence,
            redaction_hints: vec![RedactionHint::MetadataOnly],
            schema_version: 1,
        };
        validate_legion_workflow_decision_feed_entry(&entry)
            .map_err(|error| AppCompositionError::LegionWorkflow(error.message))?;
        self.decision_feed.push(entry.clone());
        Ok(entry)
    }

    fn record_tool_permission_decision(
        &mut self,
        session_id: &LegionWorkflowSessionId,
        request_id: impl Into<String>,
        tool: &McpToolDescriptor,
        decision: DelegatedTaskToolPermissionDecision,
    ) -> DelegatedTaskToolPermissionRequest {
        let request_id = request_id.into();
        let effective_decision = if self
            .tool_permission_requests
            .get(&request_id)
            .is_some_and(|request| request.deny_overrides)
        {
            DelegatedTaskToolPermissionDecision::Deny
        } else {
            decision
        };
        let request = mcp_tool_permission_request(
            request_id,
            tool,
            effective_decision,
            format!("legion.session:{}", session_id.0),
            1,
        );
        self.tool_permission_requests
            .insert(request.request_id.clone(), request.clone());
        request
    }

    fn tool_permission(&self, request_id: &str) -> Option<&DelegatedTaskToolPermissionRequest> {
        self.tool_permission_requests.get(request_id)
    }

    fn risk_monitor(
        &mut self,
        session_id: &LegionWorkflowSessionId,
        reason: Option<LegionWorkflowRiskHaltReason>,
    ) -> Result<LegionWorkflowRiskMonitorSnapshot, AppCompositionError> {
        let high_risk = *self.high_risk_tool_count.get(&session_id.0).unwrap_or(&0);
        let denied = *self.denied_tool_count.get(&session_id.0).unwrap_or(&0);
        let stale_registry = self
            .mcp_registries
            .values()
            .any(|registry| registry.last_notification_kind.is_some());
        let computed_reason = reason
            .or_else(|| {
                (high_risk >= self.halt_threshold)
                    .then_some(LegionWorkflowRiskHaltReason::HighRiskToolThreshold)
            })
            .or_else(|| {
                (denied >= self.halt_threshold)
                    .then_some(LegionWorkflowRiskHaltReason::DeniedToolThreshold)
            })
            .or_else(|| stale_registry.then_some(LegionWorkflowRiskHaltReason::StaleMcpRegistry));
        let risk_score = high_risk
            .saturating_mul(2)
            .saturating_add(denied)
            .saturating_add(if stale_registry { 1 } else { 0 });
        let state = if computed_reason.is_some() {
            LegionWorkflowRiskMonitorState::Halted
        } else if risk_score >= self.halt_threshold.saturating_sub(1) {
            LegionWorkflowRiskMonitorState::Warning
        } else {
            LegionWorkflowRiskMonitorState::Nominal
        };
        let mut labels = vec![format!("legion_workflow.risk.{state:?}")];
        if stale_registry {
            labels.push("legion_workflow.risk.stale_mcp_registry".to_string());
        }
        let snapshot = LegionWorkflowRiskMonitorSnapshot {
            monitor_id: LegionWorkflowRiskMonitorId(format!("legion-risk:{}", session_id.0)),
            session_id: session_id.clone(),
            state,
            risk_score,
            halt_threshold: self.halt_threshold,
            high_risk_action_count: high_risk,
            denied_tool_count: denied,
            stale_mcp_registry_detected: stale_registry,
            halt_reason: computed_reason,
            labels,
            redaction_hints: vec![RedactionHint::MetadataOnly],
            schema_version: 1,
        };
        validate_legion_workflow_risk_monitor_snapshot(&snapshot)
            .map_err(|error| AppCompositionError::LegionWorkflow(error.message))?;
        self.risk_monitors
            .insert(session_id.0.clone(), snapshot.clone());
        Ok(snapshot)
    }

    fn armed_kill_switch(
        &mut self,
        session_id: &LegionWorkflowSessionId,
        correlation_id: CorrelationId,
        causality_id: CausalityId,
    ) -> Result<LegionWorkflowKillSwitch, AppCompositionError> {
        let switch = self
            .kill_switches
            .entry(session_id.0.clone())
            .or_insert_with(|| LegionWorkflowKillSwitch {
                kill_switch_id: LegionWorkflowKillSwitchId(format!("legion-kill:{}", session_id.0)),
                session_id: session_id.clone(),
                state: LegionWorkflowKillSwitchState::Armed,
                triggered_by: None,
                reason_label: None,
                triggered_at: None,
                correlation_id,
                causality_id,
                redaction_hints: vec![RedactionHint::MetadataOnly],
                schema_version: 1,
            })
            .clone();
        validate_legion_workflow_kill_switch(&switch)
            .map_err(|error| AppCompositionError::LegionWorkflow(error.message))?;
        Ok(switch)
    }

    fn trigger_kill_switch(
        &mut self,
        session_id: &LegionWorkflowSessionId,
        principal_id: PrincipalId,
        reason_label: String,
        correlation_id: CorrelationId,
        causality_id: CausalityId,
    ) -> Result<LegionWorkflowKillSwitch, AppCompositionError> {
        let switch = LegionWorkflowKillSwitch {
            kill_switch_id: LegionWorkflowKillSwitchId(format!("legion-kill:{}", session_id.0)),
            session_id: session_id.clone(),
            state: LegionWorkflowKillSwitchState::Triggered,
            triggered_by: Some(principal_id),
            reason_label: Some(reason_label),
            triggered_at: Some(TimestampMillis::now()),
            correlation_id,
            causality_id,
            redaction_hints: vec![RedactionHint::MetadataOnly],
            schema_version: 1,
        };
        validate_legion_workflow_kill_switch(&switch)
            .map_err(|error| AppCompositionError::LegionWorkflow(error.message))?;
        self.kill_switches
            .insert(session_id.0.clone(), switch.clone());
        self.risk_monitor(session_id, Some(LegionWorkflowRiskHaltReason::KillSwitch))?;
        Ok(switch)
    }

    fn kill_switch_triggered(&self, session_id: &LegionWorkflowSessionId) -> bool {
        self.kill_switches
            .get(&session_id.0)
            .is_some_and(|switch| switch.state == LegionWorkflowKillSwitchState::Triggered)
    }
}

fn proposal_review_chunks(row: &ProposalLedgerRow) -> Vec<ProposalDiffChunkDescriptor> {
    if !row.diff_summary.chunks.is_empty()
        && row.diff_summary.chunks.len() as u32 >= row.diff_summary.hunk_count
    {
        return row.diff_summary.chunks.clone();
    }

    let represented_hunks = row.diff_summary.hunk_count.max(1);
    (0..represented_hunks)
        .map(|index| {
            let target = row
                .target_coverage
                .targets
                .get(index as usize)
                .or_else(|| row.target_coverage.targets.first());
            ProposalDiffChunkDescriptor {
                chunk_id: format!("delegate-hunk:{index}"),
                target_id: target.map(|target| target.target_id.clone()),
                byte_range: target.and_then(|target| target.byte_ranges.first().copied()),
                changed_line_count: 0,
                inserted_line_count: row.diff_summary.inserted_line_count,
                deleted_line_count: row.diff_summary.deleted_line_count,
                content_hash: row.diff_summary.diff_hash.clone(),
            }
        })
        .collect()
}

fn delegate_hunk_id(proposal_id: ProposalId, chunk: &ProposalDiffChunkDescriptor) -> String {
    format!("delegate:proposal:{}:{}", proposal_id.0, chunk.chunk_id)
}

fn target_path_for_chunk(
    row: &ProposalLedgerRow,
    target_id: Option<&str>,
) -> Option<CanonicalPath> {
    target_id
        .and_then(|target_id| {
            row.target_coverage
                .targets
                .iter()
                .find(|target| target.target_id == target_id)
        })
        .or_else(|| row.target_coverage.targets.first())
        .and_then(|target| target.path.clone())
}

