    /// Replace the palette usage repository with a disk-backed implementation.
    ///
    /// Call this before any palette operations to enable persistence. Product
    /// entry points call [`Self::enable_palette_usage_persistence`] instead;
    /// tests continue to use the in-memory default (or inject their own).
    pub fn set_palette_usage_repository(&mut self, repo: Box<dyn PaletteUsageRepository>) {
        self.palette_usage = repo;
    }

    /// Override the batch runtime apply policy.
    ///
    /// Test-only helper that allows tests to configure an enabled policy for a
    /// trusted workspace so the execution contract's `commit_blocked` and
    /// `finalize_blocked` fields reflect the real runtime state.
    #[cfg(any(test, feature = "test-helpers"))]
    pub fn set_batch_apply_policy_for_test(&mut self, policy: BatchRuntimeApplyPolicy) {
        self.batch_apply_policy = policy;
    }

    /// Directly force a proposal's lifecycle state, bypassing the lifecycle state
    /// machine.
    ///
    /// Test-only: enables testing defense-in-depth branches that are unreachable
    /// via the normal validation → preview pathway (e.g. the `TerminalCommand` deny
    /// arm in `apply_workspace_proposal`).
    #[cfg(any(test, feature = "test-helpers"))]
    pub fn force_proposal_lifecycle_state_for_test(
        &self,
        proposal_id: ProposalId,
        state: ProposalLifecycleState,
    ) {
        self.proposal_coordinator
            .proposal_states
            .borrow_mut()
            .insert(proposal_id, state);
    }

    /// Return the full [`WorkspaceProposal`] for a given id, if it is registered.
    ///
    /// Used by the desktop review apply path to retrieve the proposal payload
    /// required for constructing a filtered batch proposal from accepted hunks.
    pub fn workspace_proposal_for_id(&self, proposal_id: ProposalId) -> Option<WorkspaceProposal> {
        self.proposal_coordinator.proposal_for_id(proposal_id)
    }

    /// Compute a [`legion_protocol::ProposalDiffSurfaceProjection`] for a
    /// registered proposal using caller-supplied before/after file contents.
    ///
    /// `file_contents` maps each `target_id` from the proposal's target
    /// coverage to an `(old_text, new_text)` pair.  Targets whose `target_id`
    /// is absent from the map are silently skipped.
    ///
    /// # Lifecycle integration note (F4 DONE_WITH_CONCERNS)
    ///
    /// Auto-invocation on the `Previewed` lifecycle transition requires
    /// navigating the 25 000-line `lib.rs` to find the transition point, read
    /// current file contents from the workspace, and store the result.  That
    /// surgery carries significant breakage risk and is deferred to PKT-CTX.
    /// Callers (e.g. `legion-desktop`) can invoke this method manually when
    /// the proposal enters the review surface.
    pub fn compute_diff_surface_for_proposal(
        &self,
        proposal_id: ProposalId,
        file_contents: &std::collections::HashMap<String, (String, String)>,
    ) -> Option<legion_protocol::ProposalDiffSurfaceProjection> {
        let proposal = self.proposal_coordinator.proposal_for_id(proposal_id)?;
        Some(crate::proposal::compute_proposal_diff_surface(
            &proposal,
            file_contents,
        ))
    }

    /// Wires disk-backed palette usage persistence for a workspace. Usage
    /// counts (item keys only — never raw query text) live under the
    /// workspace-local `.legion/` state directory so ranking history survives
    /// restarts. Composition-root API: renderer edges (legion-desktop) and
    /// the CLI call this instead of constructing storage types themselves,
    /// keeping storage dependencies out of projection-only crates.
    pub fn enable_palette_usage_persistence(&mut self, workspace_root: &std::path::Path) {
        let palette_usage_path = workspace_root.join(".legion").join("palette_usage.json");
        if let Some(dir) = palette_usage_path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        self.set_palette_usage_repository(Box::new(
            legion_storage::FilePaletteUsageRepository::open(&palette_usage_path),
        ));
    }

    /// Enable file-backed checkpoint persistence for a workspace.
    ///
    /// Checkpoints are stored under `<workspace_root>/.legion/`.  Call this
    /// after opening a trusted workspace to survive IDE restarts.  Tests use
    /// the in-memory default (no persistence) unless they call this method.
    pub fn enable_checkpoint_persistence(&mut self, workspace_root: &std::path::Path) {
        let legion_dir = workspace_root.join(".legion");
        let _ = std::fs::create_dir_all(&legion_dir);
        self.checkpoint_store = CheckpointStore::with_base_dir(legion_dir);
    }

    /// Enable durable proposal-audit blobs under `<workspace_root>/.legion/proposal-audit/`.
    ///
    /// Complements checkpoint persistence (PKT-CKPT I4). Safe to call after
    /// [`Self::enable_checkpoint_persistence`]; both share the `.legion/` root.
    /// This must be enabled before any live proposal is registered because
    /// caller-assisted replay input is required to reconcile durable ids.
    pub fn enable_proposal_audit_persistence(
        &mut self,
        workspace_root: &std::path::Path,
    ) -> Result<(), AppCompositionError> {
        if !self
            .proposal_coordinator
            .proposal_lifecycle_recovery_snapshot()
            .records
            .is_empty()
        {
            return Err(AppCompositionError::Protocol(ProtocolError {
                code: "proposal_observation_publication_conflict".to_string(),
                message:
                    "proposal persistence must be enabled before live proposals are registered"
                        .to_string(),
            }));
        }
        let legion_dir = workspace_root.join(".legion");
        std::fs::create_dir_all(&legion_dir).map_err(|error| {
            AppCompositionError::Protocol(ProtocolError {
                code: "storage_failed".to_string(),
                message: format!("create workspace state directory failed: {error}"),
            })
        })?;
        self.storage
            .enable_base_dir(legion_dir)
            .map_err(AppCompositionError::Protocol)?;
        self.reserve_durable_proposal_observation_identities()
            .map_err(AppCompositionError::Protocol)?;
        Ok(())
    }

    fn reserve_durable_proposal_observation_identities(
        &mut self,
    ) -> ProtocolResult<Vec<legion_storage::ProposalObservationOutboxRecord>> {
        let records = self.storage.proposal_observation_batches()?;
        let proposal_floor = records
            .iter()
            .flat_map(|record| &record.batch.proposal_audits)
            .map(|audit| audit.proposal_id.0)
            .max()
            .unwrap_or(0)
            .max(
                self.storage
                    .max_proposal_audit_id()?
                    .map(|proposal_id| proposal_id.0)
                    .unwrap_or(0),
            );
        let sequence_floor = records
            .iter()
            .flat_map(|record| &record.batch.events)
            .map(|event| event.sequence.0)
            .max()
            .unwrap_or(0);
        if proposal_floor >= MAX_DURABLE_PROPOSAL_OBSERVATION_FLOOR
            || sequence_floor >= MAX_DURABLE_PROPOSAL_OBSERVATION_FLOOR
        {
            return Err(ProtocolError {
                code: "proposal_observation_identity_exhausted".to_string(),
                message: "durable proposal or event-sequence identity space is exhausted"
                    .to_string(),
            });
        }
        self.proposal_coordinator
            .reserve_proposal_ids_through(proposal_floor);
        self.proposal_coordinator
            .reserve_event_sequences_through(sequence_floor);
        self.event_sequence_generator
            .reserve_through(sequence_floor);
        Ok(records)
    }

    /// Enable the full workspace-local state suite under `.legion/`:
    /// palette usage, checkpoints, and proposal audit durability.
    pub fn enable_workspace_state_persistence(
        &mut self,
        workspace_root: &std::path::Path,
    ) -> Result<(), AppCompositionError> {
        // Bind the fallible proposal/outbox authority first. A rejected root
        // switch must not leave palette/checkpoint services rebound while the
        // proposal authority remains on the previous workspace.
        self.enable_proposal_audit_persistence(workspace_root)?;
        self.enable_palette_usage_persistence(workspace_root);
        self.enable_checkpoint_persistence(workspace_root);
        Ok(())
    }

    /// List durable checkpoints newest-first.
    pub fn list_checkpoints(&self) -> Vec<DurableCheckpointSummary> {
        self.checkpoint_store.list_checkpoints()
    }

    /// Restore a checkpoint by reverting each targeted file to its pre-apply state.
    ///
    /// Only the files recorded in the checkpoint are touched; files manually
    /// edited after the original apply that are NOT part of this checkpoint
    /// remain unchanged.
    ///
    /// # C1 — proposal-mediated file I/O
    /// All file mutations are routed through [`WorkspaceActor::restore_files_for_checkpoint`],
    /// which uses the workspace's `FileSystemService` abstraction (`self.fs.*`) rather than
    /// `std::fs` directly.  Full proposal lifecycle (fingerprint/generation checks) is not
    /// used because there is no live proposal context for a restore: see
    /// `WorkspaceRestoreFileOp` for the detailed rationale.
    ///
    /// # C2 — atomic error handling
    /// If **any** file operation fails the method returns an error immediately.  The
    /// checkpoint is NOT marked unavailable and NO audit record is written in that case,
    /// leaving the checkpoint available for a retry.
    ///
    /// # I2 — displaced content preservation
    /// Before the restore, targets whose current on-disk content would be overwritten or
    /// deleted are compared against `content_before`.  If the on-disk state differs, a
    /// pre-restore snapshot checkpoint is created so the displaced state can be recovered
    /// later via another restore.
    pub fn restore_checkpoint(&mut self, checkpoint_id: &str) -> Result<(), AppCompositionError> {
        let checkpoint = self
            .checkpoint_store
            .load_checkpoint(checkpoint_id)
            .map_err(|e| AppCompositionError::Checkpoint(e.to_string()))?
            .ok_or_else(|| {
                AppCompositionError::Checkpoint(format!("checkpoint not found: {checkpoint_id}"))
            })?;

        if !checkpoint.available {
            return Err(AppCompositionError::Checkpoint(format!(
                "checkpoint {checkpoint_id} has already been restored"
            )));
        }

        // C1: Build workspace-layer file ops — no raw std::fs calls.
        let mut ops: Vec<WorkspaceRestoreFileOp> = Vec::new();
        for target in &checkpoint.targets {
            match &target.kind {
                CheckpointTargetKind::CreatedFile => {
                    // The proposal created this file; restoring it means deleting it.
                    ops.push(WorkspaceRestoreFileOp::DeleteFile {
                        path: target.path.clone(),
                    });
                }
                CheckpointTargetKind::DeletedFile | CheckpointTargetKind::SavedFile => {
                    // Restore the pre-mutation content.
                    let content = target.content_before.clone().unwrap_or_default();
                    ops.push(WorkspaceRestoreFileOp::WriteFile {
                        path: target.path.clone(),
                        content,
                    });
                }
                CheckpointTargetKind::RenamedFile { original_path } => {
                    // Move the current path (destination after rename) back to
                    // the original source path.
                    ops.push(WorkspaceRestoreFileOp::RenameFile {
                        source: target.path.clone(),
                        destination: original_path.clone(),
                    });
                }
            }
        }

        // Durable checkpoint JSON is workspace-controlled input.  Validate the complete
        // operation set before reading any target for the displaced-content snapshot.
        // `restore_files_for_checkpoint` validates again immediately before mutation.
        self.workspace
            .validate_checkpoint_restore_ops(&ops)
            .map_err(|err| AppCompositionError::Checkpoint(format!("restore failed: {err}")))?;

        // I2: Detect targets whose current disk state differs from content_before and
        // create a pre-restore snapshot so those displaced edits can be recovered.
        let pre_restore_snapshot = self.build_pre_restore_snapshot(&checkpoint)?;
        if let Some(snap) = pre_restore_snapshot {
            let _ = self.checkpoint_store.save_checkpoint(snap);
        }

        // C2: Execute all ops through the workspace filesystem layer.
        // On failure: return the error; do NOT mark unavailable or write audit.
        self.workspace
            .restore_files_for_checkpoint(&ops)
            .map_err(|err| AppCompositionError::Checkpoint(format!("restore failed: {err}")))?;

        // All ops succeeded — mark the checkpoint consumed.
        self.checkpoint_store.mark_unavailable(checkpoint_id);

        // Write a restore audit record.
        let target_paths: Vec<CanonicalPath> =
            checkpoint.targets.iter().map(|t| t.path.clone()).collect();
        let audit = CheckpointAuditRecord {
            checkpoint_id: checkpoint_id.to_string(),
            event: CheckpointAuditEvent::Restored,
            proposal_id: checkpoint.proposal_id,
            target_paths,
            timestamp: TimestampMillis::now(),
            schema_version: 1,
        };
        let _ = self.checkpoint_store.save_audit_record(audit);

        // Refresh the workspace so the file tree reflects the restored state.
        self.refresh_workspace_after_checkpoint_restore();

        Ok(())
    }

    /// Build a pre-restore snapshot checkpoint that captures the current on-disk state of
    /// any checkpoint targets that have been displaced (manually edited after the proposal
    /// was applied).  Returns `None` when no displacement is detected.
    ///
    /// A displaced target is one whose current disk content differs from the stored
    /// `content_before`.  For `CreatedFile` targets (which will be deleted), any existing
    /// on-disk content is captured as displaced.
    fn build_pre_restore_snapshot(
        &self,
        checkpoint: &DurableCheckpoint,
    ) -> Result<Option<DurableCheckpoint>, AppCompositionError> {
        use legion_storage::checkpoint::CheckpointTarget;
        let mut snap_targets: Vec<CheckpointTarget> = Vec::new();

        for target in &checkpoint.targets {
            let current = self
                .workspace
                .read_checkpoint_target(&target.path)
                .map_err(|err| {
                    AppCompositionError::Checkpoint(format!("restore snapshot failed: {err}"))
                })?;
            let displaced = match &target.kind {
                // For a CreatedFile we're about to delete the file; any current content is
                // displaced.
                CheckpointTargetKind::CreatedFile => current.as_deref().map(|c| c.to_owned()),
                // For SavedFile/DeletedFile/RenamedFile, the file is about to be overwritten
                // with content_before.  If the current content differs from content_before,
                // it was manually edited after the proposal applied.
                _ => {
                    let expected = target.content_before.as_deref().unwrap_or("");
                    match &current {
                        Some(c) if c != expected => Some(c.clone()),
                        _ => None,
                    }
                }
            };

            if let Some(displaced_content) = displaced {
                snap_targets.push(CheckpointTarget {
                    target_id: format!("pre-restore-{}", target.target_id),
                    kind: CheckpointTargetKind::SavedFile,
                    path: target.path.clone(),
                    content_before: Some(displaced_content),
                });
            }
        }

        if snap_targets.is_empty() {
            return Ok(None);
        }

        let snap_id = format!("pre-restore-{}", checkpoint.checkpoint_id);
        Ok(Some(DurableCheckpoint {
            checkpoint_id: snap_id,
            proposal_id: checkpoint.proposal_id,
            principal: checkpoint.principal.clone(),
            created_at: TimestampMillis::now(),
            targets: snap_targets,
            available: true,
            schema_version: CHECKPOINT_SCHEMA_VERSION,
        }))
    }

    /// Query checkpoint audit records, optionally filtered by proposal identifier.
    pub fn query_checkpoint_audit(
        &self,
        proposal_id: Option<ProposalId>,
    ) -> Vec<CheckpointAuditRecord> {
        self.checkpoint_store.query_checkpoint_audit(proposal_id)
    }

    /// Refresh the workspace after a checkpoint restore, mirroring the
    /// post-rollback workspace close/reopen used by audit-failed mutations.
    fn refresh_workspace_after_checkpoint_restore(&mut self) {
        let Some(opened) = self.active_documents.opened_workspace.clone() else {
            return;
        };
        let Some(root_path) = self.active_documents.workspace_root_path.clone() else {
            return;
        };
        let principal = self
            .active_documents
            .active_principal_id
            .clone()
            .unwrap_or_else(|| PrincipalId("unknown".to_string()));
        let trust = self
            .active_documents
            .active_workspace_trust
            .clone()
            .unwrap_or(WorkspaceTrustState::Unknown);
        let correlation = self.correlation_generator.next();

        let _ = self
            .workspace
            .handle(WorkspaceRequest::Close(WorkspaceCloseRequest {
                workspace_id: opened.workspace_id,
                correlation_id: correlation,
                principal_id: principal.clone(),
            }));
        if let Ok(WorkspaceResponse::Opened(reopened)) =
            self.workspace
                .handle(WorkspaceRequest::Open(WorkspaceOpenRequest {
                    correlation_id: correlation,
                    principal_id: principal.clone(),
                    root_path: CanonicalPath(root_path.clone()),
                    trust: Some(trust.clone()),
                }))
        {
            self.active_documents.bind_workspace(
                reopened,
                CanonicalPath(root_path),
                principal,
                trust,
            );
        }
    }

    fn next_event_context(&mut self) -> EventContext {
        EventContext::new(self.correlation_generator.next())
    }

    fn emit_event(&self, envelope: EventEnvelope) {
        let _ = self.storage.record_event(envelope);
    }

    fn emit_transaction_event(&mut self, descriptor: &TextTransactionDescriptor) {
        // The envelope only fails to build on invalid core ids; skip emitting in
        // that case rather than aborting the surrounding editor operation.
        if let Ok(envelope) =
            transaction_event(descriptor, true, None, self.event_sequence_generator.next())
        {
            self.emit_event(envelope);
        }
    }

    fn begin_active_worker(
        &mut self,
        identity: ActiveWorkerIdentity,
    ) -> Result<(uuid::Uuid, SharedCancellationFlag), AppCompositionError> {
        self.reconcile_completed_workflow_drain();
        if self.active_worker.is_some() {
            return Err(AppCompositionError::AiRuntime(
                "an AI/workflow worker is already running".to_string(),
            ));
        }
        #[cfg(any(test, feature = "test-helpers"))]
        let cancellation_flag = self.injected_cancellation_flag.take().unwrap_or_default();
        #[cfg(not(any(test, feature = "test-helpers")))]
        let cancellation_flag = SharedCancellationFlag::default();
        let owner_id = uuid::Uuid::now_v7();
        self.active_worker = Some(ActiveWorkerRegistration {
            owner_id,
            identity,
            cancellation_flag: cancellation_flag.clone(),
        });
        Ok((owner_id, cancellation_flag))
    }

    fn ensure_no_active_worker(&mut self) -> Result<(), AppCompositionError> {
        self.reconcile_completed_workflow_drain();
        if self.active_worker.is_some() {
            Err(AppCompositionError::AiRuntime(
                "an AI/workflow worker is already running".to_string(),
            ))
        } else {
            Ok(())
        }
    }

    fn clear_active_worker(&mut self, owner_id: uuid::Uuid) {
        if self
            .active_worker
            .as_ref()
            .is_some_and(|registration| registration.owner_id == owner_id)
        {
            self.active_worker = None;
        }
    }

    fn reconcile_completed_workflow_drain(&mut self) {
        #[cfg(feature = "ai")]
        {
            let completed_owner = self
                .draining_workflow_worker
                .as_mut()
                .and_then(|registration| {
                    registration.reconcile_finished();
                    registration.is_complete().then_some(registration.owner_id)
                });
            if let Some(owner_id) = completed_owner {
                self.draining_workflow_worker = None;
                self.clear_active_worker(owner_id);
            }
        }
    }

    fn mode_allows_active_worker(mode: AppProductMode, identity: &ActiveWorkerIdentity) -> bool {
        match identity {
            ActiveWorkerIdentity::DelegatedTask { .. } => mode.allows_delegate(),
            ActiveWorkerIdentity::LegionWorkflow { .. } => mode.allows_automate(),
        }
    }

    /// Install a verified org policy bundle whose mode ceiling gates mode switches.
    ///
    /// Takes a [`VerifiedPolicyBundle`](legion_security::VerifiedPolicyBundle),
    /// which has no constructor other than
    /// [`SignedPolicyBundle::verify`](legion_security::SignedPolicyBundle::verify),
    /// so an unsigned or tampered bundle cannot be installed here.
    pub fn set_org_policy_bundle(&mut self, bundle: legion_security::VerifiedPolicyBundle) {
        self.org_policy_bundle = Some(bundle);
        // Re-assert the ceiling against the mode already in effect: installing a
        // bundle that forbids the current mode must lower it, not merely block
        // future raises.
        let current = self.product_mode;
        if self.org_policy_mode_ceiling_denies(current) {
            self.product_mode = AppProductMode::Manual;
            self.phase4_projection_state.assisted_ai_projection = None;
        }
    }

    /// Whether the installed org policy bundle's mode ceiling refuses `mode`.
    ///
    /// `false` when no bundle is installed — an absent bundle imposes no ceiling,
    /// which is different from an unverifiable one, which is never installed.
    pub fn org_policy_mode_ceiling_denies(&self, mode: AppProductMode) -> bool {
        self.org_policy_bundle
            .as_ref()
            .is_some_and(|bundle| !bundle.bundle().allows_mode(mode.to_product_mode()))
    }

    /// Set the app-owned product mode used to authorize AI dispatch.
    pub fn set_product_mode(&mut self, mode: AppProductMode) {
        // Org policy bundle mode ceiling (P9.F2.T3) is checked before any other
        // lane. A ceiling that only applied after the worker/stream checks below
        // would let an above-ceiling mode take effect whenever those lanes
        // happened to be idle.
        if self.org_policy_mode_ceiling_denies(mode) {
            return;
        }
        self.reconcile_completed_workflow_drain();
        if let Some(worker) = &self.active_worker
            && !Self::mode_allows_active_worker(mode, &worker.identity)
        {
            worker.cancellation_flag.cancel();
            // Keep the current authority projection, and therefore its visible
            // cancel control, until the owning worker result is merged.
            return;
        }
        if self.product_mode == mode {
            return;
        }
        if !self
            .live_product_ai_stream
            .mode_allows_active_operation(mode)
        {
            // Product provider calls do not yet expose a transport-level
            // cancellation handle. Refuse the downgrade rather than claim a
            // zero-egress mode while the request or result handoff is live.
            return;
        }
        // Persisted/projected workflow activity without a live worker can be
        // acknowledged synchronously, but only after every live lane above has
        // accepted the target mode. This avoids partial cancellation on a
        // downgrade that is ultimately deferred.
        if !mode.allows_automate() {
            for session in &mut self.legion_workflow_sessions {
                if matches!(
                    session.lifecycle_state,
                    LegionWorkflowState::Planning
                        | LegionWorkflowState::Executing
                        | LegionWorkflowState::Verifying
                ) {
                    session.lifecycle_state = LegionWorkflowState::Cancelled;
                }
            }
        }
        self.product_mode = mode;
        if !mode.allows_assist() {
            self.phase4_projection_state.assisted_ai_projection = None;
        }
    }

    /// Preferred product AI route for Assist proposals, Delegate chat, and inline ghost text.
    pub fn preferred_ai_provider(&self) -> ProductAiProviderPreference {
        self.preferred_ai_provider
    }

    /// Select the product AI route preference (`auto` / `ollama` / `anthropic` / `deterministic`).
    pub fn set_preferred_ai_provider(&mut self, preference: ProductAiProviderPreference) {
        self.preferred_ai_provider = preference;
    }

    /// Parse and apply a preferred-provider label (UI / env-compatible).
    pub fn set_preferred_ai_provider_label(&mut self, label: impl AsRef<str>) {
        self.preferred_ai_provider = ProductAiProviderPreference::parse(label.as_ref());
    }

    /// Last product AI stream projection (Assist / Delegate), if any.
    pub fn last_product_ai_stream(&self) -> Option<&ProductAiStreamProjection> {
        self.last_product_ai_stream.as_ref()
    }

    /// Snapshot of the live progressive stream (may be mid-flight).
    pub fn live_product_ai_stream_snapshot(&self) -> ProductAiStreamProjection {
        self.live_product_ai_stream.snapshot()
    }

    /// Whether a progressive / background product AI stream is still in flight.
    pub fn product_ai_stream_in_flight(&self) -> bool {
        self.live_product_ai_stream.is_in_flight()
    }

    /// Poll live stream into `last_product_ai_stream` and apply finished background jobs.
    ///
    /// Returns `true` when the retained stream, chat projection, or Assist proposal
    /// ledger changed (desktop should repaint).
    pub fn poll_product_ai_stream(&mut self) -> bool {
        let mut changed = self.poll_scheduled_proposal_observation_retries();
        let snap = self.live_product_ai_stream.snapshot();
        if (!snap.chunks.is_empty() || snap.in_flight || !snap.provider_id.is_empty())
            && self.last_product_ai_stream.as_ref() != Some(&snap)
        {
            self.last_product_ai_stream = Some(snap);
            changed = true;
        }
        for result in self.live_product_ai_stream.take_background_results() {
            if let Some(stream) = result.stream {
                self.last_product_ai_stream = Some(stream);
            }
            if !result.assistant_message_id.is_empty()
                && let Some(message) = self
                    .delegate_workflow
                    .chat_messages
                    .iter_mut()
                    .find(|m| m.message_id == result.assistant_message_id)
            {
                message.content_label = result.content_label;
                changed = true;
            }
            if let Some(proposal_source) = result.assist_proposal
                && let Some(job) = self.pending_assist_proposal.take()
            {
                match self.finish_assisted_edit_proposal_registration(job, proposal_source) {
                    Ok(_outcome) => {
                        changed = true;
                    }
                    Err(error) => {
                        // Leave stream projection; surface failure via empty proposal.
                        let _ = error;
                        changed = true;
                    }
                }
            }
        }
        changed
    }

    /// Time until the next app-owned proposal observation delivery retry.
    ///
    /// Desktop adapters can use this to request a repaint without busy-polling.
    pub fn proposal_observation_retry_delay(&self) -> Option<std::time::Duration> {
        self.proposal_observation_retry_schedule.map(|schedule| {
            schedule
                .next_attempt_at
                .saturating_duration_since(Instant::now())
        })
    }

    fn poll_scheduled_proposal_observation_retries(&mut self) -> bool {
        let Some(schedule) = self.proposal_observation_retry_schedule else {
            return false;
        };
        if Instant::now() < schedule.next_attempt_at {
            return false;
        }

        match self.retry_pending_proposal_observations() {
            Ok(report) => {
                let has_transient_pending = report.attempts.iter().any(|attempt| {
                    attempt.delivery_state
                        == legion_storage::ProposalObservationDeliveryState::Pending
                        && attempt.error_kind
                            == Some(legion_storage::ProposalObservationRetryErrorKind::Transient)
                });
                self.proposal_observation_retry_schedule = has_transient_pending.then(|| {
                    ProposalObservationRetrySchedule::after_retry_failure(schedule.failed_attempts)
                });
                report.delivered_count > 0
            }
            Err(_) => {
                self.proposal_observation_retry_schedule = Some(
                    ProposalObservationRetrySchedule::after_retry_failure(schedule.failed_attempts),
                );
                false
            }
        }
    }

    /// Clear the retained product AI stream (e.g. when leaving Assist/Delegate).
    pub fn clear_product_ai_stream(&mut self) {
        self.last_product_ai_stream = None;
    }

    /// Configure the optional ACP host command used by delegated tasks.
    #[cfg(any(test, feature = "test-helpers"))]
    pub fn set_acp_host_command(&mut self, program: impl Into<PathBuf>, args: Vec<String>) {
        self.acp_host_command = Some(AcpHostCommand::new(program, args));
    }

    /// Removes delegated-task sandbox directories left behind by crashed or
    /// abandoned lanes from a prior process. Intended to be called once by a
    /// production entry point before any delegated lane starts in the current
    /// process — never from a constructor or test harness, since those may run
    /// concurrently with other live sandboxes under the same relative path.
    ///
    /// Uses the default sandbox root (`target/delegated-tasks`, relative to
    /// the current working directory).
    ///
    /// An associated function (not a method): it uses no instance state, and
    /// callers are expected to invoke it before constructing an
    /// `AppComposition` at all.
    pub fn reap_orphaned_delegated_task_sandboxes() -> std::io::Result<Vec<PathBuf>> {
        Self::reap_orphaned_delegated_task_sandboxes_at(Path::new("target/delegated-tasks"))
    }

    /// Same as [`Self::reap_orphaned_delegated_task_sandboxes`], but against an
    /// explicit `delegated_tasks_root` rather than the default. Exists so
    /// callers (and tests) can target an isolated, temp-scoped root instead of
    /// the process-relative default.
    ///
    /// The orphan-detection rule (a `task-<run-id>` directory whose run id is
    /// not in the empty "active" list, since this only ever runs before any
    /// lane in the current process has started) lives in `legion-agent` when
    /// the `ai` feature is enabled. Offline builds have no `legion-agent`
    /// dependency, so this mirrors the same directory-walk logic locally
    /// rather than pulling that crate in just for this helper.
    pub fn reap_orphaned_delegated_task_sandboxes_at(
        delegated_tasks_root: &Path,
    ) -> std::io::Result<Vec<PathBuf>> {
        #[cfg(feature = "ai")]
        {
            legion_agent::reap_orphaned_sandboxes(delegated_tasks_root, &[])
        }
        #[cfg(not(feature = "ai"))]
        {
            offline_ai::reap_orphaned_sandboxes(delegated_tasks_root, &[])
        }
    }

    /// Current app-owned product mode.
    pub fn product_mode(&self) -> AppProductMode {
        self.product_mode
    }

    fn require_assist_mode(&self) -> Result<(), AppCompositionError> {
        if self.product_mode.allows_assist() {
            Ok(())
        } else {
            Err(AppCompositionError::AiRuntime(
                "AI dispatch requires Assist, Delegate, or Legion Workflows mode".to_string(),
            ))
        }
    }

    fn require_delegate_mode(&self) -> Result<(), AppCompositionError> {
        if self.product_mode.allows_delegate() {
            Ok(())
        } else {
            Err(AppCompositionError::AiRuntime(
                "Delegate dispatch requires Delegate or Legion Workflows mode".to_string(),
            ))
        }
    }

    /// Cancel the currently active worker loop by signalling its shared cancellation flag.
    ///
    /// This broad safety action is used by kill-switch owners and remains available
    /// even if a stale caller has already projected a lower product mode. It signals
    /// either a delegated task or a Legion workflow registration.
    pub fn cancel_delegated_task(&self) -> Result<(), AppCompositionError> {
        match &self.active_worker {
            Some(ActiveWorkerRegistration {
                cancellation_flag, ..
            }) => {
                cancellation_flag.cancel();
                Ok(())
            }
            None => Err(AppCompositionError::AiRuntime(
                "no delegated task running".to_string(),
            )),
        }
    }

    /// Cancel only a delegated-task worker, leaving Legion workflow workers untouched.
    ///
    /// UI actions that specifically mean "cancel delegated task" use this narrower
    /// entry point; workflow kill switches use [`Self::cancel_delegated_task`].
    pub fn cancel_delegated_task_only(&self) -> Result<(), AppCompositionError> {
        match &self.active_worker {
            Some(ActiveWorkerRegistration {
                identity: ActiveWorkerIdentity::DelegatedTask { .. },
                cancellation_flag,
                ..
            }) => {
                cancellation_flag.cancel();
                Ok(())
            }
            Some(ActiveWorkerRegistration {
                identity: ActiveWorkerIdentity::LegionWorkflow { session_id },
                ..
            }) => Err(AppCompositionError::AiRuntime(format!(
                "cannot cancel delegated task: active worker belongs to workflow {}",
                session_id.0
            ))),
            None => Err(AppCompositionError::AiRuntime(
                "no delegated task running".to_string(),
            )),
        }
    }

    /// Returns the workspace root path, falling back to CWD when no workspace is open.
    /// Used to ensure sandbox paths are anchored to the workspace, not the process CWD.
    #[cfg_attr(not(feature = "ai"), allow(dead_code))]
    fn workspace_root_path(&self) -> std::path::PathBuf {
        self.active_documents
            .workspace_root_path
            .as_ref()
            .map(std::path::PathBuf::from)
            .unwrap_or_else(|| std::env::current_dir().expect("current dir accessible"))
    }

    #[cfg(feature = "ai")]
    fn normalize_delegated_task_scope(
        &self,
        mut scope: legion_protocol::DelegatedTaskScope,
    ) -> Result<legion_protocol::DelegatedTaskScope, AppCompositionError> {
        let active_root = std::fs::canonicalize(self.workspace_root_path()).map_err(|error| {
            AppCompositionError::AiRuntime(format!(
                "active workspace root could not be canonicalized: {error}"
            ))
        })?;
        let selected_root = std::fs::canonicalize(&scope.workspace_root.0).map_err(|error| {
            AppCompositionError::AiRuntime(format!(
                "delegated scope workspace root could not be canonicalized: {error}"
            ))
        })?;
        if selected_root != active_root {
            return Err(AppCompositionError::AiRuntime(
                "delegated scope workspace root does not match the active workspace".to_string(),
            ));
        }
        scope.workspace_root = CanonicalPath(active_root.to_string_lossy().into_owned());

        let normalize_path = |path: &CanonicalPath,
                              label: &str|
         -> Result<std::path::PathBuf, AppCompositionError> {
            use std::path::Component;

            let raw = std::path::Path::new(&path.0);
            if raw.has_root() && !raw.is_absolute() {
                return Err(AppCompositionError::AiRuntime(format!(
                    "delegated scope {label} uses a rooted or drive-relative path without an absolute prefix"
                )));
            }
            let mut clean = std::path::PathBuf::new();
            for component in raw.components() {
                match component {
                    Component::ParentDir => {
                        return Err(AppCompositionError::AiRuntime(format!(
                            "delegated scope {label} contains parent traversal"
                        )));
                    }
                    Component::CurDir => {}
                    Component::Prefix(_) | Component::RootDir if !raw.is_absolute() => {
                        return Err(AppCompositionError::AiRuntime(format!(
                            "delegated scope {label} contains a misplaced root or prefix"
                        )));
                    }
                    _ => clean.push(component.as_os_str()),
                }
            }
            let path = if raw.is_absolute() {
                clean
            } else {
                active_root.join(clean)
            };
            resolve_existing_prefix(&path).ok_or_else(|| {
                AppCompositionError::AiRuntime(format!(
                    "delegated scope {label} contains an unresolvable path alias"
                ))
            })
        };

        match (scope.target_kind, scope.target_path.as_ref()) {
            (legion_protocol::DelegatedTaskScopeTargetKind::Repo, None) => {}
            (
                legion_protocol::DelegatedTaskScopeTargetKind::File
                | legion_protocol::DelegatedTaskScopeTargetKind::Module,
                Some(target),
            ) => {
                let target = normalize_path(target, "target")?;
                if !target.starts_with(&active_root) {
                    return Err(AppCompositionError::AiRuntime(
                        "delegated scope target is outside the active workspace".to_string(),
                    ));
                }
                scope.target_path = Some(CanonicalPath(target.to_string_lossy().into_owned()));
            }
            (legion_protocol::DelegatedTaskScopeTargetKind::Repo, Some(target)) => {
                let target = normalize_path(target, "target")?;
                if !target.starts_with(&active_root) {
                    return Err(AppCompositionError::AiRuntime(
                        "delegated scope target is outside the active workspace".to_string(),
                    ));
                }
                scope.target_path = Some(CanonicalPath(target.to_string_lossy().into_owned()));
            }
            (_, None) => {
                return Err(AppCompositionError::AiRuntime(
                    "file/module delegated scope requires a target path".to_string(),
                ));
            }
        }
        scope.forbidden_paths = scope
            .forbidden_paths
            .iter()
            .map(|path| {
                normalize_path(path, "forbidden path")
                    .map(|path| CanonicalPath(path.to_string_lossy().into_owned()))
            })
            .collect::<Result<Vec<_>, _>>()?;
        Ok(scope)
    }

    fn require_automate_mode(&self) -> Result<(), AppCompositionError> {
        if self.product_mode.allows_automate() {
            Ok(())
        } else {
            Err(AppCompositionError::AiRuntime(
                "Legion workflow dispatch requires Legion Workflows mode".to_string(),
            ))
        }
    }

    fn persist_latest_terminal_audit(&mut self) -> Result<(), AppCompositionError> {
        let Some(record) = self.terminal_workflow.take_last_audit() else {
            return Ok(());
        };
        self.storage
            .handle(StorageRepositoryRequest::SaveTerminalAuditRecord(
                record.clone(),
            ))
            .map_err(AppCompositionError::Protocol)?;
        let envelope = terminal_audit_recorded_event(&record)
            .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?;
        self.emit_event(envelope);
        Ok(())
    }

    fn persist_latest_debug_audit(&mut self) -> Result<(), AppCompositionError> {
        let Some(record) = self.debug_workflow.take_last_audit() else {
            return Ok(());
        };
        self.storage
            .handle(StorageRepositoryRequest::SaveDebugAdapterAuditRecord(
                record,
            ))
            .map_err(AppCompositionError::Protocol)?;
        Ok(())
    }

    fn persist_debug_breakpoints(&mut self) -> Result<(), AppCompositionError> {
        for (workspace_id, breakpoint_id) in self.debug_workflow.take_pending_breakpoint_deletes() {
            self.storage
                .handle(StorageRepositoryRequest::DeleteDebugBreakpointRecord {
                    workspace_id,
                    breakpoint_id,
                })
                .map_err(AppCompositionError::Protocol)?;
        }
        for record in &self.debug_workflow.breakpoints {
            self.storage
                .handle(StorageRepositoryRequest::SaveDebugBreakpointRecord(
                    record.clone(),
                ))
                .map_err(AppCompositionError::Protocol)?;
        }
        Ok(())
    }

    fn restore_debug_breakpoints_from_storage(&mut self) -> Result<(), AppCompositionError> {
        let workspace_id = self.active_documents.require_workspace_id()?;
        let response = self
            .storage
            .handle(StorageRepositoryRequest::ReadDebugBreakpointRecords { workspace_id })
            .map_err(AppCompositionError::Protocol)?;
        if let StorageRepositoryResponse::DebugBreakpointRecords(records) = response {
            self.debug_workflow.restore_breakpoints(records);
        }
        Ok(())
    }

    /// Open a workspace.
    pub fn open_workspace(
        &mut self,
        root: impl AsRef<Path>,
        trust: WorkspaceTrustState,
        principal: PrincipalId,
    ) -> Result<WorkspaceOpened, AppCompositionError> {
        let root_path = CanonicalPath(root.as_ref().to_string_lossy().into_owned());
        let request = WorkspaceOpenRequest {
            correlation_id: self.correlation_generator.next(),
            principal_id: principal.clone(),
            root_path: root_path.clone(),
            trust: Some(trust.clone()),
        };

        let opened = match self
            .workspace
            .handle(WorkspaceRequest::Open(request))
            .map_err(AppCompositionError::Protocol)?
        {
            WorkspaceResponse::Opened(opened) => opened,
            other => {
                return Err(AppCompositionError::Protocol(ProtocolError {
                    code: "workspace_open_unexpected_response".to_string(),
                    message: format!("expected opened response, got {other:?}"),
                }));
            }
        };
        self.active_documents
            .bind_workspace(opened.clone(), root_path, principal, trust.clone());
        self.debug_workflow.clear_workspace_state();
        self.assist_inline_prediction_state = AssistInlinePredictionState::default();
        self.palette = PaletteState::default();

        // Starting a language server launches a local process, so opening a
        // workspace must not start one implicitly. The user can approve that
        // boundary explicitly with the "Language Server: Start" command.

        // PKT-APPLY: Enable batch runtime apply for Trusted workspaces so that
        // `plan_batch_execution_contract` unblocks commit and finalize without
        // requiring callers to manually enable the policy.  Untrusted workspaces
        // (and any switch back to untrusted) remain fail-closed.
        self.batch_apply_policy.enabled = trust == WorkspaceTrustState::Trusted;

        Ok(opened)
    }

