    /// Open a file through workspace authority and bind it into editor engine.
    pub fn open_file(&mut self, path: impl AsRef<str>) -> Result<FileId, AppCompositionError> {
        self.open_file_with_intent(path, OpenFileIntent::Existing)
    }

    /// Open a new-file buffer only when the caller explicitly requested create intent.
    pub fn open_new_file(&mut self, path: impl AsRef<str>) -> Result<FileId, AppCompositionError> {
        self.open_file_with_intent(path, OpenFileIntent::CreateNew)
    }

    /// Open a file using an explicit open intent.
    pub fn open_file_with_intent(
        &mut self,
        path: impl AsRef<str>,
        intent: OpenFileIntent,
    ) -> Result<FileId, AppCompositionError> {
        let workspace_id = self.active_documents.require_workspace_id()?;
        let event_context = self.next_event_context();
        let opened = self.workspace.open_file_text(
            workspace_id,
            path.as_ref(),
            intent,
            Some(event_context),
        )?;
        self.bind_opened_file(opened)
    }

    fn bind_opened_file(&mut self, opened: OpenedFileText) -> Result<FileId, AppCompositionError> {
        let identity = opened.identity.clone();

        // For files above the editor's large-file threshold whose canonical path points to a
        // readable disk file, open the buffer via the streaming path. This avoids cloning the
        // workspace-provided `String` into a second allocation for the rope builder.
        let threshold = self.editor.thresholds().large_file_threshold_bytes;
        let disk_path = std::path::Path::new(&identity.canonical_path.0);
        // Use the workspace-captured file length for the streaming decision instead of
        // `text.len()`, which may differ from the on-disk size after encoding or truncation.
        // TODO: push streaming into the workspace layer so the String is never materialized
        // for files above the threshold. For now, the streaming path at least avoids a second
        // String->Rope copy by reading directly from disk.
        let file_byte_len = opened.file_length.unwrap_or(opened.text.len() as u64) as usize;
        let use_streaming = file_byte_len > threshold && disk_path.exists();

        let buffer_id = self
            .editor
            .buffer_for_file(identity.workspace_id, identity.file_id)
            .or_else(|| {
                self.editor
                    .buffer_for_path(identity.workspace_id, &identity.canonical_path.0)
            })
            .map_or_else(
                || {
                    if use_streaming {
                        self.editor.open_buffer_streaming(
                            identity.workspace_id,
                            identity.file_id,
                            identity.canonical_path.0.clone(),
                            disk_path,
                        )
                    } else {
                        self.editor.open_buffer(
                            identity.workspace_id,
                            identity.file_id,
                            identity.canonical_path.0.clone(),
                            opened.text.clone(),
                        )
                    }
                },
                Ok,
            )?;

        self.active_documents.bind_opened_file(&opened, buffer_id);

        // Skip full-text language-tooling indexing for streaming (large) files to avoid an
        // additional 100MB+ String clone. Large files are already in degraded mode where
        // semantic overlays, completions, and retrieval are deferred.
        if !use_streaming {
            let document = SourceDocument::with_versions(
                identity.workspace_id,
                identity.file_id,
                identity.canonical_path.clone(),
                language_id_for_path(&identity.canonical_path),
                opened.file_content_version,
                opened.workspace_generation,
                None,
                SemanticPrivacyScope::Workspace,
                opened.text.clone(),
            );
            self.language_tooling.refresh_retrieval_document(&document);
        }
        self.assist_inline_prediction_state
            .clear_for_buffer(buffer_id);

        Ok(identity.file_id)
    }

    /// Apply an edit command directly to the active editor-engine buffer.
    pub fn edit_active_buffer(
        &mut self,
        edit: TextEdit,
    ) -> Result<TextTransactionDescriptor, AppCompositionError> {
        let buffer_id = self.active_documents.require_active_buffer()?;
        let correlation_id = self.correlation_generator.next();
        let descriptor =
            self.apply_edit_to_buffer_with_correlation(buffer_id, edit.clone(), correlation_id)?;
        self.emit_transaction_event(&descriptor);
        let _ = self.maybe_request_next_edit_prediction_after_edit(
            buffer_id,
            edit.range.start.line as u32,
            edit.range.start.column as u32,
            &edit.new_text,
        );
        Ok(descriptor)
    }

    fn next_edit_prediction_target(
        &self,
        line: u32,
        column: u32,
        new_text: &str,
    ) -> TextCoordinate {
        let mut line = line;
        let mut character = column;
        if new_text.is_empty() {
            return TextCoordinate {
                line,
                character,
                byte_offset: None,
                utf16_offset: None,
            };
        }
        let newline_count = new_text.chars().filter(|ch| *ch == '\n').count() as u32;
        if newline_count == 0 {
            character = character.saturating_add(new_text.chars().count() as u32);
        } else {
            line = line.saturating_add(newline_count);
            character = new_text
                .rsplit('\n')
                .next()
                .map(|segment| segment.chars().count() as u32)
                .unwrap_or(0);
        }
        TextCoordinate {
            line,
            character,
            byte_offset: None,
            utf16_offset: None,
        }
    }

    fn maybe_request_next_edit_prediction_after_edit(
        &mut self,
        buffer_id: BufferId,
        line: u32,
        column: u32,
        new_text: &str,
    ) -> Result<(), AppCompositionError> {
        if !self.settings.next_edit_prediction_enabled || !self.product_mode.allows_assist() {
            return Ok(());
        }
        let target = self.next_edit_prediction_target(line, column, new_text);
        let _ = self.request_assist_inline_prediction(
            buffer_id,
            target,
            InlinePredictionTriggerKind::AfterEdit,
        )?;
        Ok(())
    }

    fn proposal_intent_id(intent: &CommandDispatchIntent) -> Option<ProposalId> {
        match intent {
            CommandDispatchIntent::PreviewProposal { proposal_id }
            | CommandDispatchIntent::ApproveProposal { proposal_id }
            | CommandDispatchIntent::RejectProposal { proposal_id, .. }
            | CommandDispatchIntent::ApplyProposal { proposal_id }
            | CommandDispatchIntent::RollbackProposal { proposal_id, .. }
            | CommandDispatchIntent::CancelProposal { proposal_id, .. }
            | CommandDispatchIntent::OpenProposalDetails { proposal_id } => Some(*proposal_id),
            _ => None,
        }
    }

    fn dispatch_proposal_ui_intent(
        &mut self,
        intent: CommandDispatchIntent,
        event_context: EventContext,
    ) -> Result<AppCommandOutcome, AppCompositionError> {
        let proposal_id = Self::proposal_intent_id(&intent)
            .ok_or(AppCompositionError::ProposalIntentMissingProposal)?;
        let proposal = self
            .proposal_coordinator
            .proposal_for_id(proposal_id)
            .ok_or(AppCompositionError::ProposalIntentMismatch {
                target: proposal_id,
                active: None,
            })?;
        let context = AppProposalIntentRouteContext {
            proposal: Some(proposal.clone()),
            principal: proposal.principal.clone(),
            capability: proposal.capability.clone(),
            correlation_id: event_context.correlation_id,
            causality_id: event_context.causality_id,
            requested_at: TimestampMillis::now(),
        };
        let routed = CommandDispatcher::route_proposal_intent(intent, context)?;
        self.proposal_coordinator
            .select_proposal_for_details(proposal_id);

        if let Some(request) = routed {
            let response = self.handle_routed_proposal_request(request)?;
            Ok(AppCommandOutcome::ProposalLifecycleUpdated(response))
        } else {
            Ok(AppCommandOutcome::ProposalDetailsOpened(proposal_id))
        }
    }

    fn handle_routed_proposal_request(
        &mut self,
        request: ProposalRequest,
    ) -> Result<ProposalResponse, AppCompositionError> {
        if let ProposalRequest::Preview(proposal) = &request
            && self
                .proposal_coordinator
                .current_lifecycle_state(proposal.proposal_id)
                == Some(ProposalLifecycleState::Created)
        {
            let validated =
                self.handle_proposal_request(ProposalRequest::Validate(proposal.clone()))?;
            if !matches!(validated, ProposalResponse::Validated(_)) {
                return Ok(validated);
            }
        }
        self.handle_proposal_request(request)
    }

    fn open_palette(
        &mut self,
        mode: PaletteMode,
        query: String,
        scope: SearchScopeProjection,
    ) -> Result<PaletteProjection, AppCompositionError> {
        self.palette.pending_confirmation = None;
        self.palette.open = true;
        self.palette.mode = mode;
        self.palette.query = palette_open_query(mode, query);
        self.palette.scope = scope;
        self.palette.selected_index = 0;
        self.refresh_palette_results()?;
        if mode == PaletteMode::Search {
            self.sync_search_palette_results();
        }
        Ok(self.palette.projection())
    }

    fn update_palette_query(
        &mut self,
        query: String,
    ) -> Result<PaletteProjection, AppCompositionError> {
        self.palette.pending_confirmation = None;
        self.palette.open = true;
        self.palette.query = query;
        self.palette.selected_index = 0;
        self.refresh_palette_results()?;
        Ok(self.palette.projection())
    }

    fn close_palette(&mut self) -> PaletteProjection {
        self.palette.close();
        self.palette.projection()
    }

    fn move_palette_selection(&mut self, delta: i32) -> PaletteProjection {
        self.palette.pending_confirmation = None;
        if self.palette.results.is_empty() {
            self.palette.selected_index = 0;
            return self.palette.projection();
        }

        if self.palette.mode == PaletteMode::Command {
            let available = self
                .palette
                .results
                .iter()
                .enumerate()
                .filter_map(|(index, result)| result.disabled_reason.is_none().then_some(index))
                .collect::<Vec<_>>();
            if available.is_empty() {
                self.palette.selected_index = self.palette.results.len();
                return self.palette.projection();
            }
            let current = available
                .iter()
                .position(|index| *index == self.palette.selected_index)
                .unwrap_or(0) as i32;
            let next = (current + delta).clamp(0, available.len() as i32 - 1) as usize;
            self.palette.selected_index = available[next];
            return self.palette.projection();
        }

        let max_index = self.palette.results.len() as i32 - 1;
        let next = (self.palette.selected_index as i32 + delta).clamp(0, max_index);
        self.palette.selected_index = next as usize;
        self.palette.projection()
    }

    fn complete_palette_selection(&mut self) -> Result<PaletteProjection, AppCompositionError> {
        self.palette.pending_confirmation = None;
        if !self.palette.open {
            return Ok(self.palette.projection());
        }
        if self.palette.mode != PaletteMode::File || self.palette.results.len() != 1 {
            return Ok(self.palette.projection());
        }
        let Some(title) = self
            .palette
            .results
            .first()
            .map(|result| result.title.clone())
        else {
            return Ok(self.palette.projection());
        };
        self.palette.query = title;
        self.palette.selected_index = 0;
        self.refresh_palette_results()?;
        Ok(self.palette.projection())
    }

    fn dispatch_palette_selection(&mut self) -> Result<AppCommandOutcome, AppCompositionError> {
        if !self.palette.open {
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        }
        if self.palette.pending_confirmation.is_some() {
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        }
        let Some(result) = self
            .palette
            .results
            .get(self.palette.selected_index)
            .cloned()
        else {
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        };
        if result.disabled_reason.is_some() {
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        }
        let Some(intent) = self.palette_result_intent(&result) else {
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        };

        if palette_command_requires_confirmation(&result.id) {
            let operands = self.palette_result_operands(&result);
            let token = self.palette.next_confirmation_token();
            self.palette.pending_confirmation = Some(PendingPaletteConfirmation {
                projection: legion_ui::PaletteConfirmationProjection {
                    token,
                    command_id: result.id.clone(),
                    operands,
                    title: result.title.clone(),
                    detail: result.detail.clone(),
                },
                intent,
            });
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        }

        // Record metadata-only usage count for frequency blending.
        // Uses `result.id` as the item key (stable command/file identifier).
        // No raw query text is persisted.
        if let Some(workspace_id) = self.active_documents.workspace_id() {
            self.palette_usage.record_usage(workspace_id, &result.id);
        }

        if matches!(result.id.as_str(), "search:run" | "search:retry") {
            let outcome = self.dispatch_ui_intent(intent)?;
            self.sync_search_palette_results();
            return Ok(outcome);
        }

        self.palette.close();
        self.dispatch_ui_intent(intent)
    }

    fn confirm_palette_selection(
        &mut self,
        token: u64,
        command_id: String,
        operands: Vec<String>,
    ) -> Result<AppCommandOutcome, AppCompositionError> {
        let Some(pending) = self.palette.pending_confirmation.clone() else {
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        };
        if pending.projection.token != token
            || pending.projection.command_id != command_id
            || pending.projection.operands != operands
        {
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        }

        let Some(result) = self
            .palette
            .results
            .get(self.palette.selected_index)
            .cloned()
        else {
            self.palette.pending_confirmation = None;
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        };
        let current_operands = self.palette_result_operands(&result);
        let current_intent = self.palette_result_intent(&result);
        if result.disabled_reason.is_some()
            || result.id != command_id
            || current_operands != operands
            || current_intent.as_ref() != Some(&pending.intent)
        {
            self.palette.pending_confirmation = None;
            return Ok(AppCommandOutcome::PaletteUpdated(self.palette.projection()));
        }

        self.palette.pending_confirmation = None;
        if let Some(workspace_id) = self.active_documents.workspace_id() {
            self.palette_usage.record_usage(workspace_id, &result.id);
        }
        self.palette.close();
        self.dispatch_ui_intent(pending.intent)
    }

    fn cancel_palette_confirmation(&mut self, token: u64) -> PaletteProjection {
        if self
            .palette
            .pending_confirmation
            .as_ref()
            .is_some_and(|pending| pending.projection.token == token)
        {
            self.palette.pending_confirmation = None;
        }
        self.palette.projection()
    }

    fn sync_search_palette_results(&mut self) {
        if !self.palette.open
            || self.palette.mode != PaletteMode::Search
            || self.palette.scope != self.search_projection.scope
            || palette_query_body(PaletteMode::Search, &self.palette.query).trim()
                != self.search_projection.query_label
        {
            return;
        }

        let mut results = self
            .search_projection
            .results
            .iter()
            .enumerate()
            .map(|(index, row)| {
                let location = row
                    .file_path
                    .as_ref()
                    .map(|path| path.0.as_str())
                    .unwrap_or("Current file");
                let mut detail = row.snippet.clone();
                if row.snippet_truncated {
                    detail.push_str(" · preview shortened");
                }
                if row.stale {
                    detail.push_str(" · outdated");
                }
                PaletteResult {
                    id: format!("search:match:{}:{index}", row.query_id),
                    kind: PaletteResultKind::Search,
                    title: format!(
                        "{location}:{}:{}",
                        row.line_number.saturating_add(1),
                        row.range.start.character.saturating_add(1)
                    ),
                    detail: Some(detail),
                    shortcut_label: Some("Enter".to_string()),
                    path: row.file_path.as_ref().map(|path| path.0.clone()),
                    buffer_id: row.buffer_id,
                    position: Some(row.range.start),
                    match_indices: Vec::new(),
                    disabled_reason: None,
                }
            })
            .collect::<Vec<_>>();
        if matches!(
            self.search_projection.status.kind,
            SearchStatusKindProjection::NoResults
                | SearchStatusKindProjection::ValidationError
                | SearchStatusKindProjection::Error
                | SearchStatusKindProjection::Cancelled
                | SearchStatusKindProjection::DegradedLimited
        ) {
            results.insert(
                0,
                PaletteResult {
                    id: "search:retry".to_string(),
                    kind: PaletteResultKind::Search,
                    title: format!(
                        "Run search again for \"{}\"",
                        self.search_projection.query_label
                    ),
                    detail: Some("Retry this search".to_string()),
                    shortcut_label: Some("Enter".to_string()),
                    path: None,
                    buffer_id: None,
                    position: None,
                    match_indices: Vec::new(),
                    disabled_reason: None,
                },
            );
        }
        self.palette.results = results;
        self.palette.selected_index = 0;
    }

