    /// Send a Delegate chat turn using local, metadata-only codebase retrieval citations.
    pub fn send_delegate_chat(
        &mut self,
        prompt_label: impl Into<String>,
    ) -> Result<AppDelegateChatOutcome, AppCompositionError> {
        self.require_delegate_mode()?;
        let prompt_label = bounded_label(prompt_label.into(), 240);
        let lane_reservation = ProductAiLaneReservation::try_acquire(
            self.live_product_ai_stream.clone(),
            "delegate.chat",
            "pending",
            "",
        )
        .ok_or_else(|| {
            AppCompositionError::AiRuntime(
                "product AI provider lane is busy; poll the active result before dispatching another request"
                    .to_string(),
            )
        })?;
        let buffer_id = self.active_documents.require_active_buffer()?;
        let context = self.active_documents.save_context_for_buffer(buffer_id)?;
        let event_context = self.next_event_context();
        let input = self.language_request_input(buffer_id, event_context)?;
        let language_id = language_id_for_path(&input.metadata.identity.canonical_path);
        let buffer_excerpt = input.text.chars().take(3_000).collect::<String>();
        let document = SourceDocument::with_versions(
            input.workspace_id,
            input.metadata.identity.file_id,
            input.metadata.identity.canonical_path.clone(),
            language_id.clone(),
            input.metadata.file_content_version,
            input.metadata.workspace_generation,
            Some(input.snapshot_id),
            SemanticPrivacyScope::Workspace,
            input.text,
        );
        self.language_tooling.refresh_retrieval_document(&document);
        let citations = self
            .language_tooling
            .search_retrieval(&RetrievalQuery {
                workspace_id: input.workspace_id,
                query_text: prompt_label.clone(),
                file_ids: vec![input.metadata.identity.file_id],
                paths: vec![input.metadata.identity.canonical_path.clone()],
                language_ids: vec![language_id],
                privacy_scope: SemanticPrivacyScope::Workspace,
                freshness_policy: SemanticQueryFreshnessPolicy::RequireFresh,
                limit: 5,
                schema_version: 1,
            })
            .into_iter()
            .map(delegate_context_citation_from_retrieval)
            .collect::<Vec<_>>();
        let citation_ids = citations
            .iter()
            .map(|citation| citation.citation_id.clone())
            .collect::<Vec<_>>();
        self.delegate_workflow.context_citations.extend(citations);

        let permission_request_id = delegated_context_permission_request_id(input.workspace_id);
        let permission = self.delegate_workflow.record_tool_permission_decision(
            DelegatedTaskToolPermissionRequestInput {
                request_id: permission_request_id,
                profile: DelegatedTaskToolPermissionProfile::Ask,
                action_class: PermissionBudgetActionClass::ReadSemanticMetadata,
                capability: Some(CapabilityId("delegated.context.retrieve".to_string())),
                target_id: Some(input.metadata.identity.file_id.0.to_string()),
                decision: DelegatedTaskToolPermissionDecision::Confirm,
                labels: delegated_context_permission_labels(),
                schema_version: 1,
            },
        );
        let context_reference = trust_reference(
            &format!("delegate:context:{}", input.metadata.identity.file_id.0),
            legion_protocol::AssistedAiTrustProjectionKind::ContextManifest,
        );
        let privacy_reference = trust_reference(
            &format!("delegate:privacy:{}", input.metadata.identity.file_id.0),
            legion_protocol::AssistedAiTrustProjectionKind::PrivacyInspector,
        );
        let permission_reference = trust_reference(
            &format!("delegate:permission-budget:{}", permission.request_id),
            legion_protocol::AssistedAiTrustProjectionKind::PermissionBudget,
        );
        let prompt_fingerprint = metadata_fingerprint("delegate-prompt", &prompt_label);
        let citation_fingerprint =
            metadata_fingerprint("delegate-citations", &citation_ids.join("|"));
        let provider_route_request = legion_protocol::AssistedAiProviderRouteRequest {
            route_id: format!(
                "delegate-chat-route:{}:{}",
                input.workspace_id.0,
                self.event_sequence_generator.next().0
            ),
            provider_id: DETERMINISTIC_LOCAL_PROVIDER_ID.to_string(),
            model_label: "deterministic-local-delegate".to_string(),
            provider_class: AssistedAiProviderClass::Local,
            operation_class: AssistedAiOperationClass::Explain,
            context_manifest: context_reference,
            privacy_inspector: privacy_reference,
            permission_budget: permission_reference,
            prompt_prefix: String::new(),
            proposal_intent: legion_protocol::AssistedAiProposalTargetIntent {
                payload_kind: legion_protocol::ProposalPayloadKind::CodeAction,
                target_coverage: ProposalTargetCoverage {
                    coverage_kind: ProposalTargetCoverageKind::Complete,
                    targets: vec![ProposalAffectedTarget {
                        target_id: format!("delegate-chat:{}", input.metadata.identity.file_id.0),
                        kind: ProposalTargetKind::MetadataOnly,
                        workspace_id: Some(input.workspace_id),
                        file_id: Some(input.metadata.identity.file_id),
                        buffer_id: Some(buffer_id),
                        path: Some(input.metadata.identity.canonical_path.clone()),
                        terminal_session_id: None,
                        plugin_id: None,
                        remote_authority: None,
                        collaboration_session_id: None,
                        byte_ranges: vec![ByteRange::new(0, 0)],
                        redaction_hints: vec![RedactionHint::MetadataOnly],
                    }],
                    omitted_target_count: 0,
                    redaction_hints: vec![RedactionHint::MetadataOnly],
                },
                required_capability: CapabilityId("ai.provider.invoke".to_string()),
                risk_label: ProposalRiskLabel::Low,
                privacy_label: legion_protocol::ProposalPrivacyLabel::WorkspaceMetadata,
                labels: vec![
                    "delegate.chat.provider_route".to_string(),
                    format!("delegate.prompt:{}", prompt_fingerprint.value),
                    format!("delegate.citations:{}", citation_fingerprint.value),
                    format!("delegate.citation_count:{}", citation_ids.len()),
                ],
                redaction_hints: vec![RedactionHint::MetadataOnly],
                schema_version: 1,
            },
            policy_decision_id: None,
            required_capability: CapabilityId("ai.provider.invoke".to_string()),
            network_target: Some(legion_protocol::NetworkTarget {
                scheme: "http".to_string(),
                host: "localhost".to_string(),
                port: Some(11434),
            }),
            cancellation_token: CancellationTokenId(uuid::Uuid::now_v7()),
            health_labels: vec!["delegate.local.deterministic".to_string()],
            cost_labels: vec!["local.free".to_string()],
            principal_id: input.principal.clone(),
            workspace_trust_state: context.trust.clone(),
            correlation_id: event_context.correlation_id,
            causality_id: event_context.causality_id,
            event_sequence: self.event_sequence_generator.next(),
            redaction_hints: vec![RedactionHint::MetadataOnly],
            schema_version: 1,
        };
        let broker = DenyByDefaultBroker::new(
            SecurityPolicy::default(),
            CapabilityNamespace("app.delegate".to_string()),
        );
        let provider_route_response = ProviderRouter::new(&self.ai_registry, &broker)
            .route_completion(provider_route_request)
            .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?;
        // Policy router is metadata-only; product chat text comes from a live
        // provider when credentials exist, else a deterministic fixture label.
        let route_completed = provider_route_response.invocation_state
            == AssistedAiProviderInvocationState::Completed;
        #[cfg(feature = "ai")]
        let use_background_live =
            route_completed && product_ai_will_attempt_live(self.preferred_ai_provider);
        #[cfg(not(feature = "ai"))]
        let use_background_live = false;
        let user_message_id = self
            .delegate_workflow
            .next_message_id(DelegatedTaskChatRole::User);
        let assistant_message_id = self
            .delegate_workflow
            .next_message_id(DelegatedTaskChatRole::Assistant);
        let created_at = TimestampMillis::now();
        self.delegate_workflow
            .chat_messages
            .push(DelegatedTaskChatMessage {
                message_id: user_message_id.clone(),
                role: DelegatedTaskChatRole::User,
                content_label: prompt_label.clone(),
                plan_id: None,
                proposal_id: None,
                citation_ids: Vec::new(),
                tool_permission_request_ids: vec![permission.request_id.clone()],
                correlation_id: event_context.correlation_id,
                causality_id: event_context.causality_id,
                created_at,
                redaction_hints: vec![RedactionHint::MetadataOnly],
                schema_version: 1,
            });

        let assistant_content_label = if !route_completed {
            lane_reservation.finish(None);
            format!(
                "Delegate provider refused; citation(s)={} route={} reason={}",
                citation_ids.len(),
                provider_route_response.route_id,
                provider_route_response
                    .refusal
                    .as_ref()
                    .map(|refusal| refusal.reason_code.as_str())
                    .unwrap_or("unknown")
            )
        } else if use_background_live {
            // Non-blocking path: stream on a worker thread; poll_product_ai_stream
            // finalizes the assistant message when generation completes.
            let preference = self.preferred_ai_provider;
            let file_path = input.metadata.identity.canonical_path.0.clone();
            let route_id = provider_route_response.route_id.clone();
            let route_labels = provider_route_response.output_labels.clone();
            let citation_count = citation_ids.len();
            let assistant_id = assistant_message_id.clone();
            let prompt_for_worker = prompt_label.clone();
            let excerpt_for_worker = buffer_excerpt.clone();
            let sink_delta = lane_reservation.sink();
            std::thread::Builder::new()
                .name("legion-delegate-chat".to_string())
                .spawn(move || {
                    let mut on_delta = move |delta: &str| sink_delta.push_delta(delta);
                    let (label, stream) = resolve_delegate_chat_reply(
                        preference,
                        &prompt_for_worker,
                        &excerpt_for_worker,
                        &file_path,
                        citation_count,
                        &route_id,
                        &route_labels,
                        Some(&mut on_delta),
                    );
                    let completion = stream.as_ref().map(|stream| ProductChatCompletion {
                        provider_id: stream.provider_id.clone(),
                        model: stream.model.clone(),
                        text: stream.text_preview.clone(),
                        stream_chunks: stream.chunks.clone(),
                        streamed: stream.streamed,
                    });
                    lane_reservation.finish_background(
                        ProductAiBackgroundResult {
                            assistant_message_id: assistant_id,
                            content_label: label,
                            stream,
                            assist_proposal: None,
                        },
                        completion.as_ref(),
                    );
                })
                .map_err(|error| {
                    AppCompositionError::AiRuntime(format!(
                        "failed to spawn Delegate chat worker: {error}"
                    ))
                })?;
            "Streaming response…".to_string()
        } else {
            let sink_delta = lane_reservation.sink();
            let mut on_delta = move |delta: &str| sink_delta.push_delta(delta);
            let (label, stream) = resolve_delegate_chat_reply(
                self.preferred_ai_provider,
                &prompt_label,
                &buffer_excerpt,
                &input.metadata.identity.canonical_path.0,
                citation_ids.len(),
                &provider_route_response.route_id,
                &provider_route_response.output_labels,
                Some(&mut on_delta),
            );
            if let Some(stream) = stream {
                lane_reservation.finish(Some(&ProductChatCompletion {
                    provider_id: stream.provider_id.clone(),
                    model: stream.model.clone(),
                    text: stream.text_preview.clone(),
                    stream_chunks: stream.chunks.clone(),
                    streamed: stream.streamed,
                }));
                self.last_product_ai_stream = Some(stream);
            } else {
                lane_reservation.finish(None);
            }
            label
        };

        self.delegate_workflow
            .chat_messages
            .push(DelegatedTaskChatMessage {
                message_id: assistant_message_id.clone(),
                role: DelegatedTaskChatRole::Assistant,
                content_label: assistant_content_label,
                plan_id: None,
                proposal_id: None,
                citation_ids: citation_ids.clone(),
                tool_permission_request_ids: vec![permission.request_id],
                correlation_id: event_context.correlation_id,
                causality_id: event_context.causality_id,
                created_at,
                redaction_hints: vec![RedactionHint::MetadataOnly],
                schema_version: 1,
            });
        let projection = self.current_delegated_task_projection(TimestampMillis::now());
        Ok(AppDelegateChatOutcome {
            projection,
            user_message_id,
            assistant_message_id,
            citation_count: citation_ids.len(),
        })
    }

    /// Record a human disposition for one projected Delegate proposal hunk.
    pub fn review_delegate_proposal_hunk(
        &mut self,
        proposal_id: ProposalId,
        hunk_id: impl Into<String>,
        disposition: DelegatedTaskProposalHunkDisposition,
    ) -> Result<DelegatedTaskProjection, AppCompositionError> {
        self.require_delegate_mode()?;
        let hunk_id = hunk_id.into();
        let generated_at = TimestampMillis::now();
        let proposal_ledger = self
            .proposal_coordinator
            .proposal_ledger_projection(generated_at);
        let row = proposal_ledger
            .rows
            .iter()
            .find(|row| row.proposal_id == proposal_id)
            .ok_or_else(|| {
                AppCompositionError::AiRuntime(format!(
                    "Delegate proposal {} is not present in the proposal ledger",
                    proposal_id.0
                ))
            })?;
        let known_hunk = proposal_review_chunks(row)
            .iter()
            .any(|chunk| delegate_hunk_id(proposal_id, chunk) == hunk_id);
        if !known_hunk {
            return Err(AppCompositionError::AiRuntime(format!(
                "Delegate proposal hunk `{hunk_id}` is not present in proposal {}",
                proposal_id.0
            )));
        }
        self.delegate_workflow
            .hunk_decisions
            .insert((proposal_id, hunk_id), disposition);
        Ok(self.delegated_task_projection(generated_at, &proposal_ledger))
    }

    /// Record a human decision for one Delegate tool permission request.
    pub fn record_delegate_tool_permission_decision(
        &mut self,
        request_id: impl Into<String>,
        decision: DelegatedTaskToolPermissionDecision,
    ) -> Result<DelegatedTaskProjection, AppCompositionError> {
        self.require_delegate_mode()?;
        let request_id = request_id.into();
        let existing = self.delegate_workflow.tool_permission(&request_id).cloned();
        let (profile, action_class, capability, target_id, labels) =
            if let Some(existing) = existing {
                (
                    existing.profile,
                    existing.action_class,
                    existing.capability,
                    existing.target_id,
                    existing.labels,
                )
            } else {
                (
                    DelegatedTaskToolPermissionProfile::Write,
                    PermissionBudgetActionClass::AccessWorkspaceFiles,
                    Some(CapabilityId("delegated.runtime.allocate".to_string())),
                    None,
                    vec!["delegate.permission.write.runtime_allocation".to_string()],
                )
            };
        self.delegate_workflow.record_tool_permission_decision(
            DelegatedTaskToolPermissionRequestInput {
                request_id,
                profile,
                action_class,
                capability,
                target_id,
                decision,
                labels,
                schema_version: 1,
            },
        );
        Ok(self.current_delegated_task_projection(TimestampMillis::now()))
    }

    fn language_request_input(
        &mut self,
        buffer_id: BufferId,
        event_context: EventContext,
    ) -> Result<LanguageRequestInput, AppCompositionError> {
        self.active_documents.ensure_active_buffer(buffer_id)?;
        let metadata = self
            .active_documents
            .metadata_for_buffer(buffer_id)
            .cloned()
            .ok_or(AppCompositionError::ActiveFileMissing)?;
        let snapshot_id = self.editor.current_snapshot(buffer_id)?.snapshot_id;
        let buffer_version = self.editor.buffer_version(buffer_id)?;
        let text = self.editor.text(buffer_id)?.to_string();
        let principal = self
            .active_documents
            .active_principal_id
            .clone()
            .ok_or(AppCompositionError::WorkspaceNotOpen)?;
        Ok(LanguageRequestInput {
            workspace_id: metadata.identity.workspace_id,
            buffer_id,
            metadata,
            principal,
            text,
            snapshot_id,
            buffer_version,
            event_context,
        })
    }

    fn run_language_read(
        &mut self,
        buffer_id: BufferId,
        kind: LanguageReadKind,
        position: TextCoordinate,
    ) -> Result<LanguageToolingProjection, AppCompositionError> {
        let event_context = self.next_event_context();
        let input = self.language_request_input(buffer_id, event_context)?;
        Ok(self.language_tooling.run_read(input, kind, position))
    }

    fn request_assist_inline_prediction(
        &mut self,
        buffer_id: BufferId,
        position: TextCoordinate,
        trigger: InlinePredictionTriggerKind,
    ) -> Result<AssistInlinePredictionProjection, AppCompositionError> {
        self.require_assist_mode()?;
        self.active_documents.ensure_active_buffer(buffer_id)?;
        let context = self.active_documents.save_context_for_buffer(buffer_id)?;
        let snapshot = self.editor.current_snapshot(buffer_id)?.clone();
        let event_context = self.next_event_context();
        let metadata = self.inline_prediction_request_metadata(
            &context,
            InlinePredictionRequestArgs {
                snapshot_id: snapshot.snapshot_id,
                buffer_version: snapshot.buffer_version,
                content_hash: snapshot.content_hash.as_str(),
                cursor: position,
                trigger,
                event_context,
            },
        );
        metadata
            .validate()
            .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?;

        self.assist_inline_prediction_state.request_in_flight = true;
        self.assist_inline_prediction_state.active_request_id = Some(metadata.request_id.clone());
        self.assist_inline_prediction_state
            .requests
            .insert(metadata.request_id.clone(), metadata.clone());

        let result = match self.invoke_inline_prediction_provider(metadata) {
            Ok(result) => result,
            Err(error) => {
                self.assist_inline_prediction_state.request_in_flight = false;
                self.assist_inline_prediction_state.active_request_id = None;
                return Err(error);
            }
        };
        self.assist_inline_prediction_state.results.push(result);
        self.assist_inline_prediction_state.request_in_flight = false;
        self.assist_inline_prediction_state.retain_bounded_history();
        Ok(self.assist_inline_prediction_projection(TimestampMillis::now()))
    }

    fn accept_assist_inline_prediction(
        &mut self,
        buffer_id: BufferId,
        prediction_id: Option<String>,
    ) -> Result<AssistInlinePredictionProjection, AppCompositionError> {
        self.require_assist_mode()?;
        self.active_documents.ensure_active_buffer(buffer_id)?;
        let Some(index) = self.resolve_inline_prediction_index(buffer_id, prediction_id.as_deref())
        else {
            return Err(AppCompositionError::AiRuntime(
                "no active Assist inline prediction is available".to_string(),
            ));
        };
        self.validate_inline_prediction_lifecycle(index, InlinePredictionLifecycleAction::Accept)?;

        let observed = self.inline_prediction_observed_fingerprint(buffer_id)?;
        let freshness = InlinePredictionFreshness::from_fingerprints(
            &self.assist_inline_prediction_state.results[index].fingerprint,
            &observed,
            1,
        );
        if freshness.state == InlinePredictionFreshnessState::Stale {
            self.mark_inline_prediction_stale(index, freshness)?;
            return Ok(self.assist_inline_prediction_projection(TimestampMillis::now()));
        }

        let context = self.active_documents.save_context_for_buffer(buffer_id)?;
        let result = self.assist_inline_prediction_state.results[index].clone();
        let ghost_text = result.ghost_text.ok_or_else(|| {
            AppCompositionError::AiRuntime(
                "Assist inline prediction has no ghost text to accept".to_string(),
            )
        })?;
        let range = Self::inline_prediction_edit_range(result.insert_range)?;
        let event_context = self.next_event_context();
        let record = self
            .editor
            .apply_protocol_edits(EditorApplyTransactionRequest {
                workspace_id: context.workspace_id,
                buffer_id,
                file_id: context.metadata.identity.file_id,
                edits: EditBatch {
                    edits: vec![legion_protocol::TextEdit {
                        range,
                        replacement: ghost_text.text,
                    }],
                },
                source: TransactionSource::User,
                undo_group_id: Some(uuid::Uuid::now_v7()),
                correlation_id: event_context.correlation_id,
            })?;
        let descriptor = record.to_protocol_descriptor();
        self.emit_transaction_event(&descriptor);
        self.mark_inline_prediction_lifecycle(index, InlinePredictionResultState::Accepted)?;
        Ok(self.assist_inline_prediction_projection(TimestampMillis::now()))
    }

    fn dismiss_assist_inline_prediction(
        &mut self,
        buffer_id: BufferId,
        prediction_id: Option<String>,
    ) -> Result<AssistInlinePredictionProjection, AppCompositionError> {
        self.require_assist_mode()?;
        self.active_documents.ensure_active_buffer(buffer_id)?;
        let Some(index) = self.resolve_inline_prediction_index(buffer_id, prediction_id.as_deref())
        else {
            return Ok(self.assist_inline_prediction_projection(TimestampMillis::now()));
        };
        self.validate_inline_prediction_lifecycle(index, InlinePredictionLifecycleAction::Dismiss)?;
        self.mark_inline_prediction_lifecycle(index, InlinePredictionResultState::Dismissed)?;
        Ok(self.assist_inline_prediction_projection(TimestampMillis::now()))
    }

    fn cancel_assist_inline_prediction(
        &mut self,
        buffer_id: BufferId,
        prediction_id: Option<String>,
    ) -> Result<AssistInlinePredictionProjection, AppCompositionError> {
        self.require_assist_mode()?;
        self.active_documents.ensure_active_buffer(buffer_id)?;
        let Some(index) = self.resolve_inline_prediction_index(buffer_id, prediction_id.as_deref())
        else {
            self.assist_inline_prediction_state.request_in_flight = false;
            self.assist_inline_prediction_state.active_request_id = None;
            return Ok(self.assist_inline_prediction_projection(TimestampMillis::now()));
        };
        self.validate_inline_prediction_lifecycle(index, InlinePredictionLifecycleAction::Cancel)?;
        self.mark_inline_prediction_lifecycle(index, InlinePredictionResultState::Cancelled)?;
        Ok(self.assist_inline_prediction_projection(TimestampMillis::now()))
    }

    fn inline_prediction_request_metadata(
        &mut self,
        context: &ActiveSaveContext,
        args: InlinePredictionRequestArgs<'_>,
    ) -> InlinePredictionRequestMetadata {
        let language_id = language_id_for_path(&context.metadata.identity.canonical_path);
        let requested_at = TimestampMillis::now();
        InlinePredictionRequestMetadata {
            request_id: InlinePredictionRequestId(format!(
                "assist-inline:req:{}:{}",
                args.event_context.correlation_id.0, args.snapshot_id.0
            )),
            workspace_id: context.workspace_id,
            buffer_id: context.buffer_id,
            file_id: Some(context.metadata.identity.file_id),
            language_id,
            cursor: args.cursor,
            selection: None,
            visible_range: None,
            trigger: args.trigger,
            fingerprint: self.inline_prediction_fingerprint(
                context,
                args.snapshot_id,
                args.buffer_version,
                args.content_hash,
            ),
            provider: InlinePredictionProviderMetadata {
                provider_id: DETERMINISTIC_LOCAL_PROVIDER_ID.to_string(),
                model_label: "zeta2-style-deterministic".to_string(),
                provider_class: AssistedAiProviderClass::Local,
                operation_class: AssistedAiOperationClass::InlinePrediction,
                invocation_state: AssistedAiProviderInvocationState::Planned,
                latency: InlinePredictionLatencyMetadata {
                    queued_ms: 0,
                    inference_ms: 0,
                    total_ms: 0,
                    timed_out: false,
                },
                health_labels: vec!["local".to_string(), "deterministic".to_string()],
                cost_labels: vec!["offline".to_string()],
                redaction_hints: vec![RedactionHint::MetadataOnly],
                schema_version: 1,
            },
            max_prediction_bytes: INLINE_PREDICTION_MAX_GHOST_TEXT_BYTES.min(256),
            timeout_ms: 250,
            requested_at,
            cancellation_token: CancellationTokenId(uuid::Uuid::now_v7()),
            required_capability: CapabilityId("ai.inline_prediction.invoke".to_string()),
            principal_id: context.principal.clone(),
            workspace_trust_state: context.trust.clone(),
            correlation_id: args.event_context.correlation_id,
            causality_id: args.event_context.causality_id,
            event_sequence: self.event_sequence_generator.next(),
            redaction_hints: vec![RedactionHint::MetadataOnly],
            schema_version: 1,
        }
    }

    fn inline_prediction_fingerprint(
        &self,
        context: &ActiveSaveContext,
        snapshot_id: legion_protocol::SnapshotId,
        buffer_version: BufferVersion,
        content_hash: &str,
    ) -> InlinePredictionFingerprintMetadata {
        InlinePredictionFingerprintMetadata {
            snapshot_id,
            buffer_version,
            file_content_version: Some(context.metadata.file_content_version),
            workspace_generation: context.metadata.workspace_generation,
            content_fingerprint: Some(FileFingerprint {
                algorithm: "legion-text-snapshot".to_string(),
                value: content_hash.to_string(),
            }),
            context_fingerprint: metadata_fingerprint(
                "assist-inline-context",
                &format!(
                    "{}:{}:{}:{}",
                    context.workspace_id.0,
                    context.metadata.identity.file_id.0,
                    context.metadata.workspace_generation.0,
                    context.metadata.fingerprint.value
                ),
            ),
            schema_version: 1,
        }
    }

    fn inline_prediction_observed_fingerprint(
        &self,
        buffer_id: BufferId,
    ) -> Result<InlinePredictionFingerprintMetadata, AppCompositionError> {
        let context = self.active_documents.save_context_for_buffer(buffer_id)?;
        let snapshot = self.editor.current_snapshot(buffer_id)?.clone();
        Ok(self.inline_prediction_fingerprint(
            &context,
            snapshot.snapshot_id,
            snapshot.buffer_version,
            snapshot.content_hash.as_str(),
        ))
    }

    #[cfg(feature = "ai")]
    fn invoke_inline_prediction_provider(
        &self,
        metadata: InlinePredictionRequestMetadata,
    ) -> Result<InlinePredictionResult, AppCompositionError> {
        // Tier 2: local-first product completion (Ollama / Anthropic) for ghost text.
        // Without a live route (CI/offline), keep deterministic fixture.
        //
        // Authorize the concrete backend before any buffer excerpt leaves the process.
        // DenyByDefaultBroker recognizes `ai.provider.invoke` / `ai.provider.stream`
        // for provider egress — not the structural `ai.inline_prediction.invoke`
        // label carried in InlinePredictionRequestMetadata.
        let live_backend = product_ai_selected_live_backend(self.preferred_ai_provider);
        if let Some(backend) = live_backend {
            let (_provider_id, _model, _class, network_target, _, _, _) =
                product_ai_route_fields(Some(backend));
            let broker = DenyByDefaultBroker::new(
                product_ai_security_policy(Some(backend)),
                CapabilityNamespace("app.ai".to_string()),
            );
            let decision = broker
                .handle(CapabilityRequest::Request {
                    principal_id: metadata.principal_id.clone(),
                    capability_id: CapabilityId("ai.provider.invoke".to_string()),
                    workspace_trust_state: metadata.workspace_trust_state.clone(),
                    target_path: None,
                    decision_id: None,
                    context: legion_protocol::CapabilityRequestContext {
                        network_target,
                        ..Default::default()
                    },
                    correlation_id: metadata.correlation_id,
                })
                .map_err(|error| AppCompositionError::AiRuntime(error.message))?;
            let granted = matches!(
                decision,
                CapabilityResponse::Decision(ref d) if d.granted
            ) || matches!(decision, CapabilityResponse::Granted(_));
            if granted {
                let buffer_excerpt = self
                    .editor
                    .text(metadata.buffer_id)
                    .unwrap_or("")
                    .chars()
                    .take(2_000)
                    .collect::<String>();
                if let Some(live) = try_live_product_inline_prediction(
                    self.preferred_ai_provider,
                    &metadata,
                    &buffer_excerpt,
                ) {
                    return Ok(live);
                }
            }
            // Live route denied or empty: fall through to deterministic offline fixture.
        }

        let request = InlinePredictionRequest {
            provider: DETERMINISTIC_LOCAL_PROVIDER_ID.to_string(),
            model: "zeta2-style-deterministic".to_string(),
            metadata,
        };
        let provider = self
            .ai_registry
            .get(DETERMINISTIC_LOCAL_PROVIDER_ID)
            .ok_or_else(|| {
                AppCompositionError::AiRuntime(
                    "deterministic inline prediction provider is not registered".to_string(),
                )
            })?;
        let response = provider
            .predict_inline(request)
            .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?;
        Ok(response.result)
    }

    /// Offline variant: `ai` feature is absent but `offline` includes `legion-ai`
    /// (pure Rust, no network deps).  We instantiate the deterministic-local
    /// provider directly without going through a hosted-capable registry, so
    /// reqwest is never pulled in.
    #[cfg(all(not(feature = "ai"), feature = "offline"))]
    fn invoke_inline_prediction_provider(
        &self,
        metadata: InlinePredictionRequestMetadata,
    ) -> Result<InlinePredictionResult, AppCompositionError> {
        use legion_ai::{
            DeterministicInlinePredictionProvider, InlinePredictionRequest, ModelProvider,
        };
        const DETERMINISTIC_ID: &str = "deterministic-local";
        let provider = DeterministicInlinePredictionProvider::new(DETERMINISTIC_ID);
        let request = InlinePredictionRequest {
            provider: DETERMINISTIC_ID.to_string(),
            model: "zeta2-style-deterministic".to_string(),
            metadata,
        };
        let response = provider
            .predict_inline(request)
            .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?;
        Ok(response.result)
    }

    /// Pure-offline variant: neither `ai` nor `offline` feature is active;
    /// inline prediction is genuinely unavailable.
    #[cfg(not(any(feature = "ai", feature = "offline")))]
    fn invoke_inline_prediction_provider(
        &self,
        _metadata: InlinePredictionRequestMetadata,
    ) -> Result<InlinePredictionResult, AppCompositionError> {
        Err(AppCompositionError::AiRuntime(
            "AI feature is disabled; inline prediction provider is unavailable".to_string(),
        ))
    }

    fn resolve_inline_prediction_index(
        &self,
        buffer_id: BufferId,
        prediction_id: Option<&str>,
    ) -> Option<usize> {
        self.assist_inline_prediction_state
            .results
            .iter()
            .enumerate()
            .find_map(|(index, result)| {
                let request = self
                    .assist_inline_prediction_state
                    .requests
                    .get(&result.request_id)?;
                if request.buffer_id != buffer_id {
                    return None;
                }
                let id_matches = prediction_id.map_or_else(
                    || {
                        self.assist_inline_prediction_state
                            .active_request_id
                            .as_ref()
                            .is_some_and(|active| active == &result.request_id)
                    },
                    |prediction_id| {
                        prediction_id == result.result_id.0 || prediction_id == result.request_id.0
                    },
                );
                id_matches.then_some(index)
            })
    }

    fn validate_inline_prediction_lifecycle(
        &mut self,
        result_index: usize,
        action: InlinePredictionLifecycleAction,
    ) -> Result<(), AppCompositionError> {
        let result = &self.assist_inline_prediction_state.results[result_index];
        if result.state != InlinePredictionResultState::Available {
            return Err(AppCompositionError::AiRuntime(format!(
                "Assist inline prediction must be available for {action:?}; current state is {:?}",
                result.state
            )));
        }
        if action == InlinePredictionLifecycleAction::Cancel
            && (!self.assist_inline_prediction_state.request_in_flight
                || self
                    .assist_inline_prediction_state
                    .active_request_id
                    .as_ref()
                    != Some(&result.request_id))
        {
            return Err(AppCompositionError::AiRuntime(
                "Assist inline prediction cancel requires an in-flight active request".to_string(),
            ));
        }
        let request_id = result.request_id.clone();
        let result_id = result.result_id.clone();
        let request = self
            .assist_inline_prediction_state
            .requests
            .get(&request_id)
            .ok_or_else(|| {
                AppCompositionError::AiRuntime(
                    "Assist inline prediction request metadata is missing".to_string(),
                )
            })?;
        let cancellation_token = request.cancellation_token;
        let event_context = self.next_event_context();
        let command = InlinePredictionLifecycleCommand {
            request_id,
            result_id: match action {
                InlinePredictionLifecycleAction::Cancel => None,
                InlinePredictionLifecycleAction::Dismiss
                | InlinePredictionLifecycleAction::Accept => Some(result_id),
            },
            action,
            cancellation_token: (action == InlinePredictionLifecycleAction::Cancel)
                .then_some(cancellation_token),
            dismissal_id: (action == InlinePredictionLifecycleAction::Dismiss)
                .then_some(InlinePredictionDismissalId(uuid::Uuid::now_v7())),
            acceptance_id: (action == InlinePredictionLifecycleAction::Accept)
                .then_some(InlinePredictionAcceptanceId(uuid::Uuid::now_v7())),
            reason_labels: vec![format!("assist-inline.{action:?}")],
            requested_at: TimestampMillis::now(),
            correlation_id: event_context.correlation_id,
            causality_id: event_context.causality_id,
            event_sequence: self.event_sequence_generator.next(),
            redaction_hints: vec![RedactionHint::MetadataOnly],
            schema_version: 1,
        };
        validate_inline_prediction_lifecycle_command(&command)
            .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))
    }

    fn mark_inline_prediction_lifecycle(
        &mut self,
        result_index: usize,
        state: InlinePredictionResultState,
    ) -> Result<(), AppCompositionError> {
        let result = &mut self.assist_inline_prediction_state.results[result_index];
        result.state = state;
        result.retention = InlinePredictionRetention::MetadataOnlyAudit;
        result.ghost_text = None;
        result.provider.invocation_state = match state {
            InlinePredictionResultState::Cancelled => AssistedAiProviderInvocationState::Cancelled,
            InlinePredictionResultState::Failed => AssistedAiProviderInvocationState::Failed,
            InlinePredictionResultState::Refused => AssistedAiProviderInvocationState::Refused,
            _ => AssistedAiProviderInvocationState::Completed,
        };
        result.generated_at = TimestampMillis::now();
        result
            .validate()
            .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?;
        self.assist_inline_prediction_state.active_request_id = None;
        self.assist_inline_prediction_state.request_in_flight = false;
        Ok(())
    }

    fn mark_inline_prediction_stale(
        &mut self,
        result_index: usize,
        freshness: InlinePredictionFreshness,
    ) -> Result<(), AppCompositionError> {
        let result = &mut self.assist_inline_prediction_state.results[result_index];
        result.state = InlinePredictionResultState::Stale;
        result.freshness = freshness;
        result.retention = InlinePredictionRetention::MetadataOnlyAudit;
        result.ghost_text = None;
        result.generated_at = TimestampMillis::now();
        result
            .validate()
            .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?;
        self.assist_inline_prediction_state.active_request_id = None;
        self.assist_inline_prediction_state.request_in_flight = false;
        Ok(())
    }

    fn inline_prediction_edit_range(
        range: ProtocolTextRange,
    ) -> Result<ProtocolEditTextRange, AppCompositionError> {
        let start = range.start.byte_offset.ok_or_else(|| {
            AppCompositionError::AiRuntime(
                "Assist inline prediction accept requires byte-coordinate start".to_string(),
            )
        })?;
        let end = range.end.byte_offset.ok_or_else(|| {
            AppCompositionError::AiRuntime(
                "Assist inline prediction accept requires byte-coordinate end".to_string(),
            )
        })?;
        Ok(ProtocolEditTextRange::byte(start, end))
    }

    fn assist_inline_prediction_projection(
        &self,
        generated_at: TimestampMillis,
    ) -> AssistInlinePredictionProjection {
        if !self.product_mode.allows_assist() {
            return AssistInlinePredictionProjection::empty();
        }
        let Some(buffer_id) = self.active_documents.active_buffer_id else {
            return AssistInlinePredictionProjection::empty();
        };
        let Some(workspace_id) = self.active_documents.workspace_id() else {
            return AssistInlinePredictionProjection::empty();
        };
        let observed = self.inline_prediction_observed_fingerprint(buffer_id).ok();
        let mut results = Vec::new();
        for result in &self.assist_inline_prediction_state.results {
            let Some(request) = self
                .assist_inline_prediction_state
                .requests
                .get(&result.request_id)
            else {
                continue;
            };
            if request.buffer_id != buffer_id {
                continue;
            }
            let mut projected = result.clone();
            if projected.state == InlinePredictionResultState::Available
                && let Some(observed) = &observed
            {
                let freshness = InlinePredictionFreshness::from_fingerprints(
                    &projected.fingerprint,
                    observed,
                    1,
                );
                if freshness.state == InlinePredictionFreshnessState::Stale {
                    projected.state = InlinePredictionResultState::Stale;
                    projected.freshness = freshness;
                    projected.retention = InlinePredictionRetention::MetadataOnlyAudit;
                    projected.ghost_text = None;
                }
            }
            results.push(projected);
        }
        let active_request_id = self
            .assist_inline_prediction_state
            .active_request_id
            .clone()
            .filter(|request_id| {
                results.iter().any(|result| {
                    &result.request_id == request_id
                        && result.state == InlinePredictionResultState::Available
                        && result.freshness.state != InlinePredictionFreshnessState::Stale
                })
            });
        let protocol = inline_prediction_projection_from_results(
            format!("assist-inline:{}:{}", workspace_id.0, buffer_id.0),
            workspace_id,
            buffer_id,
            active_request_id,
            results,
            generated_at,
            1,
        );
        match protocol {
            Ok(protocol) => self.assist_inline_prediction_projection_from_protocol(
                protocol,
                self.assist_inline_prediction_state.request_in_flight,
            ),
            Err(_) => AssistInlinePredictionProjection::empty(),
        }
    }

    fn assist_inline_prediction_projection_from_protocol(
        &self,
        projection: InlinePredictionProjection,
        request_in_flight: bool,
    ) -> AssistInlinePredictionProjection {
        let rows: Vec<_> = projection
            .results
            .iter()
            .map(|result| self.inline_prediction_row(result))
            .collect();
        let after_edit_prediction_attempts = projection
            .results
            .iter()
            .filter(|result| {
                self.assist_inline_prediction_state
                    .requests
                    .get(&result.request_id)
                    .is_some_and(|request| {
                        request.trigger == InlinePredictionTriggerKind::AfterEdit
                    })
            })
            .count();
        let after_edit_prediction_accepts = projection
            .results
            .iter()
            .filter(|result| {
                self.assist_inline_prediction_state
                    .requests
                    .get(&result.request_id)
                    .is_some_and(|request| {
                        request.trigger == InlinePredictionTriggerKind::AfterEdit
                            && result.state == InlinePredictionResultState::Accepted
                    })
            })
            .count();
        let active_prediction = projection
            .active_request_id
            .as_ref()
            .and_then(|request_id| {
                rows.iter()
                    .find(|row| {
                        projection.results.iter().any(|result| {
                            &result.request_id == request_id
                                && result.result_id.0 == row.prediction_id
                                && result.state == InlinePredictionResultState::Available
                        })
                    })
                    .cloned()
            });
        AssistInlinePredictionProjection {
            active_prediction,
            stale_prediction_count: projection.stale_count as usize,
            after_edit_prediction_attempts,
            after_edit_prediction_accepts,
            rows,
            request_in_flight,
            generated_at: projection.generated_at,
            schema_version: projection.schema_version,
        }
    }

    fn inline_prediction_row(
        &self,
        result: &InlinePredictionResult,
    ) -> AssistInlinePredictionRowProjection {
        let request = self
            .assist_inline_prediction_state
            .requests
            .get(&result.request_id);
        let stale = result.state == InlinePredictionResultState::Stale
            || result.freshness.state == InlinePredictionFreshnessState::Stale;
        AssistInlinePredictionRowProjection {
            prediction_id: result.result_id.0.clone(),
            workspace_id: request.map(|request| request.workspace_id),
            buffer_id: request.map(|request| request.buffer_id),
            file_id: request.and_then(|request| request.file_id),
            provider_label: format!(
                "{} ({})",
                result.provider.provider_id, result.provider.model_label
            ),
            status: inline_prediction_status(result),
            status_label: format!("{:?}", inline_prediction_status(result)),
            latency_ms: Some(result.provider.latency.total_ms as u64),
            requested_at: request.map_or(result.generated_at, |request| request.requested_at),
            completed_at: Some(result.generated_at),
            snapshot_id: Some(result.fingerprint.snapshot_id),
            buffer_version: Some(result.fingerprint.buffer_version),
            file_fingerprint: result.fingerprint.content_fingerprint.clone(),
            stale,
            stale_reason_label: stale.then(|| stale_reason_label(&result.freshness.stale_reasons)),
            ghost_text_label: result
                .ghost_text
                .as_ref()
                .map(|ghost| bounded_label(ghost.text.as_str(), 120))
                .unwrap_or_default(),
            replacement_preview_label: None,
            apply_range: result.insert_range,
            apply_range_label: format!(
                "{}:{}-{}:{}",
                result.insert_range.start.line,
                result.insert_range.start.character,
                result.insert_range.end.line,
                result.insert_range.end.character
            ),
            diagnostics: inline_prediction_diagnostics(result),
        }
    }

    fn run_language_proposal(
        &mut self,
        buffer_id: BufferId,
        kind: LanguageProposalKind,
        position: TextCoordinate,
        label: String,
    ) -> Result<LanguageToolingProjection, AppCompositionError> {
        let event_context = self.next_event_context();
        let input = self.language_request_input(buffer_id, event_context)?;
        let proposal_id = self.proposal_coordinator.next_id();
        let capability = CapabilityId("fs.write".to_string());
        let preconditions = ProposalVersionPreconditions {
            file_version: Some(input.metadata.file_content_version),
            buffer_version: Some(input.buffer_version),
            snapshot_id: Some(input.snapshot_id),
            generation: Some(input.metadata.workspace_generation),
            file_content_version: Some(input.metadata.file_content_version),
            workspace_generation: Some(input.metadata.workspace_generation),
            expected_fingerprint: Some(input.metadata.fingerprint.clone()),
            expected_file_length: input.metadata.file_length,
            expected_modified_at: input.metadata.modified_at,
        };
        let source = match kind {
            LanguageProposalKind::Formatting => WorkspaceEditSourceKind::LspFormatting,
            LanguageProposalKind::Rename => WorkspaceEditSourceKind::LspRename,
            LanguageProposalKind::OrganizeImports | LanguageProposalKind::CodeAction => {
                WorkspaceEditSourceKind::LspCodeAction
            }
        };
        let title = match kind {
            LanguageProposalKind::Formatting => "Format active buffer".to_string(),
            LanguageProposalKind::Rename => {
                format!("Rename symbol to {}", bounded_label(&label, 64))
            }
            LanguageProposalKind::OrganizeImports => "Organize imports".to_string(),
            LanguageProposalKind::CodeAction => {
                format!("Apply code action {}", bounded_label(&label, 64))
            }
        };
        let (workspace_edit, diagnostics) = match kind {
            LanguageProposalKind::Rename => {
                // When the LSP session is live, route through `textDocument/rename`
                // for multi-file rename coverage (PKT-LSP-C I-2).  The result
                // arrives asynchronously via `ingest_lsp_rename_result` and is
                // projected into `language_tooling` on the next drain call.
                if self.lsp_session.is_live()
                    && self.issue_lsp_rename_request_inner(buffer_id, position, label.clone())
                {
                    return Ok(self.language_tooling.projection());
                }
                // --- local (non-LSP) rename path ---
                let replacement = bounded_label(&label, 128);
                if replacement.trim().is_empty() {
                    return Ok(self.language_tooling.record_proposal_failure(
                        &input,
                        kind,
                        "Rename proposal requires a non-empty replacement label".to_string(),
                    ));
                }
                let Some(range) =
                    identifier_byte_range_at(&input.text, position.byte_offset.unwrap_or(0))
                else {
                    return Ok(self.language_tooling.record_proposal_failure(
                        &input,
                        kind,
                        "Rename proposal requires an identifier at the requested position"
                            .to_string(),
                    ));
                };
                let target = ProposalAffectedTarget {
                    target_id: format!("file:{}", input.metadata.identity.file_id.0),
                    kind: ProposalTargetKind::OpenBuffer,
                    workspace_id: Some(input.workspace_id),
                    file_id: Some(input.metadata.identity.file_id),
                    buffer_id: Some(buffer_id),
                    path: Some(input.metadata.identity.canonical_path.clone()),
                    terminal_session_id: None,
                    plugin_id: None,
                    remote_authority: None,
                    collaboration_session_id: None,
                    byte_ranges: vec![range],
                    redaction_hints: vec![RedactionHint::MetadataOnly],
                };
                let workspace_edit = WorkspaceEditProposalPayload {
                    workspace_id: input.workspace_id,
                    edit_id: uuid::Uuid::now_v7(),
                    title: title.clone(),
                    source,
                    target_coverage: ProposalTargetCoverage {
                        coverage_kind: ProposalTargetCoverageKind::Complete,
                        targets: vec![target],
                        omitted_target_count: 0,
                        redaction_hints: vec![RedactionHint::MetadataOnly],
                    },
                    file_edits: vec![WorkspaceTextEdit {
                        file: input.metadata.identity.clone(),
                        buffer_id: Some(buffer_id),
                        edits: EditBatch {
                            edits: vec![ProtocolWorkspaceTextEdit {
                                range: ProtocolEditTextRange::byte(range.start, range.end),
                                replacement,
                            }],
                        },
                        preconditions: preconditions.clone(),
                    }],
                    file_operations: Vec::new(),
                    required_capability: capability.clone(),
                    diagnostics: Vec::new(),
                    schema_version: 1,
                };
                (workspace_edit, Vec::new())
            }
            LanguageProposalKind::Formatting
            | LanguageProposalKind::OrganizeImports
            | LanguageProposalKind::CodeAction => {
                let mut diagnostics = Vec::new();
                diagnostics.push(ProtocolDiagnostic {
                    code: "language_tooling.runtime_edit_unavailable".to_string(),
                    message: format!(
                        "{title} is represented as a safe no-op preview until live LSP edits are wired"
                    ),
                    severity: ProtocolDiagnosticSeverity::Warning,
                    path: Some(input.metadata.identity.canonical_path.clone()),
                    range: None,
                });
                let target = ProposalAffectedTarget {
                    target_id: format!("file:{}", input.metadata.identity.file_id.0),
                    kind: ProposalTargetKind::OpenBuffer,
                    workspace_id: Some(input.workspace_id),
                    file_id: Some(input.metadata.identity.file_id),
                    buffer_id: Some(buffer_id),
                    path: Some(input.metadata.identity.canonical_path.clone()),
                    terminal_session_id: None,
                    plugin_id: None,
                    remote_authority: None,
                    collaboration_session_id: None,
                    byte_ranges: vec![ByteRange::new(0, input.text.len() as u64)],
                    redaction_hints: vec![RedactionHint::MetadataOnly],
                };
                let workspace_edit = WorkspaceEditProposalPayload {
                    workspace_id: input.workspace_id,
                    edit_id: uuid::Uuid::now_v7(),
                    title: title.clone(),
                    source,
                    target_coverage: ProposalTargetCoverage {
                        coverage_kind: ProposalTargetCoverageKind::Complete,
                        targets: vec![target],
                        omitted_target_count: 0,
                        redaction_hints: vec![RedactionHint::MetadataOnly],
                    },
                    file_edits: vec![WorkspaceTextEdit {
                        file: input.metadata.identity.clone(),
                        buffer_id: Some(buffer_id),
                        edits: EditBatch {
                            edits: vec![ProtocolWorkspaceTextEdit {
                                range: ProtocolEditTextRange::byte(0, input.text.len() as u64),
                                replacement: input.text.clone(),
                            }],
                        },
                        preconditions: preconditions.clone(),
                    }],
                    file_operations: Vec::new(),
                    required_capability: capability.clone(),
                    diagnostics: diagnostics.clone(),
                    schema_version: 1,
                };
                (workspace_edit, diagnostics)
            }
        };
        let request = LspRequestCorrelation {
            request_id: legion_protocol::LspRequestId(uuid::Uuid::now_v7()),
            server_id: legion_protocol::LanguageServerId(1),
            workspace_id: input.workspace_id,
            file_id: Some(input.metadata.identity.file_id),
            snapshot_id: Some(input.snapshot_id),
            buffer_version: Some(input.buffer_version),
            correlation_id: input.event_context.correlation_id,
            causality_id: input.event_context.causality_id,
            cancellation_token: Some(CancellationTokenId(uuid::Uuid::now_v7())),
            privacy_scope: SemanticPrivacyScope::Workspace,
            issued_at: TimestampMillis::now(),
            schema_version: 1,
        };
        let proposal = legion_protocol::convert_lsp_edit_to_workspace_proposal(
            LspEditProposalConversionInput {
                proposal_id,
                principal: input.principal.clone(),
                capability,
                request,
                workspace_edit,
                preconditions,
                lifecycle_state: ProposalLifecycleState::Created,
                privacy_label: legion_protocol::ProposalPrivacyLabel::WorkspaceMetadata,
                preview: PreviewSummary {
                    summary: title.clone(),
                    details: vec![
                        "language_tooling.proposal_preview".to_string(),
                        format!("buffer_version={}", input.buffer_version.0),
                        format!("snapshot_id={}", input.snapshot_id.0),
                    ],
                },
                expires_at: None,
                created_at: TimestampMillis::now(),
                diagnostics,
                schema_version: 1,
            },
        )
        .map_err(|error| AppCompositionError::LanguageTooling(format!("{error:?}")))?;
        self.proposal_coordinator
            .register_lifecycle_context(proposal.proposal_id, input.event_context);
        let created = self.proposal_coordinator.created_response(&proposal);
        if !matches!(created, ProposalResponse::Created(_)) {
            return Ok(self.language_tooling.record_proposal_failure(
                &input,
                kind,
                format!("{} proposal creation failed: {created:?}", title),
            ));
        }
        let validated = self
            .proposal_coordinator
            .handle(ProposalRequest::Validate(proposal.clone()));
        if !matches!(validated, Ok(ProposalResponse::Validated(_))) {
            return Ok(self.language_tooling.record_proposal_failure(
                &input,
                kind,
                format!("{} proposal validation failed: {validated:?}", title),
            ));
        }
        let previewed = self
            .proposal_coordinator
            .handle(ProposalRequest::Preview(proposal.clone()));
        if !matches!(previewed, Ok(ProposalResponse::Previewed { .. })) {
            return Ok(self.language_tooling.record_proposal_failure(
                &input,
                kind,
                format!("{} proposal preview failed: {previewed:?}", title),
            ));
        }
        Ok(self.language_tooling.record_proposal(
            &input,
            kind,
            proposal.proposal_id,
            if matches!(kind, LanguageProposalKind::CodeAction) {
                Some(label.as_str())
            } else {
                None
            },
            format!("{} proposal preview created", title),
        ))
    }

    fn run_active_file_structural_search(
        &self,
        query_id: &str,
        query: &StructuralSearchQuery,
        limit: usize,
    ) -> Result<StructuralBuildResult, AppCompositionError> {
        let buffer_id = self.active_documents.require_active_buffer()?;
        let metadata = self
            .active_documents
            .metadata_for_buffer(buffer_id)
            .cloned()
            .ok_or(AppCompositionError::ActiveFileMissing)?;
        let text = self.editor.text(buffer_id)?.to_string();
        let document = self.structural_document_for_open_buffer(buffer_id, &metadata, text)?;
        let mut result = StructuralBuildResult::default();
        collect_structural_document_result(
            query_id,
            SearchScopeProjection::ActiveFile,
            query,
            document,
            limit,
            &mut result,
        );
        Ok(result)
    }

    fn run_workspace_structural_search(
        &self,
        query_id: &str,
        query: &StructuralSearchQuery,
        limit: usize,
    ) -> Result<StructuralBuildResult, AppCompositionError> {
        let workspace = self.active_documents.require_workspace_context()?;
        let tree = self.workspace.tree_snapshot()?;
        let mut result = StructuralBuildResult::default();

        for node in tree {
            if !workspace_node_is_regular_file(&node) {
                continue;
            }
            let Some(size_bytes) = node
                .metadata
                .as_ref()
                .and_then(|metadata| metadata.size_bytes)
            else {
                result.omitted_file_count += 1;
                result.diagnostics.push(format!(
                    "Skipped {} because file size metadata is unavailable",
                    node.identity.canonical_path.0
                ));
                continue;
            };
            if size_bytes > WORKSPACE_SEARCH_MAX_FILE_BYTES {
                result.omitted_file_count += 1;
                result.diagnostics.push(format!(
                    "Skipped {} because {} bytes exceeds the workspace structural-search bound",
                    node.identity.canonical_path.0, size_bytes
                ));
                continue;
            }

            let document = if let Some(buffer_id) = self
                .editor
                .buffer_for_file(workspace.workspace_id, node.identity.file_id)
                .or_else(|| {
                    self.editor
                        .buffer_for_path(workspace.workspace_id, &node.identity.canonical_path.0)
                })
                .or_else(|| {
                    self.open_buffer_for_equivalent_path(
                        workspace.workspace_id,
                        &node.identity.canonical_path,
                    )
                }) {
                let metadata = self
                    .active_documents
                    .metadata_for_buffer(buffer_id)
                    .cloned()
                    .ok_or(AppCompositionError::ActiveFileMissing)?;
                let text = self.editor.text(buffer_id)?.to_string();
                self.structural_document_for_open_buffer(buffer_id, &metadata, text)?
            } else {
                let text = match self
                    .workspace
                    .read_file_text(workspace.workspace_id, &node.identity.canonical_path.0)
                {
                    Ok(text) => text,
                    Err(error) => {
                        result.omitted_file_count += 1;
                        result.diagnostics.push(format!(
                            "Skipped {}: {error}",
                            node.identity.canonical_path.0
                        ));
                        continue;
                    }
                };
                structural_document_for_tree_node(&node, workspace.workspace_generation, text)
            };

            collect_structural_document_result(
                query_id,
                SearchScopeProjection::Workspace,
                query,
                document,
                limit,
                &mut result,
            );
        }

        Ok(result)
    }

    fn structural_document_for_open_buffer(
        &self,
        buffer_id: BufferId,
        metadata: &ActiveFileMetadata,
        text: String,
    ) -> Result<SourceDocument, AppCompositionError> {
        let snapshot_id = self.editor.current_snapshot(buffer_id)?.snapshot_id;
        let mut document = SourceDocument::with_versions(
            metadata.identity.workspace_id,
            metadata.identity.file_id,
            metadata.identity.canonical_path.clone(),
            language_id_for_path(&metadata.identity.canonical_path),
            metadata.file_content_version,
            metadata.workspace_generation,
            Some(snapshot_id),
            SemanticPrivacyScope::Workspace,
            text,
        );
        document.identity.content_hash = metadata.fingerprint.clone();
        document.identity.disk_fingerprint = Some(metadata.fingerprint.clone());
        document.identity.byte_len = metadata.file_length;
        document.identity.modified_at = metadata.modified_at;
        Ok(document)
    }

    fn create_structural_rewrite_proposal(
        &mut self,
        pattern_label: &str,
        result: &mut StructuralBuildResult,
    ) -> Result<Option<ProposalId>, AppCompositionError> {
        let workspace_id = self.active_documents.require_workspace_id()?;
        let title = format!("Structural replace `{}`", bounded_label(pattern_label, 64));
        let inputs = result
            .reports
            .iter()
            .map(|report| StructuralRewriteFileInput {
                document: &report.document,
                matches: &report.matches,
            })
            .collect::<Vec<_>>();
        let mut payload =
            build_structural_rewrite_preview_payload(workspace_id, title.clone(), &inputs);
        self.enrich_structural_payload_for_open_buffers(&mut payload)?;
        if payload.file_edits.is_empty() {
            result.diagnostics.push(
                "Structural rewrite preview did not produce editable file changes".to_string(),
            );
            return Ok(None);
        }

        let event_context = self.next_event_context();
        let proposal_id = self.proposal_coordinator.next_id();
        let principal = self
            .active_documents
            .active_principal_id
            .clone()
            .ok_or(AppCompositionError::WorkspaceNotOpen)?;
        let capability = payload.required_capability.clone();
        let preconditions = payload
            .file_edits
            .first()
            .map(|edit| edit.preconditions.clone())
            .unwrap_or(ProposalVersionPreconditions {
                file_version: None,
                buffer_version: None,
                snapshot_id: None,
                generation: Some(
                    self.active_documents
                        .require_workspace_context()?
                        .workspace_generation,
                ),
                file_content_version: None,
                workspace_generation: Some(
                    self.active_documents
                        .require_workspace_context()?
                        .workspace_generation,
                ),
                expected_fingerprint: None,
                expected_file_length: None,
                expected_modified_at: None,
            });
        let proposal = WorkspaceProposal {
            proposal_id,
            principal,
            capability,
            correlation_id: event_context.correlation_id,
            payload: ProposalPayload::WorkspaceEdit(payload),
            preconditions,
            preview: PreviewSummary {
                summary: title.clone(),
                details: vec![
                    "structural_search.rewrite_preview".to_string(),
                    format!("matches={}", result.matches.len()),
                ],
            },
            expires_at: None,
            created_at: TimestampMillis::now(),
        };

        self.proposal_coordinator
            .register_lifecycle_context(proposal.proposal_id, event_context);
        let created = self.proposal_coordinator.created_response(&proposal);
        if !matches!(created, ProposalResponse::Created(_)) {
            result.diagnostics.push(format!(
                "Structural rewrite proposal creation failed: {created:?}"
            ));
            return Ok(None);
        }
        let validated = self
            .proposal_coordinator
            .handle(ProposalRequest::Validate(proposal.clone()));
        if !matches!(validated, Ok(ProposalResponse::Validated(_))) {
            result.diagnostics.push(format!(
                "Structural rewrite proposal validation failed: {validated:?}"
            ));
            return Ok(None);
        }
        let previewed = self
            .proposal_coordinator
            .handle(ProposalRequest::Preview(proposal));
        if !matches!(previewed, Ok(ProposalResponse::Previewed { .. })) {
            result.diagnostics.push(format!(
                "Structural rewrite proposal preview failed: {previewed:?}"
            ));
            return Ok(None);
        }

        Ok(Some(proposal_id))
    }

    fn enrich_structural_payload_for_open_buffers(
        &self,
        payload: &mut WorkspaceEditProposalPayload,
    ) -> Result<(), AppCompositionError> {
        for edit in &mut payload.file_edits {
            let Some(buffer_id) = self
                .editor
                .buffer_for_file(edit.file.workspace_id, edit.file.file_id)
                .or_else(|| {
                    self.editor
                        .buffer_for_path(edit.file.workspace_id, &edit.file.canonical_path.0)
                })
                .or_else(|| {
                    self.open_buffer_for_equivalent_path(
                        edit.file.workspace_id,
                        &edit.file.canonical_path,
                    )
                })
            else {
                continue;
            };
            let actual = self.active_file_version_context(buffer_id)?;
            edit.buffer_id = Some(buffer_id);
            edit.preconditions.buffer_version = Some(actual.buffer_version);
            edit.preconditions.snapshot_id = Some(actual.snapshot_id);
            edit.preconditions.file_version = Some(actual.file_version);
            edit.preconditions.file_content_version = Some(actual.file_content_version);
            edit.preconditions.generation = Some(actual.generation);
            edit.preconditions.workspace_generation = Some(actual.workspace_generation);
            edit.preconditions.expected_fingerprint = actual.fingerprint.clone();
            edit.preconditions.expected_file_length = actual.file_length;
            edit.preconditions.expected_modified_at = actual.modified_at;

            if let Some(target) = payload
                .target_coverage
                .targets
                .iter_mut()
                .find(|target| target.file_id == Some(edit.file.file_id))
            {
                target.kind = ProposalTargetKind::OpenBuffer;
                target.buffer_id = Some(buffer_id);
            }
        }
        Ok(())
    }

    fn open_buffer_for_equivalent_path(
        &self,
        workspace_id: WorkspaceId,
        path: &CanonicalPath,
    ) -> Option<BufferId> {
        self.active_documents
            .open_tabs
            .iter()
            .copied()
            .find(|buffer_id| {
                self.active_documents
                    .metadata_for_buffer(*buffer_id)
                    .is_some_and(|metadata| {
                        metadata.identity.workspace_id == workspace_id
                            && Self::paths_equivalent(&metadata.identity.canonical_path.0, &path.0)
                    })
            })
    }

    /// Capture a metadata-only workspace session record.
    pub fn capture_workspace_session_record(
        &self,
    ) -> Result<WorkspaceSessionRecord, AppCompositionError> {
        let mut record = capture_workspace_session_record(&self.active_documents, &self.editor)?;
        record.workbench_settings = workbench_settings_record_from_projection(&self.settings);
        record.memory_snapshot_json = Some(
            serde_json::to_string(
                &self
                    .memory_service
                    .compacted_snapshot(MemoryCompactionPolicy::default()),
            )
            .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?,
        );
        Ok(record)
    }

    /// Restore open tabs from a metadata-only session record.
    pub fn restore_workspace_session_record(
        &mut self,
        record: &WorkspaceSessionRecord,
    ) -> Result<AppSessionRestoreOutcome, AppCompositionError> {
        self.settings = settings_projection_from_workbench_record(&record.workbench_settings);
        // Apply user-level terminal shell preference from loaded settings.
        self.terminal_workflow
            .set_user_shell_selection(TerminalShellSelection::from_label(
                &record.workbench_settings.terminal_shell_selection,
            ));
        if let Some(memory_snapshot_json) = &record.memory_snapshot_json {
            let snapshot: MemoryServiceSnapshot = serde_json::from_str(memory_snapshot_json)
                .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?;
            self.memory_service = MemoryService::from_snapshot(snapshot)
                .map_err(|error| AppCompositionError::AiRuntime(error.to_string()))?;
        }
        let mut restored_file_ids = Vec::new();
        let mut skipped_tabs = Vec::new();
        for tab in &record.open_tabs {
            let Some(path) = tab.path.as_ref() else {
                skipped_tabs.push(AppSessionRestoreSkippedTab {
                    tab_id: tab.tab_id.clone(),
                    reason: "missing path".to_string(),
                });
                continue;
            };
            if !Path::new(&path.0).exists() {
                skipped_tabs.push(AppSessionRestoreSkippedTab {
                    tab_id: tab.tab_id.clone(),
                    reason: "path missing".to_string(),
                });
                continue;
            }
            match self.open_file(&path.0) {
                Ok(file_id) => restored_file_ids.push(file_id),
                Err(error) => skipped_tabs.push(AppSessionRestoreSkippedTab {
                    tab_id: tab.tab_id.clone(),
                    reason: error.to_string(),
                }),
            }
        }

        if let Some(active_tab) = &record.active_tab
            && let Some(tab) = record
                .open_tabs
                .iter()
                .find(|candidate| &candidate.tab_id == active_tab)
            && let Some(path) = &tab.path
            && let Some(workspace_id) = self.active_documents.workspace_id()
            && let Some(buffer_id) = self.editor.buffer_for_path(workspace_id, &path.0)
        {
            let _ = self.switch_tab(buffer_id);
        }

        Ok(AppSessionRestoreOutcome {
            restored_file_ids,
            skipped_tabs,
        })
    }

    /// Build active-buffer projection from editor-engine state.
    pub fn active_buffer_projection(
        &self,
        layout: &ShellLayoutProjection,
    ) -> Result<ActiveBufferProjection, AppCompositionError> {
        ProjectionBuilder::active_buffer_projection(&self.active_documents, &self.editor, layout)
    }

    fn selected_proposal_trust_projections(
        &self,
        proposal_ledger_projection: &legion_protocol::ProposalLedgerProjection,
        generated_at: TimestampMillis,
    ) -> Option<SelectedProposalTrustProjections> {
        let selected_proposal_id = proposal_ledger_projection.selected_proposal_id?;
        let proposal = self
            .proposal_coordinator
            .proposal_for_id(selected_proposal_id)?;
        let row = proposal_ledger_projection
            .rows
            .iter()
            .find(|row| row.proposal_id == selected_proposal_id)?;
        let lifecycle_state = row.lifecycle.state;
        let context_manifest_projection = legion_protocol::ContextManifestProjection {
            manifest: legion_protocol::context_manifest_from_proposal(
                &proposal,
                format!("proposal:{}:context-details", selected_proposal_id.0),
                self.active_documents.active_workspace_trust.clone(),
                row.privacy_label,
                row.risk_label,
                generated_at,
                1,
            ),
            selected_item_id: None,
            generated_at,
            redaction_hints: vec![RedactionHint::MetadataOnly],
            schema_version: 1,
        };
        let privacy_inspector_projection =
            legion_protocol::privacy_inspector_from_context_manifest_projection(
                &context_manifest_projection,
                format!("proposal:{}:privacy-details", selected_proposal_id.0),
                generated_at,
                1,
            );
        let permission_budget_projection = Self::selected_proposal_permission_budget_projection(
            &proposal,
            &context_manifest_projection,
            row.risk_label,
            generated_at,
        );
        let causality_id = self
            .proposal_coordinator
            .proposal_contexts
            .borrow()
            .get(&selected_proposal_id)
            .map(|context| context.causality_id);
        let audit_status =
            if row.rollback == legion_protocol::ProposalRollbackAvailability::NotRequired {
                legion_protocol::CheckpointRollbackAuditStatus::NotRequired
            } else {
                legion_protocol::CheckpointRollbackAuditStatus::Available
            };
        let checkpoint_rollback_projection =
            legion_protocol::checkpoint_rollback_projection_from_proposal(
                format!("proposal:{}:checkpoint-details", selected_proposal_id.0),
                &proposal,
                lifecycle_state,
                Some(proposal_ledger_projection),
                audit_status,
                causality_id,
                generated_at,
                1,
            );
        let approval_checklist_projection =
            legion_protocol::approval_checklist_from_trust_projections(
                format!("proposal:{}:approval-details", selected_proposal_id.0),
                &proposal,
                lifecycle_state,
                Some(proposal_ledger_projection),
                Some(&context_manifest_projection),
                Some(&privacy_inspector_projection),
                Some(&permission_budget_projection),
                Some(&checkpoint_rollback_projection),
                true,
                causality_id,
                generated_at,
                1,
            );

        Some(SelectedProposalTrustProjections {
            context_manifest_projection,
            privacy_inspector_projection,
            permission_budget_projection,
            approval_checklist_projection,
            checkpoint_rollback_projection,
        })
    }

    fn selected_proposal_permission_budget_projection(
        proposal: &WorkspaceProposal,
        context_manifest_projection: &legion_protocol::ContextManifestProjection,
        risk_label: legion_protocol::ProposalRiskLabel,
        generated_at: TimestampMillis,
    ) -> legion_protocol::PermissionBudgetProjection {
        let action_class = match &proposal.payload {
            ProposalPayload::TerminalCommand(_) => {
                legion_protocol::PermissionBudgetActionClass::AccessTerminal
            }
            _ => legion_protocol::PermissionBudgetActionClass::ApplyApprovedProposal,
        };
        let budget = legion_protocol::PermissionBudgetContract {
            budget_id: format!("proposal:{}:permission-budget", proposal.proposal_id.0),
            action_class,
            capability: Some(proposal.capability.clone()),
            state: legion_protocol::PermissionBudgetState::Allowed,
            privacy_scope: SemanticPrivacyScope::MetadataOnly,
            usage: legion_protocol::PermissionBudgetUsageSummary {
                unit_label: "actions".to_string(),
                used: 0,
                ceiling: Some(1),
                remaining: Some(1),
                attempted: 0,
                redaction_hints: vec![RedactionHint::MetadataOnly],
                schema_version: 1,
            },
            reset_policy_label: legion_protocol::PermissionBudgetResetPolicyLabel::Session,
            consent_requirement_label:
                legion_protocol::PermissionBudgetConsentRequirementLabel::NotRequired,
            risk_label,
            reasons: vec!["proposal.permission_budget.metadata_only".to_string()],
            redaction_hints: vec![RedactionHint::MetadataOnly],
            schema_version: 1,
        };
        let action = context_manifest_projection
            .manifest
            .permissions
            .first()
            .map(|permission| {
                legion_protocol::permission_budget_action_from_permission_summary(
                    permission,
                    format!("proposal:{}:permission-action", proposal.proposal_id.0),
                    action_class,
                    context_manifest_projection.manifest.workspace_id,
                    Some(proposal.proposal_id),
                    1,
                )
            })
            .unwrap_or_else(|| legion_protocol::PermissionBudgetActionSummary {
                action_id: format!("proposal:{}:permission-action", proposal.proposal_id.0),
                action_class,
                capability: Some(proposal.capability.clone()),
                workspace_id: context_manifest_projection.manifest.workspace_id,
                proposal_id: Some(proposal.proposal_id),
                target_id: None,
                privacy_scope: SemanticPrivacyScope::MetadataOnly,
                egress: legion_protocol::ContextManifestEgressStatus::LocalOnly,
                estimated_units: 1,
                ranges: Vec::new(),
                counts: Vec::new(),
                hashes: Vec::new(),
                labels: vec!["proposal.permission.action".to_string()],
                risk_label,
                redaction_hints: vec![RedactionHint::MetadataOnly],
                schema_version: 1,
            });
        let evaluation = legion_protocol::evaluate_permission_budget(
            &budget,
            action,
            format!("proposal:{}:permission-evaluation", proposal.proposal_id.0),
            1,
        );
        legion_protocol::permission_budget_projection_from_contracts(
            format!(
                "proposal:{}:permission-budget-projection",
                proposal.proposal_id.0
            ),
            vec![budget],
            vec![evaluation],
            generated_at,
            1,
        )
    }

    /// Build the complete projection snapshot consumed by the UI shell.
    pub fn shell_projection_snapshot(
        &self,
        title: impl Into<String>,
    ) -> Result<ShellProjectionSnapshot, AppCompositionError> {
        let layout_projection = ShellLayoutProjection::plain(title);
        let generated_at = TimestampMillis::now();
        let proposal_ledger_projection = self
            .proposal_coordinator
            .proposal_ledger_projection(generated_at);
        let remote_gui_projection = self.remote.gui_projection(&proposal_ledger_projection);
        let delegated_task_projection =
            self.delegated_task_projection(generated_at, &proposal_ledger_projection);
        let command_registry_projection = self.command_registry_projection(
            &proposal_ledger_projection,
            &delegated_task_projection,
            generated_at,
        );
        let artifact_ledger_projection = self.artifact_ledger_projection(
            &proposal_ledger_projection,
            &delegated_task_projection,
            generated_at,
        );
        let verification_run_projection =
            self.verification_run_projection(&delegated_task_projection, generated_at);
        let legion_workflow_projection = self.legion_workflow_projection(generated_at);
        let legion_workflow_board_columns =
            legion_workflow_board_columns(&legion_workflow_projection);
        let legion_workflow_fleet_card_projections = legion_workflow_fleet_card_projections(
            &proposal_ledger_projection,
            &verification_run_projection,
        );
        let legion_workflow_comm_rows = self.legion_workflow_comm_rows();
        let legion_workflow_budget_rows = self.legion_workflow_budget_rows();
        let system_graph_projection = self.system_graph_projection(
            &proposal_ledger_projection,
            &delegated_task_projection,
            generated_at,
        );
        let selected_proposal_trust =
            self.selected_proposal_trust_projections(&proposal_ledger_projection, generated_at);
        Ok(ShellProjectionSnapshot {
            active_buffer_projection: self.active_buffer_projection(&layout_projection)?,
            product_mode: self.product_mode.to_dock_mode(),
            layout_projection,
            explorer_projection: self.explorer_projection()?,
            status_messages: Vec::new(),
            palette_projection: self.palette.projection(),
            command_registry_projection,
            settings_projection: self.settings_projection(),
            proposal_ledger_projection,
            artifact_ledger_projection,
            verification_run_projection,
            system_graph_projection,
            context_manifest_projection: selected_proposal_trust
                .as_ref()
                .map(|projections| projections.context_manifest_projection.clone())
                .or_else(|| {
                    self.phase4_projection_state
                        .context_manifest_projection
                        .clone()
                })
                .unwrap_or_else(empty_context_manifest_projection),
            privacy_inspector_projection: selected_proposal_trust
                .as_ref()
                .map(|projections| projections.privacy_inspector_projection.clone())
                .or_else(|| {
                    self.phase4_projection_state
                        .privacy_inspector_projection
                        .clone()
                })
                .unwrap_or_else(empty_privacy_inspector_projection),
            permission_budget_projection: selected_proposal_trust
                .as_ref()
                .map(|projections| projections.permission_budget_projection.clone())
                .or_else(|| {
                    self.phase4_projection_state
                        .permission_budget_projection
                        .clone()
                })
                .unwrap_or_else(empty_permission_budget_projection),
            approval_checklist_projection: selected_proposal_trust
                .as_ref()
                .map(|projections| projections.approval_checklist_projection.clone())
                .or_else(|| {
                    self.phase4_projection_state
                        .approval_checklist_projection
                        .clone()
                })
                .unwrap_or_else(empty_approval_checklist_projection),
            checkpoint_rollback_projection: selected_proposal_trust
                .as_ref()
                .map(|projections| projections.checkpoint_rollback_projection.clone())
                .or_else(|| {
                    self.phase4_projection_state
                        .checkpoint_rollback_projection
                        .clone()
                })
                .unwrap_or_else(empty_checkpoint_rollback_projection),
            assisted_ai_projection: self
                .phase4_projection_state
                .assisted_ai_projection
                .clone()
                .unwrap_or_else(empty_assisted_ai_projection),
            assist_inline_prediction_projection: self
                .assist_inline_prediction_projection(generated_at),
            delegated_task_projection,
            legion_workflow_projection,
            legion_workflow_board_columns,
            legion_workflow_fleet_card_projections,
            legion_workflow_comm_rows,
            legion_workflow_budget_rows,
            plugin_contribution_projections: self.plugin_contribution_projections.clone(),
            extension_catalog: self.extension_catalog.projection(),
            legion_cloud_lane: self.legion_cloud_lane_projection(),
            collaboration_presence_projections: self.collaboration.presence_projections(),
            collaboration_gui_projection: self.collaboration.gui_projection(),
            remote_gui_projection,
            daily_editing_projection: ProjectionBuilder::daily_editing_projection(
                &self.active_documents,
                &self.editor,
            ),
            excerpt_surface_projection: ProjectionBuilder::excerpt_surface_projection(
                &self.active_documents,
                &self.editor,
            ),
            search_projection: self.search_projection.clone(),
            structural_search_projection: self.structural_search_projection.clone(),
            git_projection: self.git_projection.clone(),
            debug_projection: self.debug_workflow.projection(),
            test_explorer_projection: self.test_explorer_projection.clone(),
            language_tooling_projection: {
                // D2: inject live LSP health records from the background session handle.
                // PKT-LSP-C T3: also inject session lifecycle status (backoff countdown etc).
                let mut p = self.language_tooling.projection();
                if let Some(record) = self.lsp_session.health_record() {
                    p.lsp_health_records.push(record);
                }
                let status = self.lsp_session.session_status_projection();
                if !matches!(
                    status.lifecycle,
                    legion_protocol::LspSessionLifecycleKind::Idle
                ) {
                    p.lsp_session_status = Some(status);
                }
                // PKT-LSP-C T4: inject redacted stderr ring-buffer projection.
                if let Some(log) = self.lsp_session.stderr_log_projection() {
                    p.lsp_session_log = Some(log);
                }
                p
            },
            terminal_panel_projection: self.terminal_workflow.projection(),
            find_bar_projection: legion_ui::ui::FindBarProjection {
                visible: self.buffer_search_state.find_bar_visible,
                query: self.buffer_search_state.query.clone(),
                replace_text: self.buffer_search_state.replace_text.clone(),
                replace_visible: self.buffer_search_state.replace_visible,
                case_sensitive: self.buffer_search_state.case_sensitive,
                whole_word: self.buffer_search_state.whole_word,
                use_regex: self.buffer_search_state.use_regex,
                match_count: self.buffer_search_state.matches.len(),
                current_match_index: self.buffer_search_state.current_match_index,
                matches: self
                    .buffer_search_state
                    .matches
                    .iter()
                    .map(|&(sl, sc, el, ec)| legion_ui::ui::FindMatchProjection {
                        start: TextCoordinate {
                            line: sl,
                            character: sc,
                            byte_offset: None,
                            utf16_offset: None,
                        },
                        end: TextCoordinate {
                            line: el,
                            character: ec,
                            byte_offset: None,
                            utf16_offset: None,
                        },
                    })
                    .collect(),
            },
        })
    }

